"use strict";(self.webpackChunkmy_til=self.webpackChunkmy_til||[]).push([["7387"],{7017(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/05/29/ubuntu-tomcat-jenkins","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/05/29/ubuntu-tomcat-jenkins","source":"@site/blog/2026-05-29-ubuntu-tomcat-jenkins.md","title":"[TIL] Ubuntu \uC11C\uBC84 \uAD6C\uCD95 + Tomcat \uBC30\uD3EC + Jenkins \uC124\uCE58\uAE4C\uC9C0","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.05.29","date":"2026-05-29T00:00:00.000Z","tags":[{"inline":true,"label":"Ubuntu","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/ubuntu"},{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"Tomcat","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/tomcat"},{"inline":true,"label":"Jenkins","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/jenkins"},{"inline":true,"label":"Linux","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/linux"},{"inline":true,"label":"CI/CD","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/ci-cd"}],"readingTime":3.42,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Ubuntu \uC11C\uBC84 \uAD6C\uCD95 + Tomcat \uBC30\uD3EC + Jenkins \uC124\uCE58\uAE4C\uC9C0","date":"2026-05-29T00:00:00.000Z","tags":["Ubuntu","Java","Tomcat","Jenkins","Linux","CI/CD"]},"unlisted":false,"nextItem":{"title":"[TIL] SQL \uAE30\uCD08 \uBB38\uBC95\uACFC DDL, DML, \uD398\uC774\uC9D5","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/12/sql-ddl-dml-paging"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.05.29\\n\\n## \u{1F5FA} \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n\uB85C\uCEEC\uC5D0\uC11C \uAC1C\uBC1C\uD55C \uC571\uC744 \uC2E4\uC81C \uC11C\uBC84\uC5D0 \uC62C\uB824\uC11C \uC678\uBD80\uC5D0\uC11C \uC811\uADFC \uAC00\uB2A5\uD558\uAC8C \uB9CC\uB4DC\uB294 \uC804\uCCB4 \uD750\uB984\uC744 \uC2E4\uC2B5\uD588\uB2E4.\\n\\n```\\nOS \uC900\uBE44 \u2192 Java \uC124\uCE58 \u2192 Tomcat 10 \u2192 systemd \uB4F1\uB85D \u2192 Jenkins CI/CD\\n(Ubuntu 22.04)  (OpenJDK 21)  (WAR \uBC30\uD3EC)  (\uC790\uB3D9 \uAE30\uB3D9)   (\uC790\uB3D9\uD654)\\n```\\n\\n---\\n\\n## 1\uFE0F\u20E3 \uC11C\uBC84 \uAD6C\uCD95 \uAE30\uBC18 \u2014 OS\uC640 SSH\\n\\n\uC11C\uBC84\uB294 \uB85C\uCEEC IDE \uC2E4\uD589\uACFC \uB2E4\uB974\uB2E4. \uC678\uBD80 \uC0AC\uC6A9\uC790\uAC00 \uC811\uADFC \uAC00\uB2A5\uD55C \uD658\uACBD\uC774 \uB3FC\uC57C \uD558\uAE30 \uB54C\uBB38\uC5D0 OS \uC124\uCE58, \uB124\uD2B8\uC6CC\uD06C, \uAD8C\uD55C \uAD00\uB9AC\uAC00 \uC804\uBD80 \uC5EE\uC5EC\uC788\uB2E4.\\n\\n:::info \uD074\uB77C\uC6B0\uB4DC vs \uC628\uD504\uB808\uBBF8\uC2A4\\nAWS, Azure \uAC19\uC740 \uD074\uB77C\uC6B0\uB4DC\uB294 \uC778\uD504\uB77C(IaaS)\uB97C \uBE4C\uB9AC\uB294 \uAC83. \uBCF4\uC548 \uC694\uAD6C\uAC00 \uB192\uC740 \uAE30\uC5C5\uC740 \uC9C1\uC811 \uC11C\uBC84\uB97C \uAD6C\uCD95\uD558\uB294 \uC628\uD504\uB808\uBBF8\uC2A4\uB97C \uC120\uD0DD\uD558\uAE30\uB3C4 \uD55C\uB2E4. \uC624\uB298 \uC2E4\uC2B5\uC740 \uB85C\uCEEC PC\uB97C \uC11C\uBC84\uCC98\uB7FC \uC368\uC11C \uC628\uD504\uB808\uBBF8\uC2A4 \uD750\uB984\uC744 \uACBD\uD5D8\uD558\uB294 \uBC29\uC2DD\uC774\uC5C8\uB2E4.\\n:::\\n\\n### SSH \uD0A4 \uAE30\uBC18 \uC778\uC99D\\n\\nID/PW \uBC29\uC2DD\uBCF4\uB2E4 \uD0A4 \uAE30\uBC18 \uC778\uC99D\uC774 \uC548\uC804\uD558\uB2E4. \uACF5\uAC1C\uD0A4\uB294 \uC11C\uBC84\uC5D0, \uAC1C\uC778\uD0A4\uB294 \uD074\uB77C\uC774\uC5B8\uD2B8\uC5D0 \uBCF4\uAD00\uD55C\uB2E4.\\n\\n| \uB2E8\uACC4 | \uBA85\uB839\uC5B4 | \uBAA9\uC801 |\\n|------|--------|------|\\n| \uD0A4 \uC0DD\uC131 | `ssh-keygen -t rsa -b 4096` | \uACF5\uAC1C\uD0A4/\uAC1C\uC778\uD0A4 \uC30D \uC0DD\uC131 |\\n| \uD0A4 \uC704\uCE58 | `~/.ssh/id_rsa.pub` | \uACF5\uAC1C\uD0A4 \uC11C\uBC84\uC5D0 \uB4F1\uB85D |\\n| PPK \uBCC0\uD658 | PuTTYgen | PuTTY \uC811\uC18D\uC6A9 \uBCC0\uD658 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `IaaS` `\uC628\uD504\uB808\uBBF8\uC2A4` `LTS` `CLI` `SSH`\\n\\n---\\n\\n## 2\uFE0F\u20E3 OpenJDK 21 \uC124\uCE58\uC640 \uD658\uACBD\uBCC0\uC218\\n\\n\uC624\uB77C\uD074 JDK\uB294 \uAE30\uC5C5 \uD658\uACBD\uC5D0\uC11C \uC720\uB8CC(\uCF54\uC5B4\uB2F9 \uACFC\uAE08)\uAC00 \uB420 \uC218 \uC788\uC5B4\uC11C OpenJDK\uB97C \uC4F0\uB294 \uAC8C \uC77C\uBC18\uC801\uC774\uB2E4. Spring Boot 3.x\uB294 Java 17 \uC774\uC0C1\uC744 \uC694\uAD6C\uD558\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC544\uC11C 21 LTS\uB97C \uC120\uD0DD\uD588\uB2E4.\\n\\n```bash\\n# \uD328\uD0A4\uC9C0 \uBAA9\uB85D \uC5C5\uB370\uC774\uD2B8 \uD6C4 \uC124\uCE58\\napt update && apt upgrade\\napt install openjdk-21-jdk\\n\\n# \uC124\uCE58 \uD655\uC778\\njava -version\\nfind / -name java\\n```\\n\\n### \uD658\uACBD\uBCC0\uC218 \uC124\uC815 \u2014 /etc/profile vs /etc/environment\\n\\n| \uD30C\uC77C | \uBAA9\uC801 | \uD615\uC2DD |\\n|------|------|------|\\n| `/etc/profile` | \uC258 \uC2DC\uC791 \uC2DC \uC804\uC5ED \uC124\uC815 | `export` \uC0AC\uC6A9, PATH \uD655\uC7A5\uC5D0 \uC801\uD569 |\\n| `/etc/environment` | \uC2DC\uC2A4\uD15C \uC804\uC5ED \uBCC0\uC218 \uC120\uC5B8 | `export` \uC5C6\uC774 `KEY=\\"VALUE\\"` |\\n\\n```bash\\n# \uC124\uC815 \uC989\uC2DC \uBC18\uC601\\nsource /etc/profile\\nsource /etc/environment\\n\\n# \uC801\uC6A9 \uD655\uC778\\necho $JAVA_HOME\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `OpenJDK` `JAVA_HOME` `PATH` `source` `Vim`\\n\\n---\\n\\n## 3\uFE0F\u20E3 Tomcat 10 \uC218\uB3D9 \uC124\uCE58\uC640 WAR \uBC30\uD3EC\\n\\n`apt`\uB85C \uC124\uCE58 \uAC00\uB2A5\uD55C \uBC84\uC804\uACFC \uC2E4\uC81C \uD544\uC694\uD55C \uBC84\uC804\uC774 \uB2E4\uB97C \uC218 \uC788\uC5B4\uC11C, \uC2E4\uBB34\uC5D0\uC11C\uB294 `tar.gz`\uB85C \uC9C1\uC811 \uC124\uCE58\uD55C\uB2E4.\\n\\n### \uC124\uCE58 \uC808\uCC28\\n\\n1. `wget`\uC73C\uB85C tar.gz \uB2E4\uC6B4\uB85C\uB4DC \uD6C4 `/tmp`\uC5D0 \uC555\uCD95 \uD574\uC81C\\n2. `/usr/local/tomcat10`\uC73C\uB85C \uC774\uB3D9 (\uC2E4\uD589\uD30C\uC77C\uC740 `/usr` \uACC4\uC5F4)\\n3. `chmod -R 755`\uC73C\uB85C \uD558\uC704\uAE4C\uC9C0 \uC2E4\uD589 \uAD8C\uD55C \uBD80\uC5EC\\n4. `CATALINA_HOME` \uD658\uACBD\uBCC0\uC218 \uC124\uC815\\n5. `tomcat-users.xml`\uC5D0\uC11C \uAD00\uB9AC\uC790 \uACC4\uC815 \uCD94\uAC00\\n6. `context.xml`\uC5D0\uC11C RemoteAddrValve \uC8FC\uC11D \uCC98\uB9AC (\uC678\uBD80 \uC811\uADFC \uD5C8\uC6A9)\\n\\n:::warning\\n`context.xml`\uC758 RemoteAddrValve \uC81C\uD55C \uD574\uC81C\uB294 \uBCF4\uC548\uC0C1 \uBBFC\uAC10\uD55C \uC124\uC815\uC774\uB2E4. \uC2E4\uBB34\uC5D0\uC11C\uB294 IP \uC81C\uD55C\uC744 \uC720\uC9C0\uD558\uACE0 \uD5C8\uC6A9 \uB300\uC0C1\uC744 \uCD5C\uC18C\uD654\uD558\uB294 \uAC8C \uC77C\uBC18\uC801\uC774\uB2E4.\\n:::\\n\\n```bash\\n# \uAE30\uB3D9 / \uC885\uB8CC\\n./bin/startup.sh\\n./bin/shutdown.sh\\n\\n# \uAE30\uB3D9 \uD655\uC778\\ncurl http://localhost:8080\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Tomcat` `CATALINA_HOME` `tomcat-users.xml` `context.xml` `WAR`\\n\\n---\\n\\n## 4\uFE0F\u20E3 systemd\uB85C Tomcat \uC11C\uBE44\uC2A4 \uB4F1\uB85D\\n\\n\uC218\uB3D9 \uC2E4\uD589\uC740 \uC11C\uBC84 \uC7AC\uBD80\uD305 \uD6C4 \uB9E4\uBC88 \uC0AC\uB78C\uC774 \uAE30\uB3D9\uD574\uC57C \uD574\uC11C \uC6B4\uC601\uC5D0 \uBD80\uC801\uD569\uD558\uB2E4. systemd\uC5D0 \uB4F1\uB85D\uD558\uBA74 \uBD80\uD305 \uC2DC \uC790\uB3D9 \uAE30\uB3D9\uB41C\uB2E4.\\n\\n### \uC11C\uBE44\uC2A4 \uC804\uC6A9 \uACC4\uC815 \uB9CC\uB4E4\uAE30\\n\\n```bash\\n# \uADF8\uB8F9 \uBC0F nologin \uACC4\uC815 \uC0DD\uC131\\ngroupadd tomcat\\nuseradd -s /bin/nologin -g tomcat -d /usr/local/tomcat10 tomcat\\n\\n# \uC18C\uC720\uAD8C \uC774\uC804 (chmod: \uAD8C\uD55C\uBE44\uD2B8 \uBCC0\uACBD / chown: \uC18C\uC720\uC790 \uBCC0\uACBD)\\nchown -PR tomcat:tomcat /usr/local/tomcat10\\n```\\n\\n:::info\\n`nologin` \uACC4\uC815\uC740 \uB300\uD654\uD615 \uB85C\uADF8\uC778\uC774 \uBD88\uAC00\uB2A5\uD55C \uC11C\uBE44\uC2A4 \uC804\uC6A9 \uACC4\uC815\uC774\uB2E4. \uBCF4\uC548\uC744 \uC704\uD574 \uC11C\uBE44\uC2A4\uB294 \uC804\uC6A9 \uACC4\uC815\uC73C\uB85C \uC2E4\uD589\uD55C\uB2E4.\\n:::\\n\\n### \uC11C\uBE44\uC2A4 \uD30C\uC77C \uD575\uC2EC \uAD6C\uC131\\n\\n| \uD56D\uBAA9 | \uC758\uBBF8 |\\n|------|------|\\n| `User, Group` | \uC11C\uBE44\uC2A4 \uC2E4\uD589 \uACC4\uC815/\uADF8\uB8F9 (tomcat) |\\n| `Environment` | JAVA_HOME, CATALINA_HOME \uACBD\uB85C |\\n| `ExecStart/ExecStop` | \uAE30\uB3D9/\uC885\uB8CC \uC2A4\uD06C\uB9BD\uD2B8 \uC5F0\uACB0 |\\n| `WantedBy` | `multi-user.target` (\uBD80\uD305 \uB2E8\uACC4 \uC5F0\uACB0) |\\n\\n```bash\\n# \uC11C\uBE44\uC2A4 \uB4F1\uB85D \uBC0F \uAD00\uB9AC\\nsystemctl daemon-reload\\nsystemctl enable tomcat10.service\\nsystemctl start tomcat10.service\\nsystemctl status tomcat10.service\\n\\n# \uD3EC\uD2B8 \uC810\uC720 \uD655\uC778 (-l \uB9AC\uC2A4\uB2DD -n \uC22B\uC790 -t TCP -p \uD504\uB85C\uC138\uC2A4)\\nss -lntp\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `systemd` `systemctl` `useradd` `chown` `ss`\\n\\n---\\n\\n## 5\uFE0F\u20E3 Jenkins \uC124\uCE58\uC640 \uD3EC\uD2B8 \uCDA9\uB3CC \uD574\uACB0\\n\\nJenkins\uB294 Git push \uC774\uBCA4\uD2B8\uB97C \uBC1B\uC544 \uC18C\uC2A4 \uCCB4\uD06C\uC544\uC6C3 \u2192 \uBE4C\uB4DC \u2192 \uBC30\uD3EC\uB97C \uC790\uB3D9\uD654\uD558\uB294 CI \uC11C\uBC84\uB2E4. \uC124\uCE58 \uD6C4 Tomcat(8080)\uACFC \uD3EC\uD2B8 \uCDA9\uB3CC\uC774 \uBC1C\uC0DD\uD574\uC11C 8181\uB85C \uBCC0\uACBD\uD588\uB2E4.\\n\\n```\\nGit push \u2192 (webhook) \u2192 Jenkins \u2192 (Maven \uBE4C\uB4DC) \u2192 WAR \uC0DD\uC131 \u2192 Tomcat \uBC30\uD3EC \u2192 \uC11C\uBE44\uC2A4\\n```\\n\\n### \uD3EC\uD2B8 \uCDA9\uB3CC \uD574\uACB0 \uD3EC\uC778\uD2B8\\n\\n:::danger \uD575\uC2EC\\n`/etc/default/jenkins`\uC640 systemd \uC11C\uBE44\uC2A4 \uD30C\uC77C **\uB450 \uACF3 \uBAA8\uB450** \uD3EC\uD2B8\uB97C \uC77C\uCE58\uC2DC\uCF1C\uC57C \uD55C\uB2E4. \uD55C \uACF3\uB9CC \uBC14\uAFB8\uBA74 \uC801\uC6A9\uC774 \uC548 \uB41C\uB2E4.\\n:::\\n\\n```bash\\n# \uB450 \uACF3 \uB2E4 8181\uB85C \uBCC0\uACBD \uD544\uC694\\n# 1. /etc/default/jenkins \u2192 HTTP_PORT=8181\\n# 2. jenkins.service \u2192 JENKINS_PORT=8181\\n\\nsystemctl daemon-reload\\nsystemctl start jenkins\\nsystemctl status jenkins\\n```\\n\\n### Jenkins \uCD08\uAE30 \uC124\uC815 \uC21C\uC11C\\n\\n1. `http://localhost:8181` \uC811\uC18D\\n2. `cat <initialAdminPassword \uACBD\uB85C>` \uB85C \uCD08\uAE30 \uBE44\uBC88 \uD655\uC778\\n3. Install suggested plugins \uC120\uD0DD\\n4. \uAD00\uB9AC\uC790 \uACC4\uC815 \uC0DD\uC131 (\uAF2D \uD574\uC57C \uC774\uD6C4 \uC124\uC815\uC774 \uD3B8\uD568)\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Jenkins` `CI` `\uD3EC\uD2B8 \uCDA9\uB3CC` `systemd` `GitHub Actions`\\n\\n---\\n\\n## \u{1F51C} \uB2E4\uC74C\uC5D0 \uC774\uC5B4\uC9C8 \uB0B4\uC6A9\\n\\n\uC624\uB298 Jenkins \uCD08\uAE30 \uC124\uC815 \uD654\uBA74\uAE4C\uC9C0 \uC9C4\uD589\uD588\uACE0, \uB2E4\uC74C\uC5D0\uB294 \uC774\uAC78 \uC774\uC5B4\uC11C \uC9C4\uD589\uD560 \uC608\uC815\uC774\uB2E4.\\n\\n- Docker \uC124\uCE58\\n- ngrok\uC73C\uB85C \uC678\uBD80 \uC811\uADFC (\uD3EC\uD2B8\uD3EC\uC6CC\uB529 \uB300\uCCB4)\\n- Git \uC5F0\uB3D9 \u2192 CI/CD \uD30C\uC774\uD504\uB77C\uC778 \uC644\uC131"},{"id":"/2026/03/12/sql-ddl-dml-paging","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/12/sql-ddl-dml-paging","source":"@site/blog/2026-03-12-sql-ddl-dml-paging.md","title":"[TIL] SQL \uAE30\uCD08 \uBB38\uBC95\uACFC DDL, DML, \uD398\uC774\uC9D5","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.12","date":"2026-03-12T00:00:00.000Z","tags":[{"inline":true,"label":"Oracle","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/oracle"},{"inline":true,"label":"SQL","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/sql"},{"inline":true,"label":"DDL","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/ddl"},{"inline":true,"label":"DML","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/dml"},{"inline":true,"label":"ROWNUM","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/rownum"},{"inline":true,"label":"\uD398\uC774\uC9D5","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uD398\uC774\uC9D5"}],"readingTime":3.94,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] SQL \uAE30\uCD08 \uBB38\uBC95\uACFC DDL, DML, \uD398\uC774\uC9D5","date":"2026-03-12T00:00:00.000Z","tags":["Oracle","SQL","DDL","DML","ROWNUM","\uD398\uC774\uC9D5"]},"unlisted":false,"prevItem":{"title":"[TIL] Ubuntu \uC11C\uBC84 \uAD6C\uCD95 + Tomcat \uBC30\uD3EC + Jenkins \uC124\uCE58\uAE4C\uC9C0","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/05/29/ubuntu-tomcat-jenkins"},"nextItem":{"title":"[TIL] Oracle DB \uD658\uACBD\uAD6C\uCD95\uACFC SQL \uAE30\uCD08","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/11/oracle-sql-basics"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.12\\n\\n## \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\nIN \uC5F0\uC0B0\uC790/\uC6B0\uC120\uC21C\uC704 \u2192 DISTINCT/NULL \u2192 DDL/\uC81C\uC57D\uC870\uAC74\\n\u2192 DML (INSERT/UPDATE/DELETE) \u2192 WHERE \uC2EC\uD654 (LIKE/BETWEEN/NULL)\\n\u2192 NULL \uC5F0\uC0B0/NVL \u2192 ROWNUM \uD398\uC774\uC9D5\\n```\\n\\n---\\n\\n## 1. IN \uC5F0\uC0B0\uC790\uC640 \uC5F0\uC0B0\uC790 \uC6B0\uC120\uC21C\uC704\\n\\n`IN` = \uBC18\uBCF5\uB418\uB294 OR \uC870\uAC74\uC744 \uAC04\uACB0\uD558\uAC8C \uD45C\uD604.\\n\\n```sql\\n-- \uAE30\uC874 OR \uBC29\uC2DD\\nWHERE empno = 7369 OR empno = 7499\\n\\n-- IN\uC73C\uB85C \uCD95\uC57D\\nWHERE empno IN (7369, 7499)\\n```\\n\\n### \uC5F0\uC0B0\uC790 \uC6B0\uC120\uC21C\uC704\\n\\n```\\n\uAD04\uD638 > SQL \uC5F0\uC0B0\uC790(IN, BETWEEN \uB4F1) > AND > OR\\n```\\n\\n```sql\\n-- \uC758\uB3C4\uAC00 \uBD88\uBA85\uD655\uD55C \uD615\uD0DC\\nWHERE empno = 7499 OR job = \'SALESMAN\' AND empno = 7369;\\n\\n-- \uAD04\uD638\uB85C \uC758\uB3C4 \uBA85\uD655\uD788\\nWHERE (empno = 7499 OR job = \'SALESMAN\') AND empno = 7369;\\n```\\n\\n### \uD29C\uD50C IN (\uC2DC\uD5D8 \uBE48\uCD9C)\\n\\n```sql\\n-- OR/AND \uC804\uAC1C \uD615\uD0DC\\nWHERE (empno=7369 AND job=\'CLERK\') OR (empno=7566 AND job=\'MANAGER\')\\n\\n-- \uD29C\uD50C IN \uCD95\uC57D\\nWHERE (empno, job) IN ((7369,\'CLERK\'), (7566,\'MANAGER\'))\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `IN` `AND` `OR` `\uAD04\uD638` `\uD29C\uD50C IN`\\n\\n---\\n\\n## 2. DISTINCT\uC640 NULL\uC758 \uC911\uBCF5 \uCC98\uB9AC\\n\\nDISTINCT \uAE30\uC900 = SELECT\uC5D0 \uC120\uD0DD\uB41C **\uCEEC\uB7FC \uC870\uD569**.\\n\\n| SELECT \uD615\uD0DC | \uC911\uBCF5 \uC81C\uAC70 \uAE30\uC900 |\\n|------------|--------------|\\n| `DISTINCT c1` | c1 \uAC12 \uB2E8\uB3C5 |\\n| `DISTINCT c1, c2` | (c1, c2) \uC870\uD569 |\\n| `DISTINCT c1, c2, c3` | (c1, c2, c3) \uC870\uD569 \u2192 \uB354 \uB9CE\uC774 \uB0A8\uC74C |\\n\\n:::info\\nDB\uC5D0\uC11C NULL\uC740 \\"\uC5C6\uC74C\\"\uC774 \uC544\uB2C8\uB77C **\\"\uBBF8\uC9C0\uC758 \uAC12\\"**.\\n\\n`DISTINCT` \uACB0\uACFC\uC5D0 NULL\uB3C4 \uBCC4\uB3C4\uC758 \uD55C \uD56D\uBAA9\uC73C\uB85C \uD3EC\uD568\uB420 \uC218 \uC788\uB2E4.\\n:::\\n\\n:::warning\\n\uC2E4\uBB34\uC5D0\uC11C\uB294 PK \uAE30\uBC18 \uC870\uC778 \uAD6C\uC870\uAC00 \uB9CE\uC544 `DISTINCT` \uB0A8\uC6A9\uC740 \uC9C0\uC591.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `DISTINCT` `\uC911\uBCF5 \uC81C\uAC70` `NULL` `SELECT \uC870\uD569` `\uC870\uD569 \uC911\uBCF5`\\n\\n---\\n\\n## 3. DDL\uACFC \uC81C\uC57D\uC870\uAC74 (Constraint)\\n\\n| \uC81C\uC57D\uC870\uAC74 | \uC758\uBBF8 | \uC2E4\uBB34 \uD3EC\uC778\uD2B8 |\\n|---------|------|------------|\\n| `NOT NULL` | \uD544\uC218 \uC785\uB825 | \uD544\uC218\uAC12 \uB204\uB77D\uC744 DB\uC5D0\uC11C \uCC28\uB2E8 |\\n| `PRIMARY KEY` | \uC720\uC77C \uC2DD\uBCC4 | UNIQUE + NOT NULL \uC131\uACA9 |\\n| `FOREIGN KEY` | \uBD80\uBAA8 PK \uCC38\uC870 | \uBB34\uACB0\uC131 \uC704\uBC18\uC758 \uC8FC\uC694 \uC6D0\uC778 |\\n| `UNIQUE` | \uC720\uC77C\uC131 \uAC15\uC81C | NULL\uC740 \uD5C8\uC6A9 |\\n| `CHECK` | \uD5C8\uC6A9 \uBC94\uC704 \uC81C\uD55C | IF\uBB38\uCC98\uB7FC \uD5C8\uC6A9\uAC12 \uD1B5\uC81C |\\n| `DEFAULT` | \uBBF8\uC785\uB825 \uC2DC \uAE30\uBCF8\uAC12 | \uCEEC\uB7FC\uC744 INSERT \uB300\uC0C1\uC5D0\uC11C \uC81C\uC678\uD560 \uB54C \uC801\uC6A9 |\\n\\n```sql\\n-- DEFAULT \uC801\uC6A9\\nALTER TABLE user_info MODIFY (role DEFAULT \'U\');\\n```\\n\\n:::info\\nDDL \uD575\uC2EC \uD750\uB984: \uC694\uAD6C\uBD84\uC11D(\uD55C\uAE00) \u2192 \uD14C\uC774\uBE14 \uC124\uACC4(ERD) \u2192 CREATE TABLE \uAD6C\uD604\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `DDL` `CONSTRAINT` `ALTER TABLE` `DEFAULT` `FOREIGN KEY`\\n\\n---\\n\\n## 4. DML (INSERT, UPDATE, DELETE)\uACFC \uBB34\uACB0\uC131\\n\\n### INSERT\\n\\n| \uAD6C\uBD84 | \uD615\uD0DC | \uD2B9\uC9D5 |\\n|------|------|------|\\n| \uC554\uBB35\uC801 | `INSERT INTO t VALUES (...)` | \uCEEC\uB7FC \uC21C\uC11C/\uD0C0\uC785/\uAC1C\uC218 \uBAA8\uB450 \uB9DE\uCDB0\uC57C \uD568 |\\n| \uBA85\uC2DC\uC801 | `INSERT INTO t(c1,c2) VALUES (...)` | \uD544\uC694\uD55C \uCEEC\uB7FC\uB9CC \uC120\uD0DD \uAC00\uB2A5 (\uAD8C\uC7A5) |\\n\\n### \uBB34\uACB0\uC131 \uC21C\uC11C \uADDC\uCE59\\n\\n```\\n\uD14C\uC774\uBE14 \uC0DD\uC131: \uBD80\uBAA8 \uBA3C\uC800 \u2192 \uC790\uC2DD\\n\uAC12 \uC785\uB825:    \uBD80\uBAA8(PK) \uBA3C\uC800 \u2192 \uC790\uC2DD(FK)\\n\uB85C\uC6B0 \uC0AD\uC81C:  \uC790\uC2DD \uBA3C\uC800 \u2192 \uBD80\uBAA8\\n```\\n\\n:::danger\\nFK\uAC00 \uC5C6\uB294 \uAC12\uC73C\uB85C \uC790\uC2DD INSERT \uC2DC\uB3C4 \u2192 \\"\uBD80\uBAA8\uD0A4\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4\\" \uBB34\uACB0\uC131 \uC624\uB958 \uBC1C\uC0DD.\\n\\n`WHERE` \uC5C6\uC774 `UPDATE` \uC2E4\uD589 \uC2DC \uC804\uCCB4 \uD589 \uBCC0\uACBD \uC704\uD5D8 \u2014 \uBC18\uB4DC\uC2DC \uC870\uAC74 \uD3EC\uD568.\\n:::\\n\\n### DELETE vs TRUNCATE\\n\\n| \uAD6C\uBD84 | \uBCF5\uAD6C | \uC18D\uB3C4 | \uBD84\uB958 |\\n|------|------|------|------|\\n| `DELETE` | \uAC00\uB2A5 (\uB85C\uADF8/\uBC84\uD37C) | \uB290\uB9BC | DML |\\n| `TRUNCATE` | \uB9E4\uC6B0 \uC5B4\uB824\uC6C0 | \uBE60\uB984 | DDL |\\n\\n:::info\\n`DEFAULT`\uB294 \uCEEC\uB7FC\uC744 INSERT \uB300\uC0C1\uC5D0\uC11C **\uC81C\uC678**\uD588\uC744 \uB54C \uC801\uC6A9.\\n\\n\uBE48 \uBB38\uC790\uC5F4 \uC785\uB825 \uC2DC DB\uAC00 \uC774\uB97C NULL\uB85C \uCC98\uB9AC\uD558\uB294 \uACBD\uC6B0 \uC788\uC74C.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `INSERT` `UPDATE` `DELETE` `\uBB34\uACB0\uC131 \uC81C\uC57D` `DEFAULT`\\n\\n---\\n\\n## 5. WHERE \uC808 \uC2EC\uD654: LIKE, BETWEEN, \uBD80\uC815, NULL\\n\\n### LIKE \uC640\uC77C\uB4DC\uCE74\uB4DC\\n\\n| \uD328\uD134 | \uC758\uBBF8 | \uBE44\uACE0 |\\n|------|------|------|\\n| `LIKE \'\uC0BC\uC131%\'` | \uC0BC\uC131\uC73C\uB85C \uC2DC\uC791 | \uBE44\uAD50\uC801 \uC0AC\uC6A9 \uAC00\uB2A5 |\\n| `LIKE \'%\uBE14\uB8E8%\'` | \uBE14\uB8E8\uB97C \uD3EC\uD568 | \uBC94\uC704 \uB113\uC5B4 \uBD80\uD558 \uD07C |\\n| `LIKE \'\uB4DC\uB808__\'` | \uB4DC\uB808 + \uC784\uC758 2\uAE00\uC790 | `_` = \uC784\uC758 1\uAE00\uC790 |\\n| `LIKE \'%\uC804\uB0A8\'` | \uC804\uB0A8\uC73C\uB85C \uB05D | \uC120\uD589 \uC640\uC77C\uB4DC\uCE74\uB4DC \u2014 \uBE44\uAD8C\uC7A5 |\\n\\n:::warning\\n\uC120\uD589 \uC640\uC77C\uB4DC\uCE74\uB4DC(`%abc`)\uB294 \uC778\uB371\uC2A4 \uD65C\uC6A9 \uC5B4\uB824\uC6C0 \u2192 \uC131\uB2A5 \uBD80\uD558 \uC8FC\uC758.\\n:::\\n\\n### BETWEEN\\n\\n```sql\\nWHERE sal BETWEEN 1000 AND 3000  -- \uC774\uC0C1/\uC774\uD558 \uD3EC\uD568\\n```\\n\\n:::danger\\n\uBC18\uB4DC\uC2DC **\uC791\uC740 \uAC12 AND \uD070 \uAC12** \uC21C\uC11C \u2014 \uBC18\uB300\uB85C \uC4F0\uBA74 \uACB0\uACFC \uC5C6\uC74C.\\n:::\\n\\n### NULL \uBE44\uAD50\\n\\n```sql\\n-- \uC798\uBABB\uB41C \uBC29\uC2DD (\uACB0\uACFC \uD56D\uC0C1 \uACF5\uC9D1\uD569)\\nWHERE comm = NULL\\n\\n-- \uC62C\uBC14\uB978 \uBC29\uC2DD\\nWHERE comm IS NULL\\nWHERE comm IS NOT NULL\\n```\\n\\n:::danger\\nNULL \uBE44\uAD50\uB294 `=`\uB85C \uC808\uB300 \uBD88\uAC00 \u2014 \uBC18\uB4DC\uC2DC `IS NULL` / `IS NOT NULL` \uC0AC\uC6A9.\\n\\n\\"\uACF5\uC9D1\uD569(\uB85C\uC6B0\uAC00 \uC5C6\uC74C)\\"\uACFC \\"NULL \uCEEC\uB7FC(\uB85C\uC6B0\uB294 \uC788\uC73C\uB098 \uAC12\uC774 NULL)\\"\uC740 \uC644\uC804\uD788 \uB2E4\uB978 \uACB0\uACFC.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `LIKE` `BETWEEN` `IS NULL` `\uB4DC\uBAA8\uB974\uAC04` `\uC778\uB371\uC2A4`\\n\\n---\\n\\n## 6. NULL \uC5F0\uC0B0, NVL, ROWNUM \uD398\uC774\uC9D5\\n\\n### NULL \uC5F0\uC0B0\uACFC NVL\\n\\n```sql\\n-- comm\uC774 NULL\uC774\uBA74 \uACB0\uACFC\uB3C4 NULL\\nSELECT ename, sal, comm + 100 FROM emp;\\n\\n-- NVL\uB85C NULL\uC744 0\uC73C\uB85C \uCE58\uD658\\nSELECT ename, sal, NVL(comm, 0) + 100 AS bonus_sal FROM emp;\\n```\\n\\n### ROWNUM \uD398\uC774\uC9D5\\n\\n:::warning\\n`ROWNUM`\uC740 FROM \uC808\uC5D0\uC11C \uC77D\uD600 \uB098\uC628 \uC21C\uC11C\uB85C \uBC88\uD638 \uBD80\uC5EC.\\n\\n`ROWNUM = 2` \uCC98\uB7FC 1\uC774 \uC0DD\uC131\uB418\uC9C0 \uC54A\uC73C\uBA74 \uB2E4\uC74C \uBC88\uD638\uAC00 \uB098\uC624\uC9C0 \uC54A\uB294 \uD2B9\uC131 \uC788\uC74C.\\n\\n`ORDER BY`\uC640 \uACB0\uD569 \uC2DC \uC6D0\uD558\uB294 \uACB0\uACFC\uB97C \uC5BB\uC73C\uB824\uBA74 \uC778\uB77C\uC778 \uBDF0(\uC11C\uBE0C\uCFFC\uB9AC) \uD544\uC694.\\n:::\\n\\n```sql\\n-- \uC798\uBABB\uB41C \uC811\uADFC (\uC815\uB82C \uC804 ROWNUM \uC801\uC6A9)\\nSELECT * FROM emp WHERE rownum <= 3 ORDER BY sal DESC;\\n\\n-- \uC62C\uBC14\uB978 \uC811\uADFC (\uC778\uB77C\uC778 \uBDF0\uB85C \uC815\uB82C \uD6C4 ROWNUM \uC801\uC6A9)\\nSELECT * FROM (\\n    SELECT * FROM emp ORDER BY sal DESC\\n) WHERE rownum <= 3;\\n```\\n\\n| \uD398\uC774\uC9D5 \uBC29\uC2DD | DB |\\n|-----------|-----|\\n| `ROWNUM` + \uC778\uB77C\uC778 \uBDF0 | Oracle (\uACE0\uC804) |\\n| `OFFSET` | Oracle (\uCD5C\uC2E0) |\\n| `LIMIT` | MySQL, PostgreSQL |\\n| `Pageable` | JPA |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `NULL \uC5F0\uC0B0` `NVL` `CONCAT` `ROWNUM` `\uC778\uB77C\uC778 \uBDF0`\\n\\n---\\n\\n## \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. `IN` = \uBC18\uBCF5 OR \uCD95\uC57D, \uD29C\uD50C IN\uC73C\uB85C \uBCF5\uD569 \uC870\uAC74 \uCD95\uC57D \uAC00\uB2A5\\n2. AND\uAC00 OR\uBCF4\uB2E4 \uBA3C\uC800 \uD3C9\uAC00 \u2192 \uBCF5\uD569 \uC870\uAC74\uC740 \uAD04\uD638 \uD544\uC218\\n3. `DISTINCT` \uAE30\uC900 = SELECT \uCEEC\uB7FC **\uC870\uD569** / NULL\uB3C4 \uD558\uB098\uC758 \uD56D\uBAA9\uC73C\uB85C \uD3EC\uD568\\n4. DEFAULT = \uCEEC\uB7FC\uC744 INSERT \uB300\uC0C1\uC5D0\uC11C **\uC81C\uC678**\uD574\uC57C \uC801\uC6A9\\n5. DML \uBB34\uACB0\uC131 \uC21C\uC11C: \uBD80\uBAA8 \uBA3C\uC800 \uC0DD\uC131/\uC785\uB825, \uC790\uC2DD \uBA3C\uC800 \uC0AD\uC81C\\n6. NULL \uBE44\uAD50\uB294 `IS NULL` / `IS NOT NULL` \uB9CC \uC0AC\uC6A9\\n7. ROWNUM \uD398\uC774\uC9D5 = \uC815\uB82C\uC744 \uC778\uB77C\uC778 \uBDF0\uB85C \uAC10\uC2FC \uD6C4 \uBC14\uAE65\uC5D0\uC11C ROWNUM \uC870\uAC74 \uC801\uC6A9"},{"id":"/2026/03/11/oracle-sql-basics","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/11/oracle-sql-basics","source":"@site/blog/2026-03-11-oracle-sql-basics.md","title":"[TIL] Oracle DB \uD658\uACBD\uAD6C\uCD95\uACFC SQL \uAE30\uCD08","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.11","date":"2026-03-11T00:00:00.000Z","tags":[{"inline":true,"label":"Oracle","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/oracle"},{"inline":true,"label":"SQL","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/sql"},{"inline":true,"label":"DBeaver","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/d-beaver"},{"inline":true,"label":"DDL","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/ddl"},{"inline":true,"label":"DCL","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/dcl"},{"inline":true,"label":"SELECT","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/select"},{"inline":true,"label":"JOIN","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/join"}],"readingTime":3.45,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Oracle DB \uD658\uACBD\uAD6C\uCD95\uACFC SQL \uAE30\uCD08","date":"2026-03-11T00:00:00.000Z","tags":["Oracle","SQL","DBeaver","DDL","DCL","SELECT","JOIN"]},"unlisted":false,"prevItem":{"title":"[TIL] SQL \uAE30\uCD08 \uBB38\uBC95\uACFC DDL, DML, \uD398\uC774\uC9D5","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/12/sql-ddl-dml-paging"},"nextItem":{"title":"[TIL] Java \uB78C\uB2E4, \uC2A4\uD2B8\uB9BC, Maven, JUnit \uC815\uB9AC","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/10/java-lambda-stream-maven-junit"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.11\\n\\n## \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\nOracle \uC124\uCE58/\uC811\uC18D \uC810\uAC80 \u2192 DBeaver \uD658\uACBD \uAD6C\uC131 \u2192 \uC778\uCF54\uB529 \uC124\uC815\\n\u2192 DB \uD559\uC2B5 \uBAA9\uD45C \u2192 DDL/DCL \uC2E4\uC2B5 \u2192 \uC0D8\uD50C \uB370\uC774\uD130 \uC801\uC7AC\\n\u2192 SELECT \uAE30\uBCF8 \u2192 \uB530\uC634\uD45C \uADDC\uCE59 \u2192 \uC54C\uB9AC\uC544\uC2A4 \u2192 JOIN \uAE30\uCD08 \u2192 WHERE \uC870\uAC74\\n```\\n\\n---\\n\\n## 1. Oracle \uC124\uCE58 \uBC0F \uC811\uC18D \uC810\uAC80\\n\\n**Windows**: `sqlplus -v`\uB85C \uBC84\uC804 \uD655\uC778 (12 \uC774\uC0C1\uC774\uBA74 \uC2E4\uC2B5 \uAC00\uB2A5)\\n\\n**macOS**: Docker \uCEE8\uD14C\uC774\uB108 \uB0B4\uBD80\uC5D0\uC11C \uD655\uC778\\n\\n```bash\\ndocker ps\\ndocker exec -it <\uCEE8\uD14C\uC774\uB108ID> /bin/bash\\nsqlplus -v\\n```\\n\\n:::warning\\n**Oracle \uC124\uCE58 \uC2E4\uD328 \uC8FC\uC694 \uC6D0\uC778**: PC \uC774\uB984/\uACC4\uC815\uBA85\uC5D0 \uD55C\uAE00, \uACF5\uBC31, \uD2B9\uC218\uBB38\uC790 \uD3EC\uD568.\\n\\n\uD574\uACB0: \uC601\uBB38 PC \uC774\uB984\uC73C\uB85C \uBCC0\uACBD\uC774 \uAC00\uC7A5 \uB2E8\uC21C.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `SQL*Plus` `docker exec` `\uC6D0\uACA9\uC811\uC18D(IP)` `\uC544\uD0A4\uD14D\uCC98(\uC778\uD154/ARM)`\\n\\n---\\n\\n## 2. DBeaver \uD658\uACBD \uAD6C\uC131\\n\\n| \uAD6C\uBD84 | \uD615\uD0DC | \uD2B9\uC9D5 |\\n|------|------|------|\\n| Standalone | \uB3C5\uB9BD \uC2E4\uD589\uD615 \uC571 | \uC124\uCE58 \uB2E8\uC21C, \uBC14\uB85C \uC0AC\uC6A9 \uAC00\uB2A5 |\\n| Plugin | Eclipse \uD50C\uB7EC\uADF8\uC778 | \uC6CC\uD06C\uC2A4\uD398\uC774\uC2A4/\uD504\uB85C\uC81D\uD2B8 \uC5F0\uB3D9 |\\n\\n:::info\\nEclipse \uD50C\uB7EC\uADF8\uC778 \uBC29\uC2DD: \uC6CC\uD06C\uC2A4\uD398\uC774\uC2A4\uB97C DB \uC804\uC6A9\uC73C\uB85C \uBD84\uB9AC\uD574 \uD504\uB85C\uC81D\uD2B8 \uB2E8\uC704 \uAD00\uB9AC.\\n\\nSQL \uD30C\uC77C\uC774 DB\uC5D0 \uC5F0\uACB0\uB418\uC9C0 \uC54A\uC740 \uC0C1\uD0DC\uC5D0\uC11C\uB294 \uC2E4\uD589 \uBD88\uAC00 \u2014 **\uC5F0\uACB0\uB41C SQL \uD3B8\uC9D1\uAE30**\uB85C \uC5F4\uC5B4\uC57C \uD568.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `DBeaver` `Eclipse \uD50C\uB7EC\uADF8\uC778` `\uC6CC\uD06C\uC2A4\uD398\uC774\uC2A4` `\uD37C\uC2A4\uD399\uD2F0\uBE0C` `GUI`\\n\\n---\\n\\n## 3. DB \uD559\uC2B5 \uBAA9\uD45C\uC640 SQL \uBD84\uB958\\n\\n\uCD5C\uC885 \uBAA9\uD45C: \uC694\uAD6C\uC0AC\uD56D \uBD84\uC11D \u2192 \uC5D4\uD2F0\uD2F0 \uCD94\uCD9C \u2192 **ERD \uBAA8\uB378\uB9C1** \u2192 DDL/DML \uC218\uD589\\n\\n| \uBD84\uB958 | \uC758\uBBF8 | \uB300\uD45C \uBA85\uB839 |\\n|------|------|----------|\\n| DDL | \uC815\uC758\uC5B4 | `CREATE`, `ALTER`, `DROP` |\\n| DML | \uC870\uC791\uC5B4 | `SELECT`, `INSERT`, `UPDATE`, `DELETE` |\\n| DCL | \uC81C\uC5B4\uC5B4 | `GRANT`, `REVOKE` |\\n| TCL | \uD2B8\uB79C\uC7AD\uC158 \uC81C\uC5B4 | `COMMIT`, `ROLLBACK` |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `ERD` `\uBAA8\uB378\uB9C1` `\uC694\uAD6C\uC0AC\uD56D\uBD84\uC11D` `\uC5D4\uD2F0\uD2F0\uCD94\uCD9C` `DDL/DML/DCL/TCL`\\n\\n---\\n\\n## 4. DDL, DCL \uC2E4\uC2B5: \uACC4\uC815/\uAD8C\uD55C/\uD504\uB85C\uD30C\uC77C\\n\\n```sql\\n-- \uBE44\uBC00\uBC88\uD638 \uB9CC\uB8CC \uC815\uCC45 \uBB34\uD55C\uC73C\uB85C \uBCC0\uACBD\\nALTER PROFILE DEFAULT LIMIT PASSWORD_LIFE_TIME UNLIMITED;\\n\\n-- \uC0AC\uC6A9\uC790 \uC0DD\uC131 \uBC0F \uAD8C\uD55C \uBD80\uC5EC\\nCREATE USER EDU IDENTIFIED BY EDU;\\nGRANT DBA, RESOURCE, CONNECT TO EDU;\\n\\n-- Oracle 21c \uC774\uC0C1: C## \uC811\uB450\uC5B4 \uC694\uAD6C \uC644\uD654\\nALTER SESSION SET \\"_ORACLE_SCRIPT\\" = TRUE;\\n\\n-- \uD14C\uC774\uBE14\uC2A4\uD398\uC774\uC2A4 \uBC0F \uCFFC\uD130 \uC124\uC815 (\uC120\uD0DD)\\nALTER USER EDU DEFAULT TABLESPACE USERS QUOTA UNLIMITED ON USERS;\\n\\n-- \uC2DC\uC2A4\uD15C \uCE74\uD0C8\uB85C\uADF8 \uC870\uD68C\\nSELECT USERNAME FROM DBA_USERS;\\nSELECT FILE_NAME, TABLESPACE_NAME FROM DBA_DATA_FILES;\\n```\\n\\n:::info\\n\uC0AC\uC6A9\uC790 \uC0DD\uC131\uB9CC\uC73C\uB85C\uB294 \uC811\uC18D \uBD88\uAC00 \u2014 \uBC18\uB4DC\uC2DC \uAD8C\uD55C(CONNECT \uB4F1) \uBD80\uC5EC \uD544\uC694.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `CREATE USER` `GRANT` `ALTER PROFILE` `TABLESPACE` `DBF`\\n\\n---\\n\\n## 5. \uC0D8\uD50C \uB370\uC774\uD130 \uC801\uC7AC\\n\\n```bash\\n# SQL*Plus\uC5D0\uC11C \uC2A4\uD06C\uB9BD\uD2B8 \uC2E4\uD589\\nsqlplus EDU/EDU\\nshow user\\n@C:\\\\TEMP\\\\EMP.sql\\n@C:\\\\TEMP\\\\FOOTBALL.sql\\n```\\n\\n:::warning\\n\uC2E4\uD589 \uD6C4 \uD14C\uC774\uBE14\uC774 \uBCF4\uC774\uC9C0 \uC54A\uC73C\uBA74 **Refresh(F5)**\uB85C \uBA54\uD0C0\uB370\uC774\uD130 \uAC31\uC2E0.\\n\\n\\"\uC774\uBBF8 \uAC1D\uCCB4\uAC00 \uC874\uC7AC\uD568\\" \uC624\uB958 = \uC911\uBCF5 \uC2E4\uD589 \u2192 \uAE30\uC874 \uAC1D\uCCB4 DROP \uD6C4 \uC7AC\uC2E4\uD589.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC0D8\uD50C\uB370\uC774\uD130` `\uC2A4\uD06C\uB9BD\uD2B8 \uC2E4\uD589` `@\uACBD\uB85C` `\uC774\uD589 \uC2A4\uD06C\uB9BD\uD2B8` `Refresh`\\n\\n---\\n\\n## 6. SELECT \uAE30\uBCF8 \uBB38\uBC95\uACFC \uB530\uC634\uD45C \uADDC\uCE59\\n\\n```sql\\n-- \uAE30\uBCF8 \uAD6C\uC870\\nSELECT *\\nFROM PLAYER;\\n\\n-- \uC870\uAC74 \uD3EC\uD568\\nSELECT *\\nFROM EMP\\nWHERE EMPNO = \'7369\';\\n```\\n\\n| \uAD6C\uBD84 | \uC6A9\uB3C4 | \uC608\uC2DC |\\n|------|------|------|\\n| \uC2F1\uAE00\uCFFC\uD2B8 `\'` | \uAC12(\uBB38\uC790 \uB9AC\uD130\uB7F4) | `WHERE JOB = \'CLERK\'` |\\n| \uB354\uBE14\uCFFC\uD2B8 `\\"` | \uC2DD\uBCC4\uC790(\uC608\uC57D\uC5B4/\uACF5\uBC31/\uB300\uC18C\uBB38\uC790 \uACE0\uC815) | `\\"POSITION\\"`, `\\"\uC120\uC218 \uC131\uBA85\\"` |\\n\\n:::warning\\n\uC608\uC57D\uC5B4\uC778 \uCEEC\uB7FC\uBA85(\uC608: `POSITION`)\uC740 \uB354\uBE14\uCFFC\uD2B8\uB85C \uAC10\uC2F8\uC57C \uD55C\uB2E4.\\n\\n\uC608\uC57D\uC5B4\uB97C \uD14C\uC774\uBE14\uBA85\uC73C\uB85C \uC0AC\uC6A9\uD558\uBA74 \uC2E4\uBB34\uC5D0\uC11C \uAD8C\uC7A5\uB418\uC9C0 \uC54A\uC74C.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `SELECT` `FROM` `WHERE` `\uC2F1\uAE00\uCFFC\uD2B8` `\uB354\uBE14\uCFFC\uD2B8`\\n\\n---\\n\\n## 7. \uCEEC\uB7FC \uC54C\uB9AC\uC544\uC2A4\uC640 \uD14C\uC774\uBE14 \uC54C\uB9AC\uC544\uC2A4\\n\\n```sql\\n-- \uCEEC\uB7FC \uC54C\uB9AC\uC544\uC2A4 (AS \uC0DD\uB7B5 \uAC00\uB2A5)\\nSELECT PLAYER_ID AS ID,\\n       PLAYER_NAME \uC131\uBA85,\\n       PLAYER_NAME AS \\"\uC120\uC218 \uC131\uBA85\\"  -- \uACF5\uBC31 \uD3EC\uD568 \uC2DC \uB354\uBE14\uCFFC\uD2B8\\nFROM PLAYER;\\n\\n-- \uC0C1\uC218 \uCEEC\uB7FC\\nSELECT PLAYER_NAME, \'1\'\\nFROM PLAYER;\\n\\n-- \uD14C\uC774\uBE14 \uC54C\uB9AC\uC544\uC2A4\\nSELECT P.*\\nFROM PLAYER P;\\n```\\n\\n:::warning\\n\uC54C\uB9AC\uC544\uC2A4\uB97C \uC120\uC5B8\uD588\uB2E4\uBA74 \uC774\uD6C4 \uCEEC\uB7FC \uCC38\uC870\uB294 \uC54C\uB9AC\uC544\uC2A4\uB9CC \uC0AC\uC6A9 \u2014 \uD14C\uC774\uBE14\uBA85\uACFC \uD63C\uC6A9\uD558\uBA74 \uC624\uB958.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uCEEC\uB7FC \uC54C\uB9AC\uC544\uC2A4` `AS` `\uACF5\uBC31 \uC54C\uB9AC\uC544\uC2A4` `\uD14C\uC774\uBE14 \uC54C\uB9AC\uC544\uC2A4` `ANSI/ISO`\\n\\n---\\n\\n## 8. JOIN \uAE30\uCD08\uC640 ambiguous \uC624\uB958\\n\\n```sql\\nSELECT P.PLAYER_ID,\\n       P.TEAM_ID,\\n       T.TEAM_NAME\\nFROM PLAYER P\\nJOIN TEAM T\\n  ON P.TEAM_ID = T.TEAM_ID;\\n```\\n\\n:::warning\\n\uC591\uCABD \uD14C\uC774\uBE14\uC5D0 \uAC19\uC740 \uCEEC\uB7FC\uBA85(`TEAM_ID`)\uC774 \uC788\uC73C\uBA74 \uB2E8\uB3C5 `SELECT` \uC2DC **ambiguous(\uC5F4 \uC815\uC758\uAC00 \uC560\uB9E4\uD568)** \uC624\uB958 \uBC1C\uC0DD.\\n\\n\uBC18\uB4DC\uC2DC `P.TEAM_ID` \uB610\uB294 `T.TEAM_ID` \uCC98\uB7FC \uCD9C\uCC98 \uC9C0\uC815 \uD544\uC694.\\n:::\\n\\n:::info\\nJOIN\uC774 \uD544\uC694\uD55C \uC774\uC720: \uC815\uADDC\uD654\uB85C \uBD84\uB9AC\uB41C \uD14C\uC774\uBE14\uC744 \uB2E4\uC2DC \uD569\uCCD0 \uC694\uAD6C\uC0AC\uD56D\uC744 \uCDA9\uC871.\\n\\n\uC608: \uCD9C\uD310\uC0AC\uBA85 \uBCC0\uACBD \uC2DC \uBAA8\uB4E0 \uD589\uC744 \uC218\uC815\uD574\uC57C \uD558\uB294 \uC218\uC815 \uC774\uC0C1 \u2192 \uCD9C\uD310\uC0AC \uD14C\uC774\uBE14 \uBD84\uB9AC \u2192 JOIN\uC73C\uB85C \uACB0\uD569.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `JOIN` `\uC815\uADDC\uD654` `FK` `TEAM_ID` `ambiguous`\\n\\n---\\n\\n## 9. WHERE \uC870\uAC74\uC808: \uBE44\uAD50, AND/OR, \uC6B0\uC120\uC21C\uC704\\n\\n```sql\\n-- \uB2E8\uC77C \uC870\uAC74\\nSELECT * FROM EMP WHERE EMPNO = \'7369\';\\n\\n-- OR \uC870\uAC74\\nSELECT * FROM EMP\\nWHERE JOB = \'CLERK\' OR EMPNO = \'7782\';\\n\\n-- AND/OR \uD63C\uD569 \uC2DC \uAD04\uD638\uB85C \uC758\uB3C4 \uBA85\uD655\uD788\\nSELECT * FROM EMP\\nWHERE (JOB = \'CLERK\' OR JOB = \'MANAGER\')\\n  AND DEPTNO = 10;\\n```\\n\\n:::danger\\nAND\uAC00 OR\uBCF4\uB2E4 \uBA3C\uC800 \uD3C9\uAC00\uB428.\\n\\n\uAD04\uD638 \uC5C6\uC774 AND/OR \uD63C\uD569 \uC2DC \uC758\uB3C4\uC640 \uB2E4\uB978 \uACB0\uACFC \uBC1C\uC0DD \uAC00\uB2A5 \u2014 \uBC18\uB4DC\uC2DC \uAD04\uD638 \uC0AC\uC6A9.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `WHERE` `AND` `OR` `\uC6B0\uC120\uC21C\uC704` `\uBE44\uAD50\uC5F0\uC0B0`\\n\\n---\\n\\n## \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. Oracle macOS \uD658\uACBD = Docker(Colima) \uAE30\uBC18 \uC124\uCE58\\n2. \uC0AC\uC6A9\uC790 \uC0DD\uC131 \uD6C4 \uBC18\uB4DC\uC2DC \uAD8C\uD55C(`CONNECT` \uB4F1) \uBD80\uC5EC\\n3. \uC2F1\uAE00\uCFFC\uD2B8 = \uAC12 / \uB354\uBE14\uCFFC\uD2B8 = \uC2DD\uBCC4\uC790(\uC608\uC57D\uC5B4/\uACF5\uBC31 \uD3EC\uD568 \uCEEC\uB7FC\uBA85)\\n4. \uC54C\uB9AC\uC544\uC2A4 \uC120\uC5B8 \uD6C4\uC5D0\uB294 \uD14C\uC774\uBE14\uBA85 \uB300\uC2E0 \uC54C\uB9AC\uC544\uC2A4\uB9CC \uC0AC\uC6A9\\n5. \uC591\uCABD \uD14C\uC774\uBE14\uC5D0 \uAC19\uC740 \uCEEC\uB7FC\uBA85 = ambiguous \uC624\uB958 \u2192 \uC54C\uB9AC\uC544\uC2A4\uB85C \uCD9C\uCC98 \uC9C0\uC815\\n6. AND\uAC00 OR\uBCF4\uB2E4 \uBA3C\uC800 \uD3C9\uAC00 \u2192 \uBCF5\uD569 \uC870\uAC74\uC740 \uAD04\uD638 \uC0AC\uC6A9 \uD544\uC218"},{"id":"/2026/03/10/java-lambda-stream-maven-junit","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/10/java-lambda-stream-maven-junit","source":"@site/blog/2026-03-10-java-lambda-stream-maven-junit.md","title":"[TIL] Java \uB78C\uB2E4, \uC2A4\uD2B8\uB9BC, Maven, JUnit \uC815\uB9AC","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.10","date":"2026-03-10T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"Lambda","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/lambda"},{"inline":true,"label":"Stream","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/stream"},{"inline":true,"label":"Maven","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/maven"},{"inline":true,"label":"JUnit5","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/j-unit-5"},{"inline":true,"label":"Oracle","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/oracle"}],"readingTime":3.56,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java \uB78C\uB2E4, \uC2A4\uD2B8\uB9BC, Maven, JUnit \uC815\uB9AC","date":"2026-03-10T00:00:00.000Z","tags":["Java","Lambda","Stream","Maven","JUnit5","Oracle"]},"unlisted":false,"prevItem":{"title":"[TIL] Oracle DB \uD658\uACBD\uAD6C\uCD95\uACFC SQL \uAE30\uCD08","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/11/oracle-sql-basics"},"nextItem":{"title":"[TIL] Java \uC608\uC678\uCC98\uB9AC\uC640 JCF \uAE30\uCD08","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/09/java-exception-jcf"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.10\\n\\n## \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uB78C\uB2E4/\uD391\uC158 \uC778\uD130\uD398\uC774\uC2A4 \u2192 Maven \uD504\uB85C\uC81D\uD2B8 \uAD6C\uC870 \u2192 \uC758\uC874\uC131/\uC804\uC774 \uC758\uC874\uC131\\n\u2192 JSON IO + DTO \uB9E4\uD551 \u2192 \uC2A4\uD2B8\uB9BC \uAE30\uBCF8 \uC5F0\uC0B0 \u2192 distinct/groupingBy\\n\u2192 JUnit5 \uB2E8\uC704 \uD14C\uC2A4\uD2B8 \u2192 Oracle XE \uC124\uCE58 \uC900\uBE44\\n```\\n\\n---\\n\\n## 1. \uB78C\uB2E4 \uD45C\uD604\uC2DD\uACFC \uD391\uC158 \uC778\uD130\uD398\uC774\uC2A4\\n\\n\uB78C\uB2E4\uC2DD = \uB2E8\uC77C \uCD94\uC0C1 \uBA54\uC18C\uB4DC(SAM)\uB97C \uAC00\uC9C4 **\uD391\uC158 \uC778\uD130\uD398\uC774\uC2A4**\uB97C \uAD6C\uD604 \uAC1D\uCCB4 \uC0DD\uC131 \uC5C6\uC774 \uBC14\uC778\uB529.\\n\\n```java\\n@FunctionalInterface\\ninterface LambdaObject {\\n    int combine(int a, int b);\\n}\\n\\nLambdaObject s = (x, y) -> x + y;\\nint result = s.combine(2, 3); // 5\\n```\\n\\n:::info\\n\uB78C\uB2E4\uC758 \uC758\uBBF8: \uB2E8\uC21C \uBB38\uBC95 \uCD95\uC57D\uC744 \uB118\uC5B4 \uBA54\uC18C\uB4DC(\uAE30\uB2A5)\uB97C \uAC12\uCC98\uB7FC \uC804\uB2EC \u2192 \uC2A4\uD2B8\uB9BC \uAC19\uC740 \uD568\uC218\uD615 API\uC640 \uACB0\uD569 \uAC00\uB2A5.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uB78C\uB2E4\uC2DD` `\uD391\uC158\uC778\uD130\uD398\uC774\uC2A4` `SAM` `\uD654\uC0B4\uD45C\uD45C\uD604\uC2DD` `\uC624\uBC84\uB77C\uC774\uB529`\\n\\n---\\n\\n## 2. Maven \uD504\uB85C\uC81D\uD2B8 \uAD6C\uC870\uC640 \uD658\uACBD \uC124\uC815\\n\\n| \uACBD\uB85C | \uC6A9\uB3C4 | \uBC30\uD3EC \uD3EC\uD568 |\\n|------|------|----------|\\n| `src/main/java` | \uC560\uD50C\uB9AC\uCF00\uC774\uC158 \uC18C\uC2A4 | \uD3EC\uD568 |\\n| `src/main/resources` | JSON, XML, properties | \uD3EC\uD568 |\\n| `src/test/java` | \uD14C\uC2A4\uD2B8 \uCF54\uB4DC | \uBBF8\uD3EC\uD568 |\\n| `src/test/resources` | \uD14C\uC2A4\uD2B8 \uC804\uC6A9 \uB9AC\uC18C\uC2A4 | \uBBF8\uD3EC\uD568 |\\n| `target` | \uBE4C\uB4DC \uC0B0\uCD9C\uBB3C | \uC0B0\uCD9C\uBB3C \uC704\uCE58 |\\n| `pom.xml` | \uBE4C\uB4DC/\uC758\uC874\uC131 \uC124\uC815 | \uC124\uC815 \uD30C\uC77C |\\n\\n```xml\\n<build>\\n  <plugins>\\n    <plugin>\\n      <artifactId>maven-compiler-plugin</artifactId>\\n      <version>10.1</version>\\n      <configuration>\\n        <source>21</source>\\n        <target>21</target>\\n      </configuration>\\n    </plugin>\\n  </plugins>\\n</build>\\n```\\n\\n:::warning\\nEclipse \uCD08\uAE30 \uC0DD\uC131 \uC2DC JRE\uAC00 1.8\uB85C \uC7A1\uD788\uB294 \uACBD\uC6B0 \uC788\uC74C \u2192 21\uB85C \uB9DE\uCD94\uAE30 \uD544\uC218.\\n\\n`pom.xml` \uC218\uC815 \uD6C4 \uBC18\uB4DC\uC2DC **Maven Update Project** \uC218\uD589.\\n\\n\uB124\uD2B8\uC6CC\uD06C \uBD88\uC548\uC815 \uD658\uACBD: Force Update of Snapshots/Releases\uB85C \uAC15\uC81C \uC7AC\uB2E4\uC6B4\uB85C\uB4DC.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Maven` `pom.xml` `\uD45C\uC900\uB514\uB809\uD130\uB9AC` `maven-compiler-plugin` `\uC5C5\uB370\uC774\uD2B8\uD504\uB85C\uC81D\uD2B8`\\n\\n---\\n\\n## 3. \uC758\uC874\uC131 \uCD94\uAC00\uC640 \uC804\uC774 \uC758\uC874\uC131\\n\\n| \uB77C\uC774\uBE0C\uB7EC\uB9AC | \uBAA9\uC801 |\\n|-----------|------|\\n| Guava | \uBB38\uC790\uC5F4/\uCEEC\uB809\uC158 \uC720\uD2F8\uB9AC\uD2F0 \uAC15\uD654 |\\n| Gson | JSON \u2194 Java Object \uBCC0\uD658 |\\n| Apache Commons IO | \uD30C\uC77C IO \uD3B8\uC758\uC131 (`IOUtils` \uB4F1) |\\n| JUnit Jupiter | \uB2E8\uC704 \uD14C\uC2A4\uD2B8 (JUnit 5) |\\n\\n:::info\\n**\uC804\uC774 \uC758\uC874\uC131**: A \uB77C\uC774\uBE0C\uB7EC\uB9AC \uC120\uC5B8 \uC2DC A\uAC00 \uD544\uC694\uB85C \uD558\uB294 B, C\uB3C4 \uD568\uAED8 \uB0B4\uB824\uBC1B\uC74C.\\n\\nMaven Dependencies\uC5D0 \uC9C1\uC811 \uCD94\uAC00\uD55C \uAC83\uBCF4\uB2E4 \uD6E8\uC52C \uB9CE\uC740 jar\uAC00 \uBCF4\uC774\uB294 \uC774\uC720.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `MVNRepository` `dependency` `\uC804\uC774\uC758\uC874\uC131` `Guava` `Gson`\\n\\n---\\n\\n## 4. JSON \uD30C\uC77C IO\uC640 DTO \uB9E4\uD551\\n\\n```java\\n// 3\uB2E8\uACC4: \uD30C\uC77C \uC77D\uAE30 \u2192 \uBB38\uC790\uC5F4 \uBCC0\uD658 \u2192 DTO \uB9AC\uC2A4\uD2B8 \uBCC0\uD658\\nInputStream is = Resources.getResource(\\"data.json\\").openStream();\\nString json = IOUtils.toString(is, StandardCharsets.UTF_8);\\nList<People> list = new Gson().fromJson(json, new TypeToken<ArrayList<People>>(){}.getType());\\n```\\n\\n:::warning\\n\uB9AC\uC2A4\uD2B8\uB85C \uBC1B\uC744 \uB54C `TypeToken<ArrayList<People>>` \uD544\uC694 \u2014 \uD0C0\uC785 \uC18C\uAC70 \uBB38\uC81C \uB54C\uBB38.\\n\\n\uB2E8\uC77C \uAC1D\uCCB4 \uD0C0\uC785\uC73C\uB85C \uC120\uC5B8\uD574 JSON \uBC30\uC5F4\uC744 \uCC98\uB9AC\uD558\uB824 \uD558\uBA74 \uC624\uB958 \uBC1C\uC0DD.\\n:::\\n\\n:::info\\nDTO \uC124\uACC4 \uD301:\\n- JSON 1:1 \uB9E4\uD551 DTO (\uC608: `People`) \uC640 \uC11C\uBE44\uC2A4\uC6A9 \uD504\uB85C\uB355\uC158 DTO (\uC608: `PeopleDTO`) \uBD84\uB9AC\\n- `final` \uD544\uB4DC + \uC0DD\uC131\uC790 \uC8FC\uC785\uC73C\uB85C \uBD88\uBCC0\uC131 \uAC15\uD654 \u2192 setter \uC5C6\uC774 getter\uB9CC \uC81C\uACF5\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `DTO` `IOUtils` `TypeToken` `fromJson` `\uBD88\uBCC0\uAC1D\uCCB4`\\n\\n---\\n\\n## 5. \uC2A4\uD2B8\uB9BC \uAE30\uBCF8 \uBB38\uBC95\uACFC \uC8FC\uC694 \uC5F0\uC0B0\\n\\n| \uC5F0\uC0B0 | \uC758\uBBF8 | \uC804\uD1B5 \uCF54\uB4DC \uAC10\uAC01 |\\n|------|------|--------------|\\n| `filter` | \uC870\uAC74\uC5D0 \uB9DE\uB294 \uC694\uC18C\uB9CC \uD1B5\uACFC | `if` \uC870\uAC74\uBB38 |\\n| `map` | \uC694\uC18C\uB97C \uB2E4\uB978 \uD615\uD0DC\uB85C \uBCC0\uD658/\uCD94\uCD9C | \uD544\uB4DC \uCD94\uCD9C/\uAC00\uACF5 |\\n| `limit` | \uAC1C\uC218 \uC81C\uD55C | \uCE74\uC6B4\uD130 + `break` |\\n| `distinct` | \uC911\uBCF5 \uC81C\uAC70 | Set \uC0AC\uC6A9/\uC911\uBCF5 \uCCB4\uD06C |\\n| `sorted` | \uC815\uB82C | `Comparator` |\\n| `collect` | \uACB0\uACFC\uB97C List/Set/Map\uC73C\uB85C \uC218\uC9D1 | \uACB0\uACFC \uCEE8\uD14C\uC774\uB108\uC5D0 `add` |\\n\\n```java\\n// 18\uC138 \uC774\uD558 10\uBA85 \uCD94\uCD9C\\nList<People> result = list.stream()\\n    .filter(p -> p.getAge() <= 18)\\n    .limit(10)\\n    .collect(Collectors.toList());\\n\\n// \uC815\uC218 \uBC18\uBCF5\\nIntStream.rangeClosed(0, 10).forEach(System.out::println);\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Stream` `filter` `map` `collect` `\uBA54\uC11C\uB4DC\uB808\uD37C\uB7F0\uC2A4`\\n\\n---\\n\\n## 6. distinct, groupingBy, counting\uC73C\uB85C \uC9D1\uACC4\\n\\n```java\\n// \uC911\uBCF5 \uC81C\uAC70\\nList<Integer> unique = numbers.stream()\\n    .distinct()\\n    .collect(Collectors.toList());\\n\\n// \uC81C\uC870\uC0AC\uBCC4 \uADF8\uB8F9\uD551\\nMap<String, List<Car>> grouped = cars.stream()\\n    .collect(Collectors.groupingBy(Car::getMake));\\n\\n// \uD56D\uBAA9\uBCC4 \uAC1C\uC218 \uC9D1\uACC4\\nMap<String, Long> count = names.stream()\\n    .collect(Collectors.groupingBy(Function.identity(), Collectors.counting()));\\n```\\n\\n:::info\\n\uADF8\uB8F9\uD551 \uACB0\uACFC \uCD9C\uB825: \uD0A4\uB97C \uBAA8\uB974\uB294 Map\uC740 `forEach((k, v) -> ...)` \uD615\uD0DC\uB85C \uC21C\uD68C.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `distinct` `groupingBy` `counting` `Map` `JCF`\\n\\n---\\n\\n## 7. JUnit 5 (\uC8FC\uD53C\uD130) \uB2E8\uC704 \uD14C\uC2A4\uD2B8\\n\\n```java\\nclass Calculator {\\n    int add(int a, int b) { return a + b; }\\n}\\n\\npublic class JUnitTest {\\n    @Test\\n    @DisplayName(\\"\uB354\uD558\uAE30 \uD14C\uC2A4\uD2B8\\")\\n    void addTest() {\\n        Calculator cal = new Calculator();\\n        Assertions.assertEquals(5, cal.add(2, 3));\\n    }\\n}\\n```\\n\\n- \uC131\uACF5 = \uD30C\uB780\uC0C9 / \uC2E4\uD328 = \uBE68\uAC04\uC0C9 + \uAE30\uB300\uAC12/\uC2E4\uC81C\uAC12 \uBE44\uAD50 \uCD9C\uB825\\n- `@DisplayName` \u2014 \uD14C\uC2A4\uD2B8 \uBAA9\uC801\uC744 \uC0AC\uB78C\uC774 \uC77D\uAE30 \uC88B\uAC8C \uD45C\uD604\\n- \uAE30\uC874 JUnit 3.8 \uD14C\uC2A4\uD2B8 \uD30C\uC77C \uC0AD\uC81C \uD6C4 `junit-jupiter-api` \uC758\uC874\uC131 \uCD94\uAC00\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `JUnit5` `Jupiter` `@Test` `Assertions` `\uB2E8\uC704\uD14C\uC2A4\uD2B8`\\n\\n---\\n\\n## 8. DB \uACFC\uC815 \uC900\uBE44: Oracle XE \uC124\uCE58\\n\\n```sql\\n-- \uAD00\uB9AC\uC790 \uBE44\uBC00\uBC88\uD638 \uBCC0\uACBD\\nALTER USER system IDENTIFIED BY manager;\\n\\n-- \uACC4\uC815 \uC7A0\uAE08 \uD574\uC81C\\nALTER USER system ACCOUNT UNLOCK;\\n```\\n\\n- Windows: XE \uC124\uCE58 \uD30C\uC77C \uB2E4\uC6B4\uB85C\uB4DC \uD6C4 setup \uC9C4\uD589\\n- macOS: Docker(Colima) \uAE30\uBC18 \uC124\uCE58 \uD544\uC694 (\uC544\uD0A4\uD14D\uCC98 \uCC28\uC774)\\n- \uC811\uC18D \uB3C4\uAD6C: DBeaver \uAE30\uC900 (SQL Developer, IntelliJ DB \uB3C4\uAD6C\uB3C4 \uBB34\uBC29)\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `OracleXE` `SQL*Plus` `SYSDBA` `\uACC4\uC815\uC5B8\uB77D` `DBeaver`\\n\\n---\\n\\n## \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. \uB78C\uB2E4 = \uD391\uC158 \uC778\uD130\uD398\uC774\uC2A4\uC758 SAM\uC744 \uC989\uC2DC \uAD6C\uD604 \u2014 \uBCC4\uB3C4 \uD074\uB798\uC2A4 \uBD88\uD544\uC694\\n2. Maven \uD45C\uC900 \uAD6C\uC870 \uC219\uC9C0 \u2014 `src/main`\uC740 \uBC30\uD3EC \uD3EC\uD568, `src/test`\uB294 \uBBF8\uD3EC\uD568\\n3. \uC804\uC774 \uC758\uC874\uC131: \uC120\uC5B8\uD55C \uB77C\uC774\uBE0C\uB7EC\uB9AC\uC758 \uC5F0\uAD00 \uB77C\uC774\uBE0C\uB7EC\uB9AC\uAE4C\uC9C0 \uC790\uB3D9 \uD3EC\uD568\\n4. \uC2A4\uD2B8\uB9BC = \uCEEC\uB809\uC158\uC744 \uD30C\uC774\uD504\uB77C\uC778\uC73C\uB85C \uC120\uC5B8\uC801 \uCC98\uB9AC\\n5. `groupingBy` + `counting` = \uC9D1\uACC4/\uD1B5\uACC4 \uCC98\uB9AC\uC758 \uD575\uC2EC \uD328\uD134\\n6. JUnit `@Test` + `assertEquals` = \uBA54\uC18C\uB4DC \uB2E8\uC704 \uAC80\uC99D"},{"id":"/2026/03/09/java-exception-jcf","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/09/java-exception-jcf","source":"@site/blog/2026-03-09-java-exception-jcf.md","title":"[TIL] Java \uC608\uC678\uCC98\uB9AC\uC640 JCF \uAE30\uCD08","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.09","date":"2026-03-09T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"\uC608\uC678\uCC98\uB9AC","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uC608\uC678\uCC98\uB9AC"},{"inline":true,"label":"JCF","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/jcf"},{"inline":true,"label":"List","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/list"},{"inline":true,"label":"WrapperClass","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/wrapper-class"}],"readingTime":1.92,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java \uC608\uC678\uCC98\uB9AC\uC640 JCF \uAE30\uCD08","date":"2026-03-09T00:00:00.000Z","tags":["Java","\uC608\uC678\uCC98\uB9AC","JCF","List","WrapperClass"]},"unlisted":false,"prevItem":{"title":"[TIL] Java \uB78C\uB2E4, \uC2A4\uD2B8\uB9BC, Maven, JUnit \uC815\uB9AC","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/10/java-lambda-stream-maven-junit"},"nextItem":{"title":"[TIL] Java \uCD94\uC0C1, \uC778\uD130\uD398\uC774\uC2A4\uC640 \uB2E4\uD615\uC131","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/06/java-abstract-polymorphism"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.09\\n\\n## \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\ntry-catch-finally \u2192 try-with-resources \u2192 Checked/Runtime Exception\\n\u2192 throw/throws \u2192 JCF \uAD6C\uC870 \u2192 List \uC2E4\uC2B5 \u2192 Wrapper Class / \uBC15\uC2F1\\n```\\n\\n---\\n\\n## 1. \uC608\uC678 \uCC98\uB9AC \uC2EC\uD654\uC640 \uB9AC\uC18C\uC2A4 \uAD00\uB9AC\\n\\n\uAE30\uBCF8 \uAD6C\uC870: `try` \uC815\uC0C1 \uB85C\uC9C1 \u2192 \uC2E4\uD328 \uC2DC `catch` \uCC98\uB9AC \u2192 `finally` \uD56D\uC0C1 \uC2E4\uD589.\\n\\n### try-with-resources\\n\\n\uB9AC\uC18C\uC2A4\uB97C `try()` \uAD04\uD638 \uC548\uC5D0 \uC120\uC5B8\uD558\uBA74 \uBE14\uB85D \uC885\uB8CC \uC2DC \uC790\uB3D9\uC73C\uB85C `close()` \uD638\uCD9C.\\n\\n```java\\ntry (FileReader reader = new FileReader(\\"missing.txt\\")) {\\n    // \uCC98\uB9AC\\n} catch (FileNotFoundException e) {\\n    e.printStackTrace(); // \uC2A4\uD0DD \uC5ED\uCD94\uC801 \uC815\uBCF4 \uCD9C\uB825\\n} catch (Exception e) {\\n    e.printStackTrace();\\n}\\n```\\n\\n:::info\\n\uC608\uC678\uB294 \uAD6C\uCCB4\uC801\uC778 \uAC83 \uBA3C\uC800, \uD070 \uBC94\uC8FC\uB294 \uB098\uC911\uC5D0 \u2014 `FileNotFoundException` \u2192 `Exception` \uC21C\uC11C.\\n\\n\uC5EC\uB7EC \uB9AC\uC18C\uC2A4 \uC120\uC5B8 \uC2DC \uC138\uBBF8\uCF5C\uB860(`;`)\uC73C\uB85C \uAD6C\uBD84 \u2014 \uCF64\uB9C8\uB85C \uC798\uBABB \uC4F0\uB294 \uC2E4\uC218 \uC8FC\uC758.\\n:::\\n\\n:::info\\n- Java 7: try-with-resources \uB3C4\uC785\\n- Java 9+: try \uBE14\uB85D \uC678\uBD80\uC5D0\uC11C \uC0DD\uC131\uD55C \uB9AC\uC18C\uC2A4 \uBCC0\uC218\uB97C `try(resource)` \uD615\uD0DC\uB85C \uC804\uB2EC \uAC00\uB2A5\\n:::\\n\\n### Checked vs Runtime Exception\\n\\n| \uAD6C\uBD84 | Checked Exception | Runtime Exception |\\n|------|------------------|------------------|\\n| \uCEF4\uD30C\uC77C \uAC15\uC81C | \uC788\uC74C | \uC5C6\uC74C |\\n| \uC8FC\uC694 \uD328\uD0A4\uC9C0 | `java.io`, `java.sql` | `NullPointerException` \uB4F1 |\\n| \uC608\uC2DC | \uD30C\uC77C/\uB124\uD2B8\uC6CC\uD06C/DB | \uC798\uBABB\uB41C \uC778\uB371\uC2A4 \uC811\uADFC |\\n\\n### throw vs throws\\n\\n| \uAD6C\uBD84 | \uC704\uCE58 | \uC758\uBBF8 |\\n|------|------|------|\\n| `throw` | \uBA54\uC18C\uB4DC \uB0B4\uBD80 | \uC608\uC678\uB97C \uC9C1\uC811 \uBC1C\uC0DD |\\n| `throws` | \uBA54\uC18C\uB4DC \uC120\uC5B8\uBD80 | \uD638\uCD9C\uC790\uC5D0\uAC8C \uCC98\uB9AC \uC704\uC784 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `try-with-resources` `Checked Exception` `Runtime Exception` `throw` `throws`\\n\\n---\\n\\n## 2. JCF \uAD6C\uC870\uC640 List \uC2E4\uC2B5\\n\\nJCF(Java Collection Framework) = \uC790\uB8CC\uAD6C\uC870\uB97C \uC774\uC6A9\uD55C \uD45C\uC900 \uB77C\uC774\uBE0C\uB7EC\uB9AC.\\n\\n| \uAD6C\uBD84 | \uD575\uC2EC \uD2B9\uC9D5 | \uB300\uD45C \uC0AC\uC6A9 |\\n|------|----------|----------|\\n| `List` | \uC778\uB371\uC2A4 \uAE30\uBC18, \uC911\uBCF5 \uD5C8\uC6A9 | DB \uC870\uD68C \uACB0\uACFC\uB97C \uC21C\uC11C\uB300\uB85C \uCC98\uB9AC |\\n| `Set` | \uC911\uBCF5 \uBD88\uD5C8 | \uC720\uC77C\uD55C \uAC12 \uC9D1\uD569 (\uB85C\uB610 \uBC88\uD638 \uB4F1) |\\n| `Map` | Key-Value \uC30D | JSON\uCC98\uB7FC \uD0A4\uB85C \uAC12\uC744 \uCC3E\uB294 \uAD6C\uC870 |\\n\\n```java\\nlist.add(n1);\\nlist.add(n2);\\nlist.add(n3);\\n\\nSystem.out.println(list.get(1)); // \uC778\uB371\uC2A4 1\uC758 \uAC12 \uC870\uD68C\\n```\\n\\n### remove() \uC624\uBC84\uB85C\uB529 \uC8FC\uC758\\n\\n| \uD638\uCD9C \uD615\uD0DC | \uD574\uC11D | \uACB0\uACFC |\\n|----------|------|------|\\n| `remove(1)` | \uC778\uB371\uC2A4 1 \uC0AD\uC81C | \uB450 \uBC88\uC9F8 \uC694\uC18C \uC81C\uAC70 |\\n| `remove(Integer.valueOf(1))` | \uAC12 1(\uAC1D\uCCB4) \uC0AD\uC81C | \uAC12\uC774 1\uC778 \uC694\uC18C \uC81C\uAC70 |\\n\\n:::danger\\n\uC0AD\uC81C \uD6C4 \uB4A4\uC758 \uC694\uC18C\uB4E4\uC774 \uC55E\uC73C\uB85C \uB2F9\uACA8\uC9C0\uBA70 \uC778\uB371\uC2A4 \uC7AC\uC815\uB82C\uB428.\\n\\n`remove(int)`\uC640 `remove(Object)` \uD63C\uB3D9\uC740 \uBE48\uBC88\uD55C \uC2E4\uC218 \uD3EC\uC778\uD2B8.\\n:::\\n\\n### Wrapper Class\uC640 \uC790\uB3D9 \uBC15\uC2F1/\uC5B8\uBC15\uC2F1\\n\\n\uAE30\uBCF8 \uD0C0\uC785\uC744 \uCC38\uC870 \uD0C0\uC785\uC73C\uB85C \uAC10\uC2F8\uB294 \uD074\uB798\uC2A4. `int` \u2192 `Integer` \uB4F1.\\n\\n- Java 9 \uC774\uD6C4 \uC790\uB3D9 \uBC15\uC2F1/\uC5B8\uBC15\uC2F1\uC774 \uC790\uC5F0\uC2A4\uB7FD\uAC8C \uCC98\uB9AC\uB428\\n- \uCEEC\uB809\uC158\uC5D0\uC11C \uAE30\uBCF8 \uD0C0\uC785\uC774 \uAC1D\uCCB4\uB85C \uB2E4\uB904\uC9C4\uB2E4\uB294 \uAD00\uC810\uC774 \uD575\uC2EC\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `JCF` `List` `Set` `Map` `Wrapper Class`\\n\\n---\\n\\n## \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. `finally` = \uC131\uACF5/\uC2E4\uD328\uC640 \uBB34\uAD00\uD558\uAC8C \uD56D\uC0C1 \uC2E4\uD589 \u2014 \uB9AC\uC18C\uC2A4 \uD574\uC81C\uC5D0 \uD65C\uC6A9\\n2. `try-with-resources` = \uC790\uB3D9 `close()` \uBCF4\uC7A5\\n3. Checked Exception = \uCEF4\uD30C\uC77C \uB2E8\uACC4\uC5D0\uC11C \uAC15\uC81C \uCC98\uB9AC \uD544\uC694\\n4. `throw` = \uC608\uC678 \uC9C1\uC811 \uBC1C\uC0DD / `throws` = \uD638\uCD9C\uC790\uC5D0\uAC8C \uC704\uC784\\n5. JCF 3\uCD95: `List`(\uC778\uB371\uC2A4, \uC911\uBCF5 \uD5C8\uC6A9) / `Set`(\uC911\uBCF5 \uBD88\uD5C8) / `Map`(Key-Value)\\n6. `remove(int)` = \uC778\uB371\uC2A4 \uC0AD\uC81C / `remove(Object)` = \uAC12 \uC0AD\uC81C \u2014 \uD63C\uB3D9 \uC8FC\uC758"},{"id":"/2026/03/06/java-abstract-polymorphism","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/06/java-abstract-polymorphism","source":"@site/blog/2026-03-06-java-abstract-polymorphism.md","title":"[TIL] Java \uCD94\uC0C1, \uC778\uD130\uD398\uC774\uC2A4\uC640 \uB2E4\uD615\uC131","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.06","date":"2026-03-06T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"abstract","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/abstract"},{"inline":true,"label":"interface","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/interface"},{"inline":true,"label":"\uB2E4\uD615\uC131","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uB2E4\uD615\uC131"},{"inline":true,"label":"VMI","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/vmi"},{"inline":true,"label":"\uC5C5\uCE90\uC2A4\uD305","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uC5C5\uCE90\uC2A4\uD305"}],"readingTime":2.45,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java \uCD94\uC0C1, \uC778\uD130\uD398\uC774\uC2A4\uC640 \uB2E4\uD615\uC131","date":"2026-03-06T00:00:00.000Z","tags":["Java","abstract","interface","\uB2E4\uD615\uC131","VMI","\uC5C5\uCE90\uC2A4\uD305"]},"unlisted":false,"prevItem":{"title":"[TIL] Java \uC608\uC678\uCC98\uB9AC\uC640 JCF \uAE30\uCD08","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/09/java-exception-jcf"},"nextItem":{"title":"[TIL] Java \uB2EC\uB825, API \uC120\uC815, OOP \uD575\uC2EC \uC815\uB9AC","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/05/java-calendar-oop"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.06\\n\\n## \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uD559\uC2B5 \uCCB4\uD06C\uB9AC\uC2A4\uD2B8 \u2192 \uC778\uD130\uD398\uC774\uC2A4 vs \uCD94\uC0C1 \uD074\uB798\uC2A4\\n\u2192 \uCD94\uC0C1 \uBA54\uC18C\uB4DC \uAD6C\uD604 \uD750\uB984 \uC2E4\uC2B5 \u2192 \uB2E4\uD615\uC131/VMI \u2192 H2O \uBAA8\uB378\uB9C1 \uC608\uACE0\\n```\\n\\n---\\n\\n## 1. \uD559\uC2B5 \uCCB4\uD06C\uB9AC\uC2A4\uD2B8\uC640 \uB85C\uB4DC\uB9F5\\n\\n\uCCB4\uD06C\uB9AC\uC2A4\uD2B8 \uBAA9\uC801: \\"\uBB58 \uBAA8\uB974\uB294\uC9C0 \uBAA8\uB974\uB294 \uC0C1\uD0DC\\"\uC5D0\uC11C \\"N\uBC88 \uD56D\uBAA9\uC774 \uC774\uD574\uAC00 \uC548 \uB41C\uB2E4\\"\uB85C \uC9C8\uBB38\uC744 \uAD6C\uCCB4\uD654.\\n\\n| \uB85C\uB4DC\uB9F5 \uC694\uC18C | \uAC15\uC870 \uC774\uC720 |\\n|------------|----------|\\n| DB \uD559\uC2B5 | \uBB38\uBC95\uC774 \uC815\uD615\uD654\uB418\uC5B4 \uC788\uC5B4 \uC790\uBC14 \uC774\uD6C4 \uBD80\uB2F4 \uBD84\uC0B0 \uAC00\uB2A5 |\\n| \uB514\uC790\uC778 \uD328\uD134 | \\"\uC790\uBC14\uB97C \uC798\uD55C\uB2E4\\"\uB294 \uC778\uC2DD\uACFC \uC9C1\uACB0 |\\n| \uC2A4\uD2B8\uB9BC/\uB78C\uB2E4 | Spring \uB4F1\uC5D0\uC11C \uD654\uC0B4\uD45C \uBB38\uBC95\uC774 \uBE48\uBC88 \u2014 \uBBF8\uC219\uD558\uBA74 \uCF54\uB4DC \uC774\uD574 \uC5B4\uB824\uC6C0 |\\n| I/O | \uAC1C\uB150 \uD655\uC7A5\uC5D0 \uB3C4\uC6C0, \uD544\uC218\uB294 \uC544\uB2D8 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uCCB4\uD06C\uB9AC\uC2A4\uD2B8` `\uB514\uC790\uC778\uD328\uD134` `\uC2A4\uD2B8\uB9BC` `\uB78C\uB2E4` `\uC6D0\uACA9\uB370\uC2A4\uD06C\uD1B1`\\n\\n---\\n\\n## 2. \uC778\uD130\uD398\uC774\uC2A4 vs \uCD94\uC0C1 \uD074\uB798\uC2A4\\n\\n| \uAD6C\uBD84 | \uC778\uD130\uD398\uC774\uC2A4 | \uCD94\uC0C1 \uD074\uB798\uC2A4 |\\n|------|-----------|------------|\\n| \uD575\uC2EC \uC131\uACA9 | \uAE30\uB2A5 \uACC4\uC57D (\uCD94\uC0C1 \uBA54\uC18C\uB4DC \uC9D1\uD569) | \uC77C\uBC18 \uD074\uB798\uC2A4 + \uCD94\uC0C1 \uBA54\uC18C\uB4DC \uAC00\uB2A5 |\\n| \uC0DD\uC131\uC790 | \uC5C6\uC74C | \uC788\uC74C |\\n| \uAD6C\uD604 \uAC15\uC81C | \uBBF8\uAD6C\uD604 \uBA54\uC18C\uB4DC \uBC18\uB4DC\uC2DC \uC624\uBC84\uB77C\uC774\uB529 | \uB3D9\uC77C |\\n| \uD544\uB4DC | \uC790\uB3D9 `public static final` | \uC77C\uBC18 \uD074\uB798\uC2A4 \uADDC\uCE59 \uC801\uC6A9 |\\n| \uB2E4\uC911 \uC0C1\uC18D | \uAC00\uB2A5 | \uBD88\uAC00 |\\n\\n:::info\\n\uCD94\uC0C1 \uBA54\uC18C\uB4DC\uAC00 \uD074\uB798\uC2A4\uC5D0 \uD3EC\uD568\uB418\uBA74 \uD574\uB2F9 \uD074\uB798\uC2A4\uB294 \uBC18\uB4DC\uC2DC `abstract`\uB85C \uC120\uC5B8\uD574\uC57C \uD55C\uB2E4.\\n\\n\uCD94\uC0C1 \uD074\uB798\uC2A4\uB294 \uCD94\uC0C1 \uBA54\uC18C\uB4DC\uAC00 \uC5C6\uC5B4\uB3C4 `new`\uB85C \uC9C1\uC811 \uC778\uC2A4\uD134\uC2A4\uD654 \uBD88\uAC00 \uC120\uC5B8\uC774 \uAC00\uB2A5.\\n:::\\n\\n:::info\\n\uD074\uB798\uC2A4 \uB2E4\uC911 \uC0C1\uC18D\uC774 \uC81C\uD55C\uB418\uB294 \uC774\uC720: \uC0DD\uC131\uC790 \uD638\uCD9C \uBC0F \uC815\uCCB4\uC131(\uD2B9\uC131) \uCDA9\uB3CC.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `extends` `implements` `abstract` `default\uBA54\uC18C\uB4DC` `static`\\n\\n---\\n\\n## 3. \uCD94\uC0C1 \uBA54\uC18C\uB4DC \uAD6C\uD604 \uD750\uB984 \uC2E4\uC2B5\\n\\n`\uC778\uD130\uD398\uC774\uC2A4 \u2192 \uCD94\uC0C1 \uD074\uB798\uC2A4(\uC77C\uBD80 \uAD6C\uD604) \u2192 \uC790\uC2DD \uD074\uB798\uC2A4(\uB098\uBA38\uC9C0 \uAD6C\uD604)` \uB2E8\uACC4\uC801 \uAD6C\uD604 \uBAA8\uB378.\\n\\n```java\\ninterface IParent {\\n    void make();\\n    void print();\\n}\\n\\nabstract class AParent implements IParent {\\n    @Override\\n    public void print() {\\n        System.out.println(\\"AParent.print()\\");\\n    }\\n\\n    @Override\\n    public abstract void make(); // \uC790\uC2DD\uC5D0\uAC8C \uC704\uC784\\n}\\n\\nclass Child extends AParent {\\n    @Override\\n    public void make() {\\n        System.out.println(\\"Child.make()\\");\\n    }\\n}\\n```\\n\\n:::warning\\n\uCD94\uC0C1 \uBA54\uC18C\uB4DC\uB97C \uC120\uC5B8\uD558\uB294 \uC21C\uAC04 \uD074\uB798\uC2A4\uC5D0 `abstract`\uAC00 \uC5C6\uC73C\uBA74 \uCEF4\uD30C\uC77C \uC624\uB958 \uBC1C\uC0DD.\\n\\nIDE\uC758 \\"abstract \uC120\uC5B8 \uCD94\uAC00\\" \uC81C\uC548\uC73C\uB85C \uC989\uC2DC \uD655\uC778 \uAC00\uB2A5.\\n:::\\n\\n:::info\\n\uD074\uB798\uC2A4 \uB2E4\uC774\uC5B4\uADF8\uB7A8\uC744 \uC77D\uB294 \uB2A5\uB825\uC774 VMI(\uB3D9\uC801 \uBC14\uC778\uB529) \uC774\uD574\uC5D0 \uD544\uC218.\\n\\n\uC0C1\uC18D/\uAD6C\uD604 \uAD00\uACC4\uB97C \uADF8\uB9BC\uC73C\uB85C \uC77D\uC5B4\uC57C \uB7F0\uD0C0\uC784 \uD638\uCD9C \uB300\uC0C1 \uCD94\uC801 \uAC00\uB2A5.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uCD94\uC0C1\uBA54\uC18C\uB4DC` `\uCD94\uC0C1\uD074\uB798\uC2A4` `\uC624\uBC84\uB77C\uC774\uB4DC` `\uD074\uB798\uC2A4\uB2E4\uC774\uC5B4\uADF8\uB7A8` `\uCEF4\uD30C\uC77C\uC624\uB958`\\n\\n---\\n\\n## 4. \uB2E4\uD615\uC131, VMI\uC640 \uBA54\uBAA8\uB9AC \uB178\uCD9C\\n\\n| \uAD6C\uBD84 | \uACB0\uC815 \uAE30\uC900 |\\n|------|----------|\\n| \uC811\uADFC \uAC00\uB2A5\uD55C \uBA64\uBC84 | \uCC38\uC870 \uBCC0\uC218\uC758 \uD0C0\uC785 |\\n| \uC624\uBC84\uB77C\uC774\uB529\uB41C \uBA54\uC18C\uB4DC \uC2E4\uD589 | \uC2E4\uC81C \uC0DD\uC131\uB41C \uAC1D\uCCB4 \uD0C0\uC785 (VMI) |\\n| \uD544\uB4DC \uC811\uADFC | \uCC38\uC870 \uBCC0\uC218\uC758 \uD0C0\uC785 (\uD558\uC774\uB529) |\\n| static \uBA54\uC18C\uB4DC | \uD074\uB798\uC2A4 \uAE30\uC900 (\uD558\uC774\uB529) |\\n\\n```java\\n// IParent \uD0C0\uC785\uC73C\uB85C \uCC38\uC870\uD574\uB3C4 make() \uD638\uCD9C\uC740 \uCD5C\uC885 \uAD6C\uD604(Child)\uC73C\uB85C \uC774\uB3D9\\nIParent p = new Child();\\np.make(); // Child.make() \uC2E4\uD589\\n```\\n\\n- \uC790\uC2DD \uD0C0\uC785\uC73C\uB85C \uC0DD\uC131 \u2192 \uC790\uC2DD \uBA64\uBC84\uAE4C\uC9C0 \uBAA8\uB450 \uC811\uADFC \uAC00\uB2A5\\n- \uBD80\uBAA8 \uD0C0\uC785\uC73C\uB85C \uC5C5\uCE90\uC2A4\uD305 \u2192 \uBD80\uBAA8 \uD0C0\uC785\uC5D0 \uC120\uC5B8\uB41C \uBA64\uBC84\uB9CC \uC811\uADFC \uAC00\uB2A5\\n- \uC5C5\uCE90\uC2A4\uD305 \uC0C1\uD0DC\uC5D0\uC11C\uB3C4 \uC624\uBC84\uB77C\uC774\uB529\uB41C \uBA54\uC18C\uB4DC\uB294 \uC2E4\uC81C \uAC1D\uCCB4\uC758 \uAD6C\uD604\uC774 \uC2E4\uD589\uB428\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uB2E4\uD615\uC131` `\uC5C5\uCE90\uC2A4\uD305` `\uB2E4\uC6B4\uCE90\uC2A4\uD305` `VMI` `\uB3D9\uC801\uBC14\uC778\uB529`\\n\\n---\\n\\n## 5. H2O \uBAA8\uB378\uB9C1 \uC608\uACE0\\n\\n\uB2E4\uC74C \uC2E4\uC2B5 \uAD6C\uC870 \uC608\uACE0:\\n\\n| \uAD6C\uC131 \uC694\uC18C | \uC5ED\uD560 | \uC608\uC2DC \uBA85\uBA85 |\\n|----------|------|----------|\\n| \uC778\uD130\uD398\uC774\uC2A4 | \uAE30\uB2A5(\uD589\uB3D9)\uC758 \uACC4\uC57D \uC815\uC758 | `H2O` |\\n| \uCD94\uC0C1 \uD074\uB798\uC2A4 | \uACF5\uD1B5 \uB85C\uC9C1/\uAE30\uBCF8 \uD2C0 \uC81C\uACF5 | `H2OImpl` |\\n| \uAD6C\uCCB4 \uD074\uB798\uC2A4 | \uC0C1\uD0DC\uBCC4 \uB3D9\uC791 \uC644\uC131 | `Ice`, `Water`, `Steam` |\\n\\n:::info\\n\uC2E4\uBB34 \uAD00\uB840: \uC778\uD130\uD398\uC774\uC2A4 \uAD6C\uD604\uCCB4\uC5D0 `Impl` \uC811\uBBF8\uC0AC\uB97C \uBD99\uC774\uB294 \uB124\uC774\uBC0D \uD328\uD134.\\n\\n\uD504\uB808\uC784\uC6CC\uD06C/\uC5D4\uD130\uD504\uB77C\uC774\uC988 \uCF54\uB4DC\uC5D0\uC11C \uAD6C\uD604 \uD074\uB798\uC2A4\uB97C \uBE60\uB974\uAC8C \uC2DD\uBCC4\uD558\uAE30 \uC704\uD55C \uAD00\uC2B5.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `H2O` `Impl` `\uCD94\uC0C1\uD654` `\uAD6C\uD604\uCCB4` `\uC0C1\uD0DC\uBAA8\uB378\uB9C1`\\n\\n---\\n\\n## \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. \uC778\uD130\uD398\uC774\uC2A4 = \uAE30\uB2A5 \uACC4\uC57D (\uC0DD\uC131\uC790 \uC5C6\uC74C, \uD544\uB4DC\uB294 \uC790\uB3D9 `static final`)\\n2. \uCD94\uC0C1 \uD074\uB798\uC2A4 = \uC77C\uBC18 \uD074\uB798\uC2A4 + \uCD94\uC0C1 \uBA54\uC18C\uB4DC \uAC00\uB2A5 (\uC0DD\uC131\uC790 \uC788\uC74C)\\n3. \uCD94\uC0C1 \uBA54\uC18C\uB4DC \uC788\uC73C\uBA74 \uD074\uB798\uC2A4\uB3C4 \uBC18\uB4DC\uC2DC `abstract`\\n4. VMI = \uCC38\uC870 \uD0C0\uC785\uC73C\uB85C \uB178\uCD9C \uBC94\uC704 \uC81C\uD55C + \uC2E4\uC81C \uAC1D\uCCB4 \uD0C0\uC785\uC73C\uB85C \uBA54\uC18C\uB4DC \uC2E4\uD589\\n5. \uC5C5\uCE90\uC2A4\uD305 \uC2DC \uBA64\uBC84 \uB178\uCD9C\uC740 \uCC38\uC870 \uD0C0\uC785 \uAE30\uC900, \uBA54\uC18C\uB4DC \uC2E4\uD589\uC740 \uC2E4\uC81C \uAC1D\uCCB4 \uAE30\uC900\\n6. \uAD6C\uD604\uCCB4 \uD074\uB798\uC2A4\uBA85\uC5D0 `Impl` \uC811\uBBF8\uC0AC \uBD99\uC774\uB294 \uAC83\uC774 \uC2E4\uBB34 \uAD00\uB840"},{"id":"/2026/03/05/java-calendar-oop","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/05/java-calendar-oop","source":"@site/blog/2026-03-05-java-calendar-oop.md","title":"[TIL] Java \uB2EC\uB825, API \uC120\uC815, OOP \uD575\uC2EC \uC815\uB9AC","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.05","date":"2026-03-05T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"Calendar","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/calendar"},{"inline":true,"label":"LocalDate","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/local-date"},{"inline":true,"label":"OOP","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/oop"},{"inline":true,"label":"\uC778\uD130\uD398\uC774\uC2A4","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uC778\uD130\uD398\uC774\uC2A4"},{"inline":true,"label":"\uC624\uBC84\uB85C\uB529","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uC624\uBC84\uB85C\uB529"}],"readingTime":3.06,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java \uB2EC\uB825, API \uC120\uC815, OOP \uD575\uC2EC \uC815\uB9AC","date":"2026-03-05T00:00:00.000Z","tags":["Java","Calendar","LocalDate","OOP","\uC778\uD130\uD398\uC774\uC2A4","\uC624\uBC84\uB85C\uB529"]},"unlisted":false,"prevItem":{"title":"[TIL] Java \uCD94\uC0C1, \uC778\uD130\uD398\uC774\uC2A4\uC640 \uB2E4\uD615\uC131","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/06/java-abstract-polymorphism"},"nextItem":{"title":"[TIL] Java \uC218\uC5F4, \uBC30\uC5F4, \uBCF5\uC0AC, Object","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/04/java-array-copy-object"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.05\\n\\n## \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uB2EC\uB825 \uB85C\uC9C1 \uC644\uC131 \u2192 Calendar/LocalDate API \u2192 \uC624\uBC84\uB85C\uB529/\uC624\uBC84\uB77C\uC774\uB529/\uD558\uC774\uB529\\n\u2192 VMI\uC640 \uCC38\uC870 \uD0C0\uC785 \u2192 this/super\uC640 \uC0DD\uC131\uC790 \u2192 \uC778\uD130\uD398\uC774\uC2A4 \uAD6C\uC131\\n```\\n\\n---\\n\\n## 1. \uBA54\uC18C\uB4DC\uD615 \uB2EC\uB825 \uB85C\uC9C1 \uC644\uC131\\n\\n\uB2EC\uB825 \uCD9C\uB825\uC758 \uD575\uC2EC \uC804\uC81C: **1\uC77C\uC758 \uC694\uC77C**\uACFC **\uD574\uB2F9 \uC6D4 \uCD5C\uB300 \uC77C\uC218**.\\n\\n- \uC6D4 \uC778\uB371\uC2A4: \uC0AC\uC6A9\uC790 \uC785\uB825\uC740 1\uBD80\uD130 \u2192 \uBC30\uC5F4 \uC778\uB371\uC2A4\uB294 `month - 1`\uB85C \uBCF4\uC815 \uD544\uC218\\n- \uC904\uBC14\uAFC8 \uADDC\uCE59: `(\uCCAB \uC694\uC77C \uACF5\uBC31 + \uCD9C\uB825\uD55C \uC77C\uC218) % 7 == 0`\uC774\uBA74 \uC904\uBC14\uAFC8\\n- \uC774\uC804 \uB2EC \uB0A0\uC9DC: `month == 1`\uC774\uBA74 \uC804\uB2EC\uC740 12\uC6D4(31\uC77C \uACE0\uC815) \uCC98\uB9AC \u2014 `0\uC6D4` \uACC4\uC0B0 \uBC29\uC9C0\\n\\n:::warning\\n`+1` \uC624\uD504\uC14B \uB204\uB77D \uC2DC \uC774\uC804 \uB2EC \uC2DC\uC791 \uB0A0\uC9DC\uAC00 \uC5B4\uAE0B\uB098\uB294 off-by-one \uC624\uB958 \uBC1C\uC0DD \uC8FC\uC758.\\n\\n\uD14C\uC2A4\uD2B8 \uCF00\uC774\uC2A4: 4\uB144 2\uC6D4(29\uC77C), 5\uB144 2\uC6D4(28\uC77C)\uB85C \uC724\uB144/\uD3C9\uB144 \uAC80\uC99D.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC724\uB144` `\uC778\uB371\uC2A4-1` `printf` `\uBAA8\uB4C8\uB85C7` `\uC774\uC804/\uC774\uD6C4\uB2EC\uB825`\\n\\n---\\n\\n## 2. API \uC120\uC815 \uAE30\uC900\uACFC Calendar / LocalDate\\n\\n| \uAD6C\uBD84 | Calendar | LocalDate |\\n|------|----------|-----------|\\n| \uC6D4 \uC785\uB825 | 0\uBD80\uD130 \uC2DC\uC791 \u2192 `-1/+1` \uBC18\uBCF5 \uD544\uC694 | 1\uBD80\uD130 \uC2DC\uC791, \uC9C1\uAD00\uC801 |\\n| \uAC1D\uCCB4 \uC0DD\uC131 | `Calendar.getInstance()` | `LocalDate.of(year, month, 1)` |\\n| \uCD5C\uB300 \uC77C\uC218 | `getActualMaximum(Calendar.DAY_OF_MONTH)` | `lengthOfMonth()` |\\n| \uC774\uC804 \uB2EC | \uC6D4\uC5D0 \uC74C\uC218 \uC785\uB825 \uC2DC \uC790\uB3D9 \uBCF4\uC815 | `minusMonths(1)` |\\n| \uAD8C\uC7A5 \uBC84\uC804 | \uD638\uD658\uC131 \uD544\uC694 \uC2DC | Java 8 \uC774\uC0C1 \uAD8C\uC7A5 |\\n\\n:::info\\nAPI \uC120\uC815 \uAE30\uC900: **\uB9CE\uC774 \uC0AC\uC6A9\uB418\uB294\uAC00(\uD638\uD658\uC131)** + **\uCDE8\uC57D\uC810\uC774 \uC801\uC740\uAC00(\uBCF4\uC548/\uC720\uC9C0\uBCF4\uC218)**\\n\\nEclipse \uB9AC\uD329\uD130\uB9C1 \uB2E8\uCD95\uD0A4: `Alt + Shift + R` \u2014 \uBA54\uC18C\uB4DC/\uBCC0\uC218 \uC774\uB984 \uC5F0\uAD00 \uC0AC\uC6A9\uCC98\uAE4C\uC9C0 \uC77C\uAD04 \uBCC0\uACBD\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `API\uC120\uC815\uAE30\uC900` `Calendar.getInstance` `getActualMaximum` `LocalDate.of` `lengthOfMonth`\\n\\n---\\n\\n## 3. \uC624\uBC84\uB85C\uB529 vs \uC624\uBC84\uB77C\uC774\uB529 vs \uD558\uC774\uB529\\n\\n| \uAD6C\uBD84 | \uC870\uAC74 | \uB3D9\uC791 |\\n|------|------|------|\\n| \uC624\uBC84\uB85C\uB529 | \uAC19\uC740 \uD074\uB798\uC2A4, \uAC19\uC740 \uBA54\uC18C\uB4DC\uBA85, \uB2E4\uB978 \uC778\uC790 \uC2DC\uADF8\uB2C8\uCC98 | \uCEF4\uD30C\uC77C \uD0C0\uC784\uC5D0 \uC120\uD0DD |\\n| \uC624\uBC84\uB77C\uC774\uB529 | \uC0C1\uC18D \uAD00\uACC4, \uB3D9\uC77C \uC2DC\uADF8\uB2C8\uCC98 | \uB7F0\uD0C0\uC784\uC5D0 \uC790\uC2DD \uAD6C\uD604 \uC2E4\uD589 (VMI) |\\n| static \uD558\uC774\uB529 | \uB3D9\uC77C \uC2DC\uADF8\uB2C8\uCC98\uC758 static \uBA54\uC18C\uB4DC\uB97C \uC790\uC2DD\uC5D0 \uC120\uC5B8 | \uC624\uBC84\uB77C\uC774\uB529 \uC544\uB2D8, \uD074\uB798\uC2A4 \uAE30\uC900 \uD638\uCD9C |\\n| \uD544\uB4DC \uD558\uC774\uB529 | \uC790\uC2DD\uC774 \uBD80\uBAA8\uC640 \uAC19\uC740 \uC774\uB984\uC758 \uD544\uB4DC \uC120\uC5B8 | \uCC38\uC870 \uD0C0\uC785 \uAE30\uC900\uC73C\uB85C \uACB0\uC815 |\\n\\n:::info\\n\uC624\uBC84\uB85C\uB529 \uC131\uB9BD \uC870\uAC74: **\uC544\uADDC\uBA3C\uD2B8 \uC2DC\uADF8\uB2C8\uCC98(\uAC1C\uC218/\uD0C0\uC785)\uB9CC**\uC73C\uB85C \uAD6C\uBD84.\\n\\n\uC811\uADFC \uC81C\uD55C\uC790, \uBC18\uD658 \uD0C0\uC785, static \uC5EC\uBD80\uB294 \uC624\uBC84\uB85C\uB529 \uC131\uB9BD\uACFC \uBB34\uAD00.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC624\uBC84\uB85C\uB529` `\uC624\uBC84\uB77C\uC774\uB529` `static\uD558\uC774\uB529` `\uD544\uB4DC\uD558\uC774\uB529` `\uC5C5\uCE90\uC2A4\uD305`\\n\\n---\\n\\n## 4. VMI\uC640 \uCC38\uC870 \uD0C0\uC785\uC758 \uBA64\uBC84 \uB178\uCD9C\\n\\n| \uAD6C\uBD84 | \uACB0\uC815 \uAE30\uC900 |\\n|------|----------|\\n| \uC811\uADFC \uAC00\uB2A5\uD55C \uBA64\uBC84 (\uB178\uCD9C) | **\uCC38\uC870 \uBCC0\uC218\uC758 \uD0C0\uC785** |\\n| \uC624\uBC84\uB77C\uC774\uB529\uB41C \uBA54\uC18C\uB4DC \uC2E4\uD589 | **\uC2E4\uC81C \uC0DD\uC131\uB41C \uAC1D\uCCB4 \uD0C0\uC785** (VMI) |\\n| \uD544\uB4DC \uC811\uADFC | \uCC38\uC870 \uBCC0\uC218\uC758 \uD0C0\uC785 (\uD558\uC774\uB529) |\\n| static \uBA54\uC18C\uB4DC \uC2E4\uD589 | \uD074\uB798\uC2A4 \uAE30\uC900 (\uD558\uC774\uB529) |\\n\\n```java\\nParent p = new Child();\\np.parentMake();\\n// \uC120\uC5B8\uC740 Parent\uC5D0 \uC788\uC9C0\uB9CC \uC2E4\uD589\uC740 Child\uC758 \uC7AC\uC815\uC758 \uBA54\uC18C\uB4DC\\n```\\n\\n:::info\\n**\uC0C1\uC18D \uAD00\uACC4\uAC00 \uC5C6\uB294 \uCC38\uC870 \uD0C0\uC785\uB07C\uB9AC\uB294 \uD615\uBCC0\uD658 \uBD88\uAC00**.\\n\\n\uCC38\uC870\uD615 \uD615\uBCC0\uD658\uC758 \uC804\uC81C \uC870\uAC74\uC740 \uC0C1\uC18D \uAD00\uACC4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `VMI` `\uCC38\uC870\uD0C0\uC785` `\uC2E4\uC81C\uD0C0\uC785` `\uB2E4\uD615\uC131` `\uD615\uBCC0\uD658\uC804\uC81C`\\n\\n---\\n\\n## 5. this / super\uC640 \uC0DD\uC131\uC790\\n\\n| \uD0A4\uC6CC\uB4DC | \uC6A9\uB3C4 |\\n|--------|------|\\n| `this.\uD544\uB4DC` | \uB85C\uCEEC \uBCC0\uC218\uC640 \uBA64\uBC84 \uD544\uB4DC \uC774\uB984 \uCDA9\uB3CC \uC2DC \uBA64\uBC84 \uBA85\uC2DC |\\n| `this()` | \uAC19\uC740 \uD074\uB798\uC2A4 \uB0B4 \uB2E4\uB978 \uC0DD\uC131\uC790 \uD638\uCD9C (\uC0DD\uC131\uC790 \uCCB4\uC774\uB2DD) |\\n| `super()` | \uBD80\uBAA8 \uC0DD\uC131\uC790 \uD638\uCD9C \u2014 \uBD80\uBAA8\uC5D0 \uAE30\uBCF8 \uC0DD\uC131\uC790 \uC5C6\uC73C\uBA74 \uBA85\uC2DC \uD544\uC218 |\\n| `super.\uBA64\uBC84` | \uC790\uC2DD \uB0B4\uBD80\uC5D0\uC11C \uBD80\uBAA8 \uBA64\uBC84 \uCC38\uC870 |\\n\\n:::warning\\n\uC678\uBD80 \uCF54\uB4DC\uC5D0\uC11C \uC778\uC2A4\uD134\uC2A4\uB97C \uD1B5\uD574 \uBD80\uBAA8 \uBA64\uBC84\uB97C \uC9C1\uC811 \uC9C0\uC815 \uD638\uCD9C\uD558\uB294 \uAC83\uC740 \uBD88\uAC00\uB2A5.\\n\\n\uBD80\uBAA8 \uB3D9\uC791\uC744 \uD568\uAED8 \uC218\uD589\uD558\uB824\uBA74 \uC790\uC2DD \uBA54\uC18C\uB4DC \uB0B4\uBD80\uC5D0\uC11C `super.method()` \uD638\uCD9C \uD544\uC694.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `this()` `this.\uD544\uB4DC` `super()` `super.\uBA64\uBC84` `\uBD80\uBAA8\uD638\uCD9C\uC81C\uD55C`\\n\\n---\\n\\n## 6. \uC778\uD130\uD398\uC774\uC2A4 \uAD6C\uC131, \uAD6C\uD604, \uB124\uC2A4\uD2F0\uB4DC\\n\\n| \uAD6C\uBD84 | \uC778\uD130\uD398\uC774\uC2A4 | \uCD94\uC0C1 \uD074\uB798\uC2A4 |\\n|------|-----------|------------|\\n| \uC0DD\uC131\uC790 | \uC5C6\uC74C | \uC788\uC74C |\\n| \uD544\uB4DC | \uC790\uB3D9 `public static final` | \uC77C\uBC18 \uD074\uB798\uC2A4 \uADDC\uCE59 \uC801\uC6A9 |\\n| \uAD6C\uD604 \uAC15\uC81C | `implements` \u2014 \uBBF8\uAD6C\uD604 \uBA54\uC18C\uB4DC \uBC18\uB4DC\uC2DC \uC624\uBC84\uB77C\uC774\uB529 | `extends` \u2014 \uB3D9\uC77C |\\n| \uB2E4\uC911 \uC0C1\uC18D | \uAC00\uB2A5 (`extends A, B`) | \uBD88\uAC00 |\\n\\n```java\\n// Java 8 \uC774\uD6C4 \uC778\uD130\uD398\uC774\uC2A4 \uD655\uC7A5\\ndefault void defaultMethod() { ... }    // \uACF5\uD1B5 \uAD6C\uD604 \uBC30\uD3EC\\nstatic void staticMethod() { ... }      // \uC720\uD2F8\uB9AC\uD2F0\\nprivate void helperMethod() { ... }     // \uB0B4\uBD80 \uC911\uBCF5 \uB85C\uC9C1 \uBD84\uB9AC\\n```\\n\\n:::info\\n\uC778\uD130\uD398\uC774\uC2A4 \uD0C0\uC785\uC73C\uB85C \uAD6C\uD604\uCCB4\uB97C \uCC38\uC870\uD558\uBA74 VMI\uAC00 \uC790\uC5F0\uC2A4\uB7FD\uAC8C \uB3D9\uC791\uD55C\uB2E4.\\n\\n\uB124\uC2A4\uD2F0\uB4DC \uC778\uD130\uD398\uC774\uC2A4: \uC778\uD130\uD398\uC774\uC2A4 \uC548\uC5D0 \uC778\uD130\uD398\uC774\uC2A4\uB97C \uB450\uB294 \uBC29\uC2DD \u2014 \uC5ED\uD560 \uACC4\uCE35\uD654 \uBAA9\uC801.\\n\uAD6C\uD604 \uC2DC `Outer.Inner` \uD615\uD0DC\uB85C \uB0B4\uBD80 \uD0C0\uC785 \uC9C0\uC815.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `static final` `default\uBA54\uC18C\uB4DC` `implements` `\uB124\uC2A4\uD2F0\uB4DC\uC778\uD130\uD398\uC774\uC2A4` `\uC774\uB108\uD074\uB798\uC2A4`\\n\\n---\\n\\n## \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. \uB2EC\uB825 \uB85C\uC9C1: \uC6D4 \uC778\uB371\uC2A4\uB294 \uBC18\uB4DC\uC2DC `-1` \uBCF4\uC815, \uC774\uC804 \uB2EC 1\uC6D4 \uC608\uC678 \uCC98\uB9AC \uD544\uC218\\n2. `Calendar` = \uC6D4 0\uBD80\uD130, `LocalDate` = \uC6D4 1\uBD80\uD130 \u2014 Java 8 \uC774\uC0C1\uC774\uBA74 `LocalDate` \uAD8C\uC7A5\\n3. \uC624\uBC84\uB85C\uB529 = \uC778\uC790 \uC2DC\uADF8\uB2C8\uCC98\uB85C \uAD6C\uBD84 / \uC624\uBC84\uB77C\uC774\uB529 = \uC0C1\uC18D \uAD00\uACC4\uC5D0\uC11C \uC7AC\uC815\uC758\\n4. VMI = \uCC38\uC870 \uD0C0\uC785\uC73C\uB85C \uB178\uCD9C \uBC94\uC704 \uC81C\uD55C + \uC2E4\uC81C \uAC1D\uCCB4 \uD0C0\uC785\uC73C\uB85C \uBA54\uC18C\uB4DC \uC2E4\uD589\\n5. `this()` = \uC0DD\uC131\uC790 \uCCB4\uC774\uB2DD, `super()` = \uBD80\uBAA8 \uC0DD\uC131\uC790 \uD638\uCD9C\\n6. \uC778\uD130\uD398\uC774\uC2A4\uB294 \uB2E4\uC911 \uAD6C\uD604 \uAC00\uB2A5, \uD074\uB798\uC2A4 \uB2E4\uC911 \uC0C1\uC18D\uC740 \uBD88\uAC00"},{"id":"/2026/03/04/java-array-copy-object","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/04/java-array-copy-object","source":"@site/blog/2026-03-04-java-array-copy-object.md","title":"[TIL] Java \uC218\uC5F4, \uBC30\uC5F4, \uBCF5\uC0AC, Object","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.04","date":"2026-03-04T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"\uBC30\uC5F4","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uBC30\uC5F4"},{"inline":true,"label":"StringBuilder","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/string-builder"},{"inline":true,"label":"\uBCF5\uC0AC","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uBCF5\uC0AC"},{"inline":true,"label":"Object","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/object"}],"readingTime":3.68,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java \uC218\uC5F4, \uBC30\uC5F4, \uBCF5\uC0AC, Object","date":"2026-03-04T00:00:00.000Z","tags":["Java","\uBC30\uC5F4","StringBuilder","\uBCF5\uC0AC","Object"]},"unlisted":false,"prevItem":{"title":"[TIL] Java \uB2EC\uB825, API \uC120\uC815, OOP \uD575\uC2EC \uC815\uB9AC","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/05/java-calendar-oop"},"nextItem":{"title":"[TIL] Java \uC57D\uC218/\uC644\uC804\uC218/\uCE5C\uD654\uC218\uC640 \uBB38\uC790\uC5F4 \uC2EC\uD654","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/03/java-divisor-string"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.04\\n\\n## \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uAC1C\uBBF8 \uC218\uC5F4 \uAD6C\uD604 \u2192 \uB2E8\uACC4 \uBC18\uBCF5 \u2192 \uBB38\uC790\uC5F4 \uC131\uB2A5 \uCE21\uC815\\n\u2192 \uBC30\uC5F4 \uC120\uC5B8/\uCD08\uAE30\uD654 \u2192 Arrays \uC720\uD2F8\uB9AC\uD2F0\\n\u2192 \uAE30\uBCF8/\uCC38\uC870 \uD0C0\uC785 \uC804\uB2EC \uBC29\uC2DD \u2192 \uC595\uC740/\uAE4A\uC740 \uBCF5\uC0AC \u2192 Object \uD074\uB798\uC2A4\\n```\\n\\n---\\n\\n## 1. \uAC1C\uBBF8 \uC218\uC5F4(\uB8E9 \uC564 \uC138\uC774) \uAD6C\uD604\\n\\n\uC785\uB825 \uBB38\uC790\uC5F4\uC744 \uC67C\uCABD\uBD80\uD130 \uC77D\uC73C\uBA70 \uAC19\uC740 \uBB38\uC790\uC758 \uC5F0\uC18D \uAC1C\uC218\uB97C \uC138\uACE0 `\uBB38\uC790+\uAC1C\uC218` \uD615\uD0DC\uB85C \uB204\uC801\uD574 \uB2E4\uC74C \uD56D\uC744 \uC0DD\uC131\uD55C\uB2E4.\\n\\n```java\\nString process(String s) {\\n    char init = s.charAt(0);\\n    int cnt = 1;\\n    String answer = \\"\\";\\n\\n    for (int i = 1; i < s.length(); i++) {\\n        char cur = s.charAt(i);\\n        if (cur == init) {\\n            cnt++;\\n        } else {\\n            answer = answer + init + cnt;\\n            init = cur;\\n            cnt = 1;\\n        }\\n    }\\n    answer = answer + init + cnt; // \uB8E8\uD504 \uC885\uB8CC \uD6C4 \uB9C8\uC9C0\uB9C9 \uADF8\uB8F9 \uBC18\uB4DC\uC2DC \uB204\uC801\\n    return answer;\\n}\\n```\\n\\n:::warning\\n\uC785\uB825 \uBB38\uC790\uC5F4\uC774 \uBE44\uC5B4 \uC788\uAC70\uB098 \uC798\uBABB\uB41C \uBCC0\uC218\uB85C `charAt(0)`\uC744 \uD638\uCD9C\uD558\uBA74 `StringIndexOutOfBoundsException` \uBC1C\uC0DD.\\n\\n`else` \uBE14\uB85D\uC5D0\uC11C `init` \uAC31\uC2E0\uACFC `cnt = 1` \uB9AC\uC14B\uC744 \uB204\uB77D\uD558\uBA74 \uC798\uBABB\uB41C \uACB0\uACFC\uAC00 \uB098\uC628\uB2E4.\\n:::\\n\\n:::info\\n\uB8E8\uD504 \uAE30\uBC18 \uBB38\uC790\uC5F4 \uB204\uC801\uC740 `StringBuilder`\uB97C \uAE30\uC900\uC73C\uB85C \uC0BC\uB294 \uAC83\uC774 \uC548\uC804\uD558\uB2E4.\\n\\n\uC9E7\uC740 \uC5F0\uACB0(10\uD68C \uC774\uD558)\uC5D0\uC11C\uB294 concat\uB3C4 \uD5C8\uC6A9\uB418\uC9C0\uB9CC \uB8E8\uD504 \uC548\uC5D0\uC11C\uB294 \uBB34\uC870\uAC74 `StringBuilder`.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uB8E9\uC564\uC138\uC774` `\uAC1C\uBBF8\uC218\uC5F4` `StringIndexOutOfBoundsException` `StringBuilder` `\uB514\uBC84\uAE45`\\n\\n---\\n\\n## 2. \uAC1C\uBBF8 \uC218\uC5F4 \uB2E8\uACC4 \uBC18\uBCF5\\n\\n\uB2E8\uACC4 \uBC18\uBCF5\uC758 \uD575\uC2EC: \uB9E4 \uBC18\uBCF5\uB9C8\uB2E4 `result = process(prev)` \uC218\uD589 \uD6C4 \uACB0\uACFC\uB97C \uB2E4\uC2DC `prev`\uC5D0 \uC7AC\uB300\uC785.\\n\\n```\\n\uC0DD\uC131 \u2192 \uCD9C\uB825 \u2192 \uC7AC\uB300\uC785 \uC21C\uC11C\uB97C \uC720\uC9C0\uD574\uC57C \uC5F0\uC1C4 \uC0DD\uC131\uC774 \uB04A\uAE30\uC9C0 \uC54A\uB294\uB2E4.\\n```\\n\\n- \uC2DC\uC791\uAC12: `\\"1\\"` (1 \u2192 11 \u2192 21 \u2192 1211 \u2192 ...)\\n- \uBC18\uBCF5 \uD69F\uC218\uAC00 \uAE38\uC5B4\uC9C0\uBA74 \uCD9C\uB825\uB7C9\uC774 \uAE09\uC99D\uD558\uBBC0\uB85C \uD14C\uC2A4\uD2B8 \uB2E8\uACC4 \uC218\uB97C \uC81C\uD55C\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `stage` `\uC7AC\uB300\uC785` `\uBC18\uBCF5\uBB38` `process` `\uC774\uD130\uB808\uC774\uD130`\\n\\n---\\n\\n## 3. \uBB38\uC790\uC5F4 \uB204\uC801 \uC131\uB2A5 \uCE21\uC815 (Runtime, GC)\\n\\n```java\\nRuntime rt = Runtime.getRuntime();\\nrt.gc();\\n\\nlong memBefore = rt.totalMemory() - rt.freeMemory();\\nlong start = System.nanoTime();\\n\\n// \uBE44\uAD50\uD560 \uC5F0\uC0B0 \uBE14\uB85D (concat / StringBuilder / StringBuffer)\\n\\nlong end = System.nanoTime();\\nlong memAfter = rt.totalMemory() - rt.freeMemory();\\n\\nSystem.out.println(\\"\uC2E4\uD589\uC2DC\uAC04(ms): \\" + (end - start) / 1_000_000);\\nSystem.out.println(\\"\uC0AC\uC6A9\uBA54\uBAA8\uB9AC(KB): \\" + (memAfter - memBefore) / 1024);\\n```\\n\\n:::info\\n- `StringBuffer`\uB294 \uB3D9\uAE30\uD654\uB85C \uC778\uD574 \uB2E8\uC77C \uC2A4\uB808\uB4DC\uC5D0\uC11C `StringBuilder`\uBCF4\uB2E4 \uB290\uB9B4 \uC218 \uC788\uB2E4.\\n- GC\uB294 VM \uC0C1\uD669\uC5D0 \uB530\uB77C \uBE44\uACB0\uC815\uC801\uC774\uBBC0\uB85C \uACB0\uACFC \uD574\uC11D \uC2DC \uC804\uC81C \uC870\uAC74 \uD655\uC778 \uD544\uC694.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Runtime` `gc` `nanoTime` `StringBuffer` `\uBA54\uBAA8\uB9AC\uCE21\uC815`\\n\\n---\\n\\n## 4. \uBC30\uC5F4 \uC120\uC5B8\uACFC \uCD08\uAE30\uD654 (1\uCC28\uC6D0, 2\uCC28\uC6D0)\\n\\n\uBC30\uC5F4\uC740 \uD074\uB798\uC2A4\uAC00 \uC5C6\uB294 \uCC38\uC870 \uD0C0\uC785 \uAC1D\uCCB4. `new \uD0C0\uC785[\uD06C\uAE30]`\uB85C \uACF5\uAC04\uC744 \uD655\uBCF4\uD55C\uB2E4.\\n\\n| \uAD6C\uBD84 | \uC608\uC2DC | \uD2B9\uC9D5 |\\n|------|------|------|\\n| 1\uCC28\uC6D0 \uACF5\uAC04 \uC0DD\uC131 | `int[] a = new int[3];` | \uAE30\uBCF8\uAC12\uC73C\uB85C \uCD08\uAE30\uD654 (int\uB294 0) |\\n| 1\uCC28\uC6D0 \uB9AC\uD130\uB7F4 | `int[] a = {1,2,3};` | \uC6D0\uC18C \uAC1C\uC218\uB85C \uD06C\uAE30 \uACB0\uC815 |\\n| \uACF5\uAC04 \uD6C4 \uB300\uC785 | `a[0]=10; a[1]=11;` | \uBC94\uC704 \uBC97\uC5B4\uB098\uBA74 \uC608\uC678 \uBC1C\uC0DD |\\n| 2\uCC28\uC6D0 \uC120\uC5B8 | `int[][] m = new int[2][3];` | \\"\uBC30\uC5F4\uC758 \uBC30\uC5F4\\", \uB0B4\uBD80 \uBC30\uC5F4\uB3C4 \uCC38\uC870 |\\n\\n:::danger\\n\uC778\uB371\uC2A4\uB294 0\uBD80\uD130 \uC2DC\uC791, \uB9C8\uC9C0\uB9C9\uC740 `length - 1`.\\n\\n\uBC94\uC704 \uCD08\uACFC \uC2DC `ArrayIndexOutOfBoundsException` \uBC1C\uC0DD.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uCC38\uC870\uD0C0\uC785` `length` `ArrayIndexOutOfBoundsException` `2\uCC28\uC6D0\uBC30\uC5F4` `\uAE30\uBCF8\uAC12\uCD08\uAE30\uD654`\\n\\n---\\n\\n## 5. \uBC30\uC5F4 \uCD9C\uB825\uACFC Arrays \uC720\uD2F8\uB9AC\uD2F0\\n\\n\uBC30\uC5F4\uC744 \uADF8\uB300\uB85C `println`\uD558\uBA74 `\uD0C0\uC785@\uD574\uC2DC\uCF54\uB4DC` \uD615\uD0DC\uB85C \uCD9C\uB825\uB41C\uB2E4.\\n\\n| \uBC29\uC2DD | \uB300\uC0C1 | \uC7A5\uC810 | \uC8FC\uC758 |\\n|------|------|------|------|\\n| \uC778\uB371\uC2A4 \uC811\uADFC | 1/2\uCC28\uC6D0 | \uCD9C\uB825 \uBC94\uC704 \uC790\uC720\uB86D\uAC8C \uC81C\uC5B4 | \uC778\uB371\uC2A4 \uAD00\uB9AC \uC2E4\uC218 \uC8FC\uC758 |\\n| \uD5A5\uC0C1\uB41C for | 1\uCC28\uC6D0 | \uCF54\uB4DC \uAC04\uACB0 | \uC778\uB371\uC2A4 \uC81C\uC5B4 \uBD88\uAC00 |\\n| `Arrays.toString` | 1\uCC28\uC6D0 | \uD55C \uC904 \uCD9C\uB825 | \uAD6C\uBD84\uC790 \uD3EC\uD568, \uAC00\uACF5\uC5D0 \uBD80\uC801\uD569 |\\n| `Arrays.deepToString` | \uB2E4\uCC28\uC6D0 | \uC911\uCCA9 \uBC30\uC5F4 \uD55C \uBC88\uC5D0 \uCD9C\uB825 | \uB0A8\uC6A9 \uC2DC \uC7A5\uD669\uD574\uC9D0 |\\n\\n- `Arrays.sort()` \u2014 \uB3D9\uC77C \uBC30\uC5F4\uC744 \uC9C1\uC811 \uC815\uB82C\\n- `Arrays.fill()` \u2014 \uC804\uCCB4 \uC6D0\uC18C\uB97C \uD2B9\uC815 \uAC12\uC73C\uB85C \uC77C\uAD04 \uCD08\uAE30\uD654\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `java.util.Arrays` `toString` `sort` `fill` `\uD5A5\uC0C1\uB41Cfor`\\n\\n---\\n\\n## 6. \uAE30\uBCF8 \uD0C0\uC785 vs \uCC38\uC870 \uD0C0\uC785 \uC804\uB2EC \uBC29\uC2DD\\n\\n| \uD0C0\uC785 | \uC804\uB2EC \uBC29\uC2DD | \uBA54\uC18C\uB4DC \uB0B4 \uBCC0\uACBD \uC2DC |\\n|------|----------|----------------|\\n| \uAE30\uBCF8 \uD0C0\uC785 (`int`) | \uAC12 \uBCF5\uC81C | \uC6D0\uBCF8 \uBCF4\uC874 |\\n| \uCC38\uC870 \uD0C0\uC785 (`int[]`) | \uC8FC\uC18C\uAC12 \uBCF5\uC81C | \uC6D0\uBCF8\uB3C4 \uBCC0\uACBD\uB428 |\\n\\n:::info\\n\uC790\uBC14\uB294 \uC624\uC9C1 **pass-by-value**\uB9CC \uC874\uC7AC\uD55C\uB2E4.\\n\\n\uCC38\uC870 \uD0C0\uC785\uC740 \\"\uC8FC\uC18C\uAC12 \uC790\uCCB4\uAC00 \uAC12\\"\uC73C\uB85C \uBCF5\uC81C \uC804\uB2EC\uB418\uB294 \uAC83\uC774\uC9C0, \uAC1D\uCCB4 \uC790\uCCB4\uAC00 \uC804\uB2EC\uB418\uB294 \uAC8C \uC544\uB2C8\uB2E4.\\n:::\\n\\n:::warning\\n\uCC38\uC870 \uACF5\uC720\uB294 \uC758\uB3C4\uCE58 \uC54A\uC740 \uC0AC\uC774\uB4DC \uC774\uD399\uD2B8\uB97C \uB9CC\uB4E4 \uC218 \uC788\uC73C\uBBC0\uB85C \uBCF5\uC81C \uC804\uB7B5\uC774 \uD544\uC694\uD558\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uAE30\uBCF8\uD0C0\uC785` `\uCC38\uC870\uD0C0\uC785` `pass-by-value` `\uC8FC\uC18C\uAC12` `\uC624\uBC84\uB85C\uB529`\\n\\n---\\n\\n## 7. \uC595\uC740 \uBCF5\uC0AC vs \uAE4A\uC740 \uBCF5\uC0AC\\n\\n| \uBC29\uC2DD | \uC124\uBA85 | \uB3C5\uB9BD\uC131 |\\n|------|------|--------|\\n| \uC595\uC740 \uBCF5\uC0AC | `arrCopy = arr` \u2014 \uAC19\uC740 \uC8FC\uC18C \uACF5\uC720 | \uC5C6\uC74C (\uBCC0\uACBD \uC804\uD30C) |\\n| \uC778\uB371\uC2A4 \uBCF5\uC0AC | `for (copy[i] = src[i])` | \uC788\uC74C |\\n| `clone()` | `src.clone()` | \uC788\uC74C (\uBC30\uC5F4 \uAE30\uC900) |\\n| `System.arraycopy` | `System.arraycopy(src, sPos, dst, dPos, len)` | \uC788\uC74C, \uAD6C\uAC04 \uBCF5\uC0AC \uAC15\uC810 |\\n\\n:::info\\n\uAE4A\uC740 \uBCF5\uC0AC \uD655\uC778: `hashCode()`\uAC00 \uB2E4\uB974\uBA74 \uB3C5\uB9BD\uB41C \uAC1D\uCCB4.\\n\\n\uC595\uC740 \uBCF5\uC0AC\uB294 \uB3D9\uC77C \uD574\uC2DC\uCF54\uB4DC, \uAE4A\uC740 \uBCF5\uC0AC\uB294 \uC11C\uB85C \uB2E4\uB978 \uD574\uC2DC\uCF54\uB4DC.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `ShallowCopy` `DeepCopy` `clone` `System.arraycopy` `hashCode`\\n\\n---\\n\\n## 8. Object \uCD5C\uC0C1\uC704 \uD074\uB798\uC2A4\\n\\n\uBAA8\uB4E0 \uC790\uBC14 \uD074\uB798\uC2A4\uB294 \uBA85\uC2DC\uD558\uC9C0 \uC54A\uC544\uB3C4 `Object`\uB97C \uC0C1\uC18D\uD55C\uB2E4.\\n\\n| \uBA54\uC18C\uB4DC | \uC5ED\uD560 |\\n|--------|------|\\n| `getClass()` | \uB7F0\uD0C0\uC784 \uD0C0\uC785 \uC815\uBCF4 \uBC18\uD658 |\\n| `toString()` | \uAE30\uBCF8 \uCD9C\uB825: `\uD074\uB798\uC2A4\uBA85@\uD574\uC2DC\uCF54\uB4DC(16\uC9C4\uC218)` |\\n| `equals()` | \uAC1D\uCCB4 \uBE44\uAD50 \u2014 \uAE30\uBCF8\uC740 \uC815\uCCB4\uC131 \uAE30\uBC18, \uAC12 \uBE44\uAD50 \uD544\uC694 \uC2DC \uC624\uBC84\uB77C\uC774\uB529 |\\n| `hashCode()` | \uACE0\uC720\uC131 \uD655\uC778, `equals`\uC640 \uC30D\uC73C\uB85C \uC624\uBC84\uB77C\uC774\uB529 |\\n\\n:::info\\n\uBC30\uC5F4\uC744 \uADF8\uB0E5 \uCD9C\uB825\uD588\uC744 \uB54C `@` \uD45C\uAE30\uAC00 \uB098\uC624\uB294 \uC774\uC720 = `Object`\uC758 \uAE30\uBCF8 `toString()` \uB3D9\uC791 \uB54C\uBB38.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `java.lang.Object` `getClass` `toString` `equals` `\uC0C1\uC18D`\\n\\n---\\n\\n## \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. \uAC1C\uBBF8 \uC218\uC5F4: \uCD08\uAE30\uAC12 \uC124\uC815 + \uB8E8\uD504 \uC885\uB8CC \uD6C4 \uB9C8\uC9C0\uB9C9 \uADF8\uB8F9 \uB204\uC801 \uD544\uC218\\n2. \uB8E8\uD504 \uB0B4 \uBB38\uC790\uC5F4 \uB204\uC801\uC740 \uBB34\uC870\uAC74 `StringBuilder`\\n3. \uBC30\uC5F4 \uCD9C\uB825 \uC2DC \uADF8\uB0E5 `println`\uD558\uBA74 \uC8FC\uC18C \uCD9C\uB825\uB428 \u2192 `Arrays.toString` \uB610\uB294 \uBC18\uBCF5\uBB38 \uC0AC\uC6A9\\n4. \uC790\uBC14\uB294 pass-by-value\uB9CC \uC874\uC7AC \u2014 \uCC38\uC870 \uD0C0\uC785\uC740 \uC8FC\uC18C\uAC12\uC774 \uBCF5\uC81C\uB428\\n5. \uC595\uC740 \uBCF5\uC0AC = \uC8FC\uC18C \uACF5\uC720, \uAE4A\uC740 \uBCF5\uC0AC = \uB3C5\uB9BD \uAC1D\uCCB4\\n6. \uBAA8\uB4E0 \uD074\uB798\uC2A4\uB294 `Object`\uB97C \uC0C1\uC18D \u2014 `toString`, `equals`\uC758 \uAE30\uBCF8 \uB3D9\uC791 \uC774\uD574 \uD544\uC218"},{"id":"/2026/03/03/java-divisor-string","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/03/java-divisor-string","source":"@site/blog/2026-03-03-java-divisor-string.md","title":"[TIL] Java \uC57D\uC218/\uC644\uC804\uC218/\uCE5C\uD654\uC218\uC640 \uBB38\uC790\uC5F4 \uC2EC\uD654","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.03","date":"2026-03-03T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"\uC54C\uACE0\uB9AC\uC998","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uC54C\uACE0\uB9AC\uC998"},{"inline":true,"label":"String","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/string"},{"inline":true,"label":"\uC815\uADDC\uD45C\uD604\uC2DD","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uC815\uADDC\uD45C\uD604\uC2DD"},{"inline":true,"label":"DTO","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/dto"}],"readingTime":4.72,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java \uC57D\uC218/\uC644\uC804\uC218/\uCE5C\uD654\uC218\uC640 \uBB38\uC790\uC5F4 \uC2EC\uD654","date":"2026-03-03T00:00:00.000Z","tags":["Java","\uC54C\uACE0\uB9AC\uC998","String","\uC815\uADDC\uD45C\uD604\uC2DD","DTO"]},"unlisted":false,"prevItem":{"title":"[TIL] Java \uC218\uC5F4, \uBC30\uC5F4, \uBCF5\uC0AC, Object","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/04/java-array-copy-object"},"nextItem":{"title":"[TIL] Java final\uACFC \uC0C1\uC18D, \uC7AC\uC815\uC758","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/27/java-final-inheritance"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.03.03\\n\\n## \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uC9C4\uC57D\uC218 \uD569 \u2192 \uC644\uC804\uC218 \u2192 \uCE5C\uD654\uC218 \u2192 \uAE30\uBCF8 \uC0DD\uC131\uC790\\n\u2192 String \uD574\uC2DC\uCF54\uB4DC/intern \u2192 DTO equals/hashCode\\n\u2192 String API \u2192 \uAE38\uC774 \uCE21\uC815 \uADDC\uCE59 \u2192 \uD14D\uC2A4\uD2B8 \uBE14\uB85D\\n```\\n\\n---\\n\\n## 1. \uC9C4\uC57D\uC218 \uD569\uACFC \uC57D\uC218 \uD310\uBCC4 \uBA54\uC18C\uB4DC\\n\\n\uC9C4\uC57D\uC218 = \uC790\uAE30 \uC790\uC2E0\uC744 \uC81C\uC678\uD55C \uC57D\uC218. \uBC18\uBCF5 \uBC94\uC704\uB294 1\uBD80\uD130 n-1\uAE4C\uC9C0.\\n\\n\uC57D\uC218 \uD310\uBCC4 \uB85C\uC9C1\uC744 \uBCC4\uB3C4 \uBA54\uC18C\uB4DC\uB85C \uBD84\uB9AC\uD558\uBA74 \uC644\uC804\uC218/\uCE5C\uD654\uC218 \uBB38\uC81C\uC5D0\uC11C \uC7AC\uC0AC\uC6A9 \uAC00\uB2A5\uD558\uB2E4.\\n\\n```java\\npublic boolean isCheck(int num, int chkNum) {\\n    boolean isCheck = false;\\n    if (num % chkNum == 0) {\\n        isCheck = true;\\n    }\\n    return isCheck;\\n}\\n\\npublic void divisorSum(int num) {\\n    int cnt = 0;\\n    int sum = 0;\\n\\n    for (int i = 1; i < num; i++) {\\n        if (isCheck(num, i)) {\\n            cnt++;\\n            sum += i;\\n        }\\n    }\\n    System.out.printf(\\"%d\uC758 \uC9C4\uC57D\uC218 \uAC1C\uC218\uB294 %d, \uD569\uC740 %d\uC785\uB2C8\uB2E4.%n\\", num, cnt, sum);\\n}\\n```\\n\\n:::info\\n\uC57D\uC218 \uD310\uBCC4\uC744 \uACF5\uD1B5 \uBA54\uC18C\uB4DC\uB85C \uBD84\uB9AC\uD558\uBA74 **\uC751\uC9D1\uB3C4\uB294 \uB192\uC774\uACE0 \uACB0\uD569\uB3C4\uB294 \uB0AE\uCD9C \uC218 \uC788\uB2E4.**\\n\\n\uBC18\uBCF5\uC5D0\uC11C 0\uC744 \uC81C\uC678\uD558\uB294 \uAC83\uB9CC\uC73C\uB85C\uB3C4 \uBD88\uD544\uC694\uD55C \uC5F0\uC0B0\uC744 \uC904\uC77C \uC218 \uC788\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC9C4\uC57D\uC218` `\uBAA8\uB4C8\uB7EC(%)` `\uBA54\uC18C\uB4DC \uBD84\uB9AC` `\uC751\uC9D1\uB3C4/\uACB0\uD569\uB3C4` `printf`\\n\\n---\\n\\n## 2. \uC644\uC804\uC218 \uD310\uBCC4\uACFC private \uBA54\uC18C\uB4DC \uC124\uACC4\\n\\n\uC644\uC804\uC218 = \uC790\uAE30 \uC790\uC2E0 == \uC9C4\uC57D\uC218\uC758 \uD569\uC778 \uC218. (\uC608: 6 = 1+2+3)\\n\\n\uB0B4\uBD80 \uACC4\uC0B0\uC6A9 \uBA54\uC18C\uB4DC\uB294 `private`, \uC678\uBD80\uC5D0\uB294 \uBC94\uC704 \uCD9C\uB825\uC6A9 `public` \uBA54\uC18C\uB4DC\uB9CC \uB178\uCD9C\uD55C\uB2E4.\\n\\n```java\\nprivate boolean isCheck(int num, int chkNum) {\\n    return (num % chkNum == 0) ? true : false;\\n}\\n\\nprivate int divisorSum(int num) {\\n    int sum = 0;\\n    for (int i = 1; i < num; i++) {\\n        if (isCheck(num, i)) {\\n            sum += i;\\n        }\\n    }\\n    return sum;\\n}\\n\\npublic void perfectNum(int range) {\\n    for (int i = 2; i <= range; i++) {\\n        if (i == divisorSum(i)) {\\n            System.out.println(i + \\"\uB294 \uC644\uC804\uC218\uB85C \uD310\uB2E8\uB428\\");\\n        }\\n    }\\n}\\n```\\n\\n:::info\\n\uCEA1\uC290\uD654 \uAD00\uC810\uC5D0\uC11C \uC678\uBD80\uC5D0\uC11C \uC9C1\uC811 \uD638\uCD9C\uD560 \uD544\uC694\uAC00 \uC5C6\uB294 \uBA54\uC18C\uB4DC\uB294 `private`\uC73C\uB85C \uC228\uAE34\uB2E4.\\n\\n`return`\uC774 \uB204\uB77D\uB418\uBA74 \uCEF4\uD30C\uC77C \uC624\uB958 \uBC1C\uC0DD \u2014 \uBC18\uD658 \uD0C0\uC785\uC774 \uC788\uB294 \uBA54\uC18C\uB4DC\uB294 \uBC18\uB4DC\uC2DC \uBC18\uD658\uAC12\uC774 \uC874\uC7AC\uD574\uC57C \uD55C\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC644\uC804\uC218` `private` `\uCEA1\uC290\uD654` `\uBC18\uD658(return)` `\uC0BC\uD56D\uC5F0\uC0B0\uC790`\\n\\n---\\n\\n## 3. \uCE5C\uD654\uC218 \uB85C\uC9C1\uACFC \uB300\uC785 \uD2B9\uC131 \uD65C\uC6A9\\n\\n\uCE5C\uD654\uC218 = A\uC758 \uC9C4\uC57D\uC218 \uD569\uC774 B\uC774\uACE0, B\uC758 \uC9C4\uC57D\uC218 \uD569\uC774 \uB2E4\uC2DC A\uAC00 \uB418\uB294 \uC30D.\\n\\n```\\nsumProperDivisors(A) = B\\nsumProperDivisors(B) = A\\n(\uB2E8, A != B)\\n```\\n\\n\uB300\uC785 \uC5F0\uC0B0\uC758 \uD575\uC2EC: **\uB300\uC785 \uC2DC\uC810\uC758 \uAC12\uC774 \uBCF5\uC0AC\uB418\uC5B4 \uC720\uC9C0**\uB418\uBBC0\uB85C \uC911\uAC04 \uACB0\uACFC\uB97C \uBE44\uAD50 \uAE30\uC900\uC73C\uB85C \uC548\uC804\uD558\uAC8C \uBCF4\uAD00\uD560 \uC218 \uC788\uB2E4.\\n\\n- \uC2E4\uC2B5 \uC608\uC2DC: 220 \u2194 284\\n- \uC9C4\uC57D\uC218 \uD569 \uD568\uC218\uB97C 2\uD68C \uD638\uCD9C\uD558\uB294 \uAD6C\uC870 \u2192 \uBA54\uC18C\uB4DC \uC7AC\uC0AC\uC6A9 \uC124\uACC4\uAC00 \uC720\uB9AC\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uCE5C\uD654\uC218` `\uB300\uC785\uC5F0\uC0B0\uC790` `\uC911\uAC04\uACB0\uACFC \uBE44\uAD50` `\uBA54\uC18C\uB4DC \uC7AC\uC0AC\uC6A9` `\uC54C\uACE0\uB9AC\uC998 \uC124\uACC4`\\n\\n---\\n\\n## 4. \uAE30\uBCF8 \uC0DD\uC131\uC790\uC640 \uAC1D\uCCB4 \uC778\uC2A4\uD134\uC2A4\uD654\\n\\n\uBCC4\uB3C4 \uC0DD\uC131\uC790\uB97C \uC120\uC5B8\uD558\uC9C0 \uC54A\uC73C\uBA74 \uC790\uBC14\uAC00 \uB514\uD3F4\uD2B8 \uC0DD\uC131\uC790\uB97C \uC554\uBB35\uC801\uC73C\uB85C \uC81C\uACF5\uD55C\uB2E4.\\n\\n- \uB514\uD3F4\uD2B8 \uC0DD\uC131\uC790: \uD074\uB798\uC2A4\uBA85\uACFC \uAC19\uC740 \uC774\uB984, \uBC18\uD658 \uD0C0\uC785 \uC5C6\uC74C\\n- `new` = \uD799\uC5D0 \uAC1D\uCCB4 \uC0DD\uC131 \uD6C4 \uCC38\uC870(\uC8FC\uC18C) \uBC18\uD658\\n- \uAC1D\uCCB4 \uC0DD\uC131 \uD6C4\uC5D0\uC57C \uBA54\uC18C\uB4DC \uD638\uCD9C \uAC00\uB2A5\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uB514\uD3F4\uD2B8 \uC0DD\uC131\uC790` `new` `\uC778\uC2A4\uD134\uC2A4\uD654` `\uCC38\uC870(\uC8FC\uC18C)` `\uD799 \uBA54\uBAA8\uB9AC`\\n\\n---\\n\\n## 5. String \uD574\uC2DC\uCF54\uB4DC\uC640 identityHashCode, intern\\n\\n| \uBA54\uC18C\uB4DC | \uB3D9\uC791 |\\n|--------|------|\\n| `hashCode()` | String\uC5D0\uC11C \uAC12 \uAE30\uBC18\uC73C\uB85C \uC624\uBC84\uB77C\uC774\uB529 \u2014 \uB0B4\uC6A9 \uAC19\uC73C\uBA74 \uAC19\uC740 \uAC12 |\\n| `System.identityHashCode()` | VM\uC774 \uBD80\uC5EC\uD55C \uC815\uCCB4\uC131 \uAE30\uBC18 \uD574\uC2DC \u2014 \uC624\uBC84\uB77C\uC774\uB529 \uBB34\uC2DC |\\n| `intern()` | String \uD480\uC758 \uB3D9\uC77C \uB9AC\uD130\uB7F4\uC744 \uCC38\uC870\uD558\uB3C4\uB85D \uC720\uB3C4 |\\n| `==` | \uCC38\uC870(\uC8FC\uC18C) \uBE44\uAD50 \u2014 \uAC19\uC740 \uAC1D\uCCB4\uB97C \uAC00\uB9AC\uD0A4\uC9C0 \uC54A\uC73C\uBA74 \uAC70\uC9D3 |\\n\\n```java\\nString a = new String(\\"hello\\");\\nString b = new String(\\"hello\\");\\n\\na == b            // false (\uC11C\uB85C \uB2E4\uB978 \uAC1D\uCCB4)\\na.equals(b)       // true  (\uAC12 \uB3D9\uC77C)\\na.hashCode() == b.hashCode()  // true (\uAC12 \uAE30\uBC18 hashCode)\\nSystem.identityHashCode(a) == System.identityHashCode(b)  // false (\uC815\uCCB4\uC131 \uAE30\uBC18)\\na.intern() == b.intern()  // true (String \uD480 \uB3D9\uC77C \uCC38\uC870)\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `String \uD480` `hashCode()` `System.identityHashCode()` `intern()` `\uCC38\uC870 \uBE44\uAD50(==)`\\n\\n---\\n\\n## 6. DTO equals/hashCode \uC624\uBC84\uB77C\uC774\uB529\uACFC \uAC1D\uCCB4 \uBE44\uAD50\\n\\n| \uBE44\uAD50 \uD56D\uBAA9 | \uC624\uBC84\uB77C\uC774\uB529 \uC804 | \uC624\uBC84\uB77C\uC774\uB529 \uD6C4 |\\n|----------|-------------|-------------|\\n| `dto1 == dto2` | false (\uB2E4\uB978 \uAC1D\uCCB4) | false (\uB2E4\uB978 \uAC1D\uCCB4) |\\n| `dto1.hashCode()` | \uC815\uCCB4\uC131 \uAE30\uBC18, \uC11C\uB85C \uB2E4\uB984 | \uD544\uB4DC \uAC12 \uAE30\uBC18, \uAC19\uC744 \uC218 \uC788\uC74C |\\n| `System.identityHashCode(dto)` | VM \uAE30\uBC18, \uC11C\uB85C \uB2E4\uB984 | VM \uAE30\uBC18, \uC11C\uB85C \uB2E4\uB984 |\\n| `dto1.equals(dto2)` | false (Object \uAE30\uBCF8 \uAD6C\uD604) | \uAC12 \uAC19\uC73C\uBA74 true |\\n\\n:::info\\n`equals()`/`hashCode()`\uB97C \uAC12 \uAE30\uBC18\uC73C\uB85C \uC624\uBC84\uB77C\uC774\uB529\uD558\uBA74 \uCEEC\uB809\uC158(JCF)\uC5D0\uC11C \uC911\uBCF5 \uD310\uB2E8\uACFC \uD0A4 \uB3D9\uC791\uC5D0 \uC9C1\uC811 \uC601\uD5A5\uC744 \uC900\uB2E4.\\n\\n\uBA64\uBC84 \uD544\uB4DC\uB294 `private`\uC73C\uB85C \uB450\uACE0 getter/setter\uB85C \uC81C\uC5B4\uD558\uB294 \uAC83\uC774 \uCEA1\uC290\uD654\uC758 \uCD9C\uBC1C\uC810\uC774\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `DTO` `equals()` `hashCode()` `\uC624\uBC84\uB77C\uC774\uB529` `\uCEA1\uC290\uD654(getter/setter)`\\n\\n---\\n\\n## 7. String \uBA54\uC18C\uB4DC\uC640 \uC815\uADDC\uD45C\uD604\uC2DD \uAE30\uBC18 \uC720\uD6A8\uC131 \uCC98\uB9AC\\n\\n### \uACF5\uBC31 \uAC80\uC99D\\n\\n| \uBA54\uC18C\uB4DC | \uB3D9\uC791 |\\n|--------|------|\\n| `isEmpty()` | \uAE38\uC774\uAC00 0\uC778 \uACBD\uC6B0\uB9CC true (\uACF5\uBC31 \uBB38\uC790\uC5F4\uC740 false) |\\n| `isBlank()` | \uACF5\uBC31/\uD0ED \uB4F1\uC73C\uB85C\uB9CC \uAD6C\uC131\uB41C \uACBD\uC6B0\uB3C4 true |\\n| `trim()` | \uC55E\uB4A4 \uD654\uC774\uD2B8\uC2A4\uD398\uC774\uC2A4 \uC81C\uAC70 |\\n\\n:::warning\\n\uC0AC\uC6A9\uC790\uAC00 \uC2A4\uD398\uC774\uC2A4\uB97C \uC785\uB825\uD558\uBA74 \uB208\uC73C\uB85C\uB294 \uAC19\uC544 \uBCF4\uC5EC\uB3C4 `isEmpty()`\uB294 false\uAC00 \uB41C\uB2E4.\\n\\n`trim()` \uB610\uB294 \uC815\uADDC\uC2DD\uC73C\uB85C \uCD94\uAC00 \uC815\uC81C\uAC00 \uD544\uC694\uD558\uB2E4.\\n:::\\n\\n### replaceAll + \uC815\uADDC\uD45C\uD604\uC2DD\\n\\n```java\\nString str = \\"!T%123abC\\";\\nString regex = \\"[^0-9a-zA-Z]\\";  // \uC22B\uC790/\uC601\uBB38\uC790 \uC678 \uC81C\uAC70\\nString result = str.replaceAll(regex, \\"\\");\\n// \uACB0\uACFC: \\"T123abC\\"\\n```\\n\\n### \uBB38\uC790\uC5F4 \uACB0\uD569 \uCD5C\uC801\uD654\\n\\n```java\\n// \uBE48\uBC88\uD55C \uACB0\uD569 \uC2DC StringBuilder \uAD8C\uC7A5\\nStringBuilder sb = new StringBuilder();\\nsb.append(\\"hello\\").append(\\" \\").append(\\"world\\");\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `replaceAll` `\uC815\uADDC\uD45C\uD604\uC2DD` `isBlank` `trim` `StringBuilder`\\n\\n---\\n\\n## 8. \uBB38\uC790\uC5F4 \uBD84\uD574, \uD0D0\uC0C9\uACFC \uC778\uB371\uC2A4 \uC608\uC678\\n\\n| \uBA54\uC18C\uB4DC | \uC131\uACF5 \uC2DC | \uC2E4\uD328/\uBC94\uC704 \uCD08\uACFC \uC2DC |\\n|--------|---------|----------------|\\n| `substring(begin, end)` | \uC0C8 \uBB38\uC790\uC5F4 \uBC18\uD658 (end \uBBF8\uD3EC\uD568) | \uBC94\uC704 \uC798\uBABB\uB418\uBA74 \uC608\uC678 |\\n| `charAt(i)` | \uD574\uB2F9 \uC778\uB371\uC2A4 \uBB38\uC790 \uBC18\uD658 | \uC778\uB371\uC2A4 \uCD08\uACFC \uC2DC `StringIndexOutOfBoundsException` |\\n| `indexOf(str)` | \uCCAB \uC704\uCE58 \uC778\uB371\uC2A4 \uBC18\uD658 | \uCC3E\uC9C0 \uBABB\uD558\uBA74 **-1** \uBC18\uD658 |\\n| `contains(str)` | `true` | `false` |\\n\\n```java\\n// \uBA54\uC77C \uC8FC\uC18C \uBD84\uD574 \uC608\uC2DC\\nString email = \\"hello@gmail.com\\";\\nint atIdx = email.indexOf(\'@\');   // 5\\nString id = email.substring(0, atIdx);  // \\"hello\\"\\nString domain = email.substring(atIdx + 1);  // \\"gmail.com\\"\\n```\\n\\n:::warning\\n`indexOf()` \uACB0\uACFC\uB85C `substring()`\uC744 \uC5F0\uACB0\uD560 \uB54C **-1 \uCC98\uB9AC \uB204\uB77D**\uC774 \uB17C\uB9AC \uC624\uB958\uB85C \uC774\uC5B4\uC9C8 \uC218 \uC788\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `substring` `charAt` `indexOf` `contains` `\uC778\uB371\uC2A4 \uC608\uC678`\\n\\n---\\n\\n## 9. \uAE38\uC774 \uCE21\uC815 \uADDC\uCE59: length vs length() vs size()\\n\\n| \uD0C0\uC785 | \uC0AC\uC6A9 \uBC29\uBC95 | \uC774\uC720 |\\n|------|----------|------|\\n| \uBC30\uC5F4(Array) | `arr.length` | \uACE0\uC815 \uAE38\uC774 \uD544\uB4DC |\\n| \uBB38\uC790\uC5F4(String) | `str.length()` | \uBA54\uC18C\uB4DC |\\n| \uCEEC\uB809\uC158(JCF) | `collection.size()` | \uBA54\uC18C\uB4DC |\\n\\n:::info\\n\uBC18\uBCF5\uBB38\uACFC \uC778\uB371\uC2F1\uC758 \uC804\uC81C\uC870\uAC74\uC774\uBBC0\uB85C \uD0C0\uC785\uBCC4 \uAD6C\uBD84\uC744 \uBA85\uD655\uD788 \uD574\uC57C \uD55C\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `length` `length()` `size()` `\uBC30\uC5F4` `JCF`\\n\\n---\\n\\n## 10. \uD14D\uC2A4\uD2B8 \uBE14\uB85D (Java 13~17)\\n\\n\uC5EC\uB7EC \uC904 \uBB38\uC790\uC5F4\uC744 `\\"\\"\\"`\uB85C \uD45C\uD604\uD558\uB294 \uBB38\uBC95. HTML/JSON \uAC19\uC740 \uBA40\uD2F0\uB77C\uC778 \uD14D\uC2A4\uD2B8 \uC791\uC131\uC5D0 \uC720\uC6A9\uD558\uB2E4.\\n\\n```java\\nString s = \\"\\"\\"\\n\uC548\uB155\uD558\uC138\uC694.\\n\uBC18\uAC11\uC2B5\uB2C8\uB2E4.\\n\\"\\"\\";\\n```\\n\\n:::danger\\n\uC2DC\uC791 `\\"\\"\\"` \uB4A4\uC5D0 **\uC989\uC2DC \uC5D4\uD130**\uB97C \uCE58\uACE0 \uB0B4\uC6A9\uC744 \uC791\uC131\uD574\uC57C \uD55C\uB2E4.\\n\\n\uC904\uBC14\uAFC8 \uB204\uB77D \uC2DC \uCEF4\uD30C\uC77C \uC624\uB958 \uBC1C\uC0DD.\\n:::\\n\\n:::warning\\n\uB208\uC5D0 \uBCF4\uC774\uB294 \uBB38\uC790\uC5F4\uC774 \uAC19\uC544\uB3C4 \uAC1C\uD589 \uD3EC\uD568 \uC5EC\uBD80\uC5D0 \uB530\uB77C \uBE44\uAD50 \uACB0\uACFC\uAC00 \uB2EC\uB77C\uC9C8 \uC218 \uC788\uB2E4.\\n\\n\uBB38\uC790\uC5F4 \uBE44\uAD50\uB294 `==`\uAC00 \uC544\uB2C8\uB77C `equals()`\uB97C \uAE30\uBCF8\uC73C\uB85C \uC0AC\uC6A9\uD560 \uAC83.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD14D\uC2A4\uD2B8 \uBE14\uB85D` `Java 13` `Java 17` `\uBA40\uD2F0\uB77C\uC778 \uBB38\uC790\uC5F4` `equals()`\\n\\n---\\n\\n## \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. \uC57D\uC218 \uD310\uBCC4 \uB85C\uC9C1\uC740 \uBA54\uC18C\uB4DC\uB85C \uBD84\uB9AC \u2192 \uC644\uC804\uC218/\uCE5C\uD654\uC218\uC5D0\uC11C \uC7AC\uC0AC\uC6A9\\n2. \uB0B4\uBD80 \uACC4\uC0B0\uC6A9 \uBA54\uC18C\uB4DC\uB294 `private`, \uC678\uBD80 \uC778\uD130\uD398\uC774\uC2A4\uB9CC `public`\\n3. `==`\uB294 \uCC38\uC870 \uBE44\uAD50, \uAC12 \uBE44\uAD50\uB294 `equals()` \uC0AC\uC6A9\\n4. `hashCode()`\uB294 String\uC5D0\uC11C \uAC12 \uAE30\uBC18\uC73C\uB85C \uC624\uBC84\uB77C\uC774\uB529\uB428\\n5. `isEmpty()` vs `isBlank()` \u2014 \uACF5\uBC31 \uBB38\uC790\uC5F4 \uCC98\uB9AC \uB2E4\uB984\\n6. `indexOf()` \uC2E4\uD328 \uC2DC **-1** \uBC18\uD658 \u2192 \uCC98\uB9AC \uB204\uB77D \uC8FC\uC758\\n7. \uBC30\uC5F4 = `length`, \uBB38\uC790\uC5F4 = `length()`, \uCEEC\uB809\uC158 = `size()`\\n8. \uD14D\uC2A4\uD2B8 \uBE14\uB85D \uC2DC\uC791 `\\"\\"\\"` \uB4A4\uC5D0 \uBC18\uB4DC\uC2DC \uC5D4\uD130"},{"id":"/2026/02/27/java-final-inheritance","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/27/java-final-inheritance","source":"@site/blog/2026-02-27-java-final-inheritance.md","title":"[TIL] Java final\uACFC \uC0C1\uC18D, \uC7AC\uC815\uC758","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.27","date":"2026-02-27T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"final","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/final"},{"inline":true,"label":"\uC0C1\uC18D","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uC0C1\uC18D"},{"inline":true,"label":"override","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/override"},{"inline":true,"label":"Eclipse","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/eclipse"}],"readingTime":2.6,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java final\uACFC \uC0C1\uC18D, \uC7AC\uC815\uC758","date":"2026-02-27T00:00:00.000Z","tags":["Java","final","\uC0C1\uC18D","override","Eclipse"]},"unlisted":false,"prevItem":{"title":"[TIL] Java \uC57D\uC218/\uC644\uC804\uC218/\uCE5C\uD654\uC218\uC640 \uBB38\uC790\uC5F4 \uC2EC\uD654","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/03/03/java-divisor-string"},"nextItem":{"title":"[TIL] Java \uAE30\uCD08 \uBB38\uBC95\uACFC \uC81C\uC5B4\uBB38 \u2014 if, switch, for","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/26/java-control-flow"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.27\\n\\n## \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\nEclipse \uD504\uB85C\uC81D\uD2B8 \uAD00\uB9AC \u2192 final \uBCC0\uC218 \u2192 final \uBA54\uC18C\uB4DC \u2192 final \uD074\uB798\uC2A4\\n```\\n\\n---\\n\\n## 1. Eclipse \uD504\uB85C\uC81D\uD2B8 & \uCF54\uB4DC \uAD00\uB9AC\\n\\n\uD504\uB85C\uC81D\uD2B8\uAC00 \uB9CE\uC544\uC9C0\uBA74 \uD0D0\uC0C9\uAE30\uAC00 \uBCF5\uC7A1\uD574\uC9C0\uACE0 \uBA54\uBAA8\uB9AC\uB3C4 \uC810\uC720\uB418\uBBC0\uB85C, \uC0AC\uC6A9\uD558\uC9C0 \uC54A\uB294 \uD504\uB85C\uC81D\uD2B8\uB294 \uB2EB\uC544\uB450\uB294 \uAC83\uC774 \uC88B\uB2E4.\\n\\n| \uC791\uC5C5 | \uACBD\uB85C | \uD6A8\uACFC |\\n|------|------|------|\\n| \uD504\uB85C\uC81D\uD2B8 \uB2EB\uAE30 | \uC6B0\uD074\uB9AD \u2192 Close Project | \uBE44\uD65C\uC131\uD654, \uBA54\uBAA8\uB9AC \uC808\uC57D |\\n| \uB2EB\uD78C \uD504\uB85C\uC81D\uD2B8 \uC228\uAE30\uAE30 | \uD0D0\uC0C9\uAE30(\uC810 3\uAC1C) \u2192 Filters \u2192 Closed Projects \uCCB4\uD06C | \uBAA9\uB85D\uC5D0\uC11C \uC548 \uBCF4\uC784 |\\n| \uB2E4\uC2DC \uC5F4\uAE30 | \uD0D0\uC0C9\uAE30\uC5D0\uC11C \uB354\uBE14\uD074\uB9AD | \uC7AC\uD65C\uC131\uD654 |\\n\\n### \uCF54\uB4DC \uD3EC\uB9F7\uD305\\n\\n```\\n\uC6B0\uD074\uB9AD \u2192 Source \u2192 Format\\n\uB2E8\uCD95\uD0A4: Ctrl + Shift + F\\n```\\n\\n\uD300 \uB2E8\uC704 \uAC1C\uBC1C\uC5D0\uC11C \uD3EC\uB9F7 \uBBF8\uC801\uC6A9 \uCF54\uB4DC\uB294 \uB9AC\uBDF0 \uD488\uC9C8\uC744 \uC800\uD558\uC2DC\uD0A4\uBBC0\uB85C \uC2B5\uAD00\uD654\uAC00 \uD544\uC694\uD558\uB2E4.\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Eclipse` `Close Project` `Filters` `Format` `\uBA54\uBAA8\uB9AC \uAD00\uB9AC`\\n\\n---\\n\\n## 2. final\uC758 3\uAC00\uC9C0 \uC801\uC6A9 \uC9C0\uC810\\n\\nfinal\uC740 \\"\uC5B4\uB514\uC5D0 \uBD99\uC774\uB290\uB0D0\\"\uC5D0 \uB530\uB77C \uC81C\uC57D \uB300\uC0C1\uC774 \uB2EC\uB77C\uC9C4\uB2E4.\\n\\n| \uC801\uC6A9 \uB300\uC0C1 | final \uC758\uBBF8 | \uD575\uC2EC \uD6A8\uACFC |\\n|----------|-----------|----------|\\n| \uBCC0\uC218 | \uC0C1\uC218\uD654 | \uCD5C\uCD08 1\uD68C\uB9CC \uAC12 \uACB0\uC815, \uC7AC\uB300\uC785 \uBD88\uAC00 |\\n| \uBA54\uC18C\uB4DC | \uC7AC\uC815\uC758(override) \uBD88\uAC00 | \uC790\uC2DD \uD074\uB798\uC2A4\uAC00 \uAD6C\uD604\uC744 \uBC14\uAFC0 \uC218 \uC5C6\uC74C |\\n| \uD074\uB798\uC2A4 | \uC0C1\uC18D \uBD88\uAC00 | extends\uB85C \uD655\uC7A5 \uBD88\uAC00 |\\n\\n:::info\\n- **\uD655\uC7A5(extends)**: \uBD80\uBAA8 \uAE30\uB2A5\uC744 \uBB3C\uB824\uBC1B\uC544 \uBC94\uC704\uB97C \uB113\uD788\uB294 \uAC83\\n- **\uC7AC\uC815\uC758(override)**: \uBD80\uBAA8\uC758 \uB3D9\uC791\uC744 \uC790\uC2DD\uC774 \uB3D9\uC77C\uD55C \uC2DC\uADF8\uB2C8\uCC98\uB85C \uBC14\uAFD4 \uB07C\uC6B0\uB294 \uAC83\\n\\nfinal\uC740 \uC774 \uB450 \uAC00\uB2A5\uC131\uC744 \uBA85\uC2DC\uC801\uC73C\uB85C \uCC28\uB2E8\uD55C\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `final` `\uBCC0\uC218` `\uBA54\uC18C\uB4DC` `\uD074\uB798\uC2A4` `\uC0C1\uC18D`\\n\\n---\\n\\n## 3. final \uBCC0\uC218 \u2014 \uCD08\uAE30\uD654\uC640 \uC7AC\uB300\uC785 \uAE08\uC9C0\\n\\nfinal \uBCC0\uC218\uB294 **\uB2E8 \uD55C \uBC88\uB9CC \uAC12\uC744 \uACB0\uC815**\uD560 \uC218 \uC788\uB2E4. \uC774\uD6C4 \uC7AC\uB300\uC785 \uC2DC \uCEF4\uD30C\uC77C \uC624\uB958 \uBC1C\uC0DD.\\n\\n### \uBCC0\uC218 \uC885\uB958\uBCC4 \uC815\uB9AC\\n\\n| \uBCC0\uC218 \uC885\uB958 | \uC120\uC5B8 \uC704\uCE58 | \uC811\uADFC/\uD2B9\uC9D5 |\\n|----------|----------|----------|\\n| \uC778\uC2A4\uD134\uC2A4 \uBCC0\uC218 | \uD074\uB798\uC2A4 \uB0B4\uBD80(\uD544\uB4DC) | \uAC1D\uCCB4\uB97C \uD1B5\uD574 \uC811\uADFC, \uC0DD\uC131 \uC2DC \uCD08\uAE30\uD654 |\\n| \uC9C0\uC5ED \uBCC0\uC218(\uB85C\uCEEC) | \uBA54\uC18C\uB4DC \uB0B4\uBD80 | \uBA54\uC18C\uB4DC \uBC16\uC5D0\uC11C \uC9C1\uC811 \uC811\uADFC \uBD88\uAC00, return\uC73C\uB85C \uC804\uB2EC |\\n| \uC815\uC801 \uBCC0\uC218(static) | \uD074\uB798\uC2A4 \uB0B4\uBD80(\uD544\uB4DC) | \uD074\uB798\uC2A4\uBA85\uC73C\uB85C \uC811\uADFC, \uBA54\uBAA8\uB9AC\uC5D0 1\uD68C \uB85C\uB529 \uD6C4 \uACF5\uC720 |\\n\\n### \uCF54\uB4DC \uC608\uC2DC\\n\\n```java\\npublic class FinalClass {\\n    public static final int AGE = 10;  // \uC120\uC5B8\uACFC \uB3D9\uC2DC\uC5D0 \uCD08\uAE30\uD654\\n\\n    public static final int[] ARR;\\n    static {\\n        ARR = new int[3];  // \uC815\uC801 \uCD08\uAE30\uD654 \uBE14\uB85D\uC5D0\uC11C \uCD08\uAE30\uD654\\n    }\\n}\\n```\\n\\n```java\\nfinal int a = 10;\\na = 20;  // \uCEF4\uD30C\uC77C \uC624\uB958 \u2014 \uC774\uBBF8 \uAC12\uC774 \uC9C0\uC815\uB428\\n```\\n\\n:::warning\\n\uBA64\uBC84\uD544\uB4DC\uC5D0 final\uC744 \uC120\uC5B8\uD558\uBA74 \uBC18\uB4DC\uC2DC \uC120\uC5B8 \uC2DC\uC810 \uB610\uB294 \uC815\uC801 \uCD08\uAE30\uD654 \uBE14\uB85D(`static {}`)\uC5D0\uC11C \uAC12\uC744 \uCC44\uC6CC\uC57C \uD55C\uB2E4. \uBE44\uC5B4\uC788\uC73C\uBA74 \uCEF4\uD30C\uC77C \uC624\uB958.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC0C1\uC218` `\uCD08\uAE30\uD654` `static \uBE14\uB85D` `\uB85C\uCEEC \uBCC0\uC218` `\uC7AC\uB300\uC785`\\n\\n---\\n\\n## 4. final \uBA54\uC18C\uB4DC \u2014 \uC624\uBC84\uB77C\uC774\uB4DC \uCC28\uB2E8\\n\\n\uBD80\uBAA8 \uBA54\uC18C\uB4DC\uAC00 final\uC774\uBA74 \uC790\uC2DD \uD074\uB798\uC2A4\uC5D0\uC11C \uC7AC\uC815\uC758\uD560 \uC218 \uC5C6\uB2E4. \uD638\uCD9C\uC744 \uD1B5\uD55C \uC0AC\uC6A9\uB9CC \uD5C8\uC6A9\uB41C\uB2E4.\\n\\n| \uBD80\uBAA8 \uBA54\uC18C\uB4DC \uC0C1\uD0DC | Override \uBAA9\uB85D \uB178\uCD9C | \uC790\uC2DD \uC7AC\uC815\uC758 \uAC00\uB2A5 \uC5EC\uBD80 |\\n|----------------|-------------------|-------------------|\\n| \uC77C\uBC18 \uBA54\uC18C\uB4DC | \uB178\uCD9C\uB428 | \uAC00\uB2A5 |\\n| final \uBA54\uC18C\uB4DC | \uB178\uCD9C \uC548 \uB428 | \uBD88\uAC00 |\\n\\n```java\\nString msg = child.callMessage();  // \uBC18\uD658\uAC12\uC740 \uBCC0\uC218\uC5D0 \uBC1B\uAC70\uB098 \uCD9C\uB825 \uD568\uC218\uB85C \uC804\uB2EC\uD574\uC57C \uD568\\nSystem.out.println(msg);\\n```\\n\\n:::info\\n\uBC18\uD658 \uD0C0\uC785\uC774 \uC788\uB294 \uBA54\uC18C\uB4DC\uB294 \uD638\uCD9C\uB9CC \uD55C\uB2E4\uACE0 \uCD9C\uB825\uC774 \uC790\uB3D9\uC73C\uB85C \uBC1C\uC0DD\uD558\uC9C0 \uC54A\uB294\uB2E4.\\n\uBC18\uD658\uAC12\uC744 \uC0AC\uC6A9\uD558\uB824\uBA74 \uBC18\uB4DC\uC2DC \uBCC0\uC218\uC5D0 \uBC1B\uAC70\uB098 \uCD9C\uB825 \uD568\uC218\uB85C \uC804\uB2EC\uD574\uC57C \uD55C\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `override` `final \uBA54\uC18C\uB4DC` `\uC0C1\uC18D` `\uBC18\uD658 \uD0C0\uC785` `Source \uBA54\uB274`\\n\\n---\\n\\n## 5. final \uD074\uB798\uC2A4 \u2014 \uC0C1\uC18D \uAE08\uC9C0\\n\\nfinal \uD074\uB798\uC2A4\uB294 \uB2E4\uB978 \uD074\uB798\uC2A4\uC758 \uBD80\uBAA8\uAC00 \uB420 \uC218 \uC5C6\uB2E4.\\n\\n```java\\nfinal class X {}\\nclass Y extends X {}  // \uCEF4\uD30C\uC77C \uC624\uB958\\n```\\n\\n\uB300\uD45C \uC0AC\uB840: `String` \uD074\uB798\uC2A4\uB294 final\uB85C \uC120\uC5B8\uB418\uC5B4 \uC788\uC5B4 \uC0C1\uC18D\uC774 \uBD88\uAC00\uD558\uB2E4. \uBB38\uC790\uC5F4 \uB3D9\uC791\uC744 \uC784\uC758\uB85C \uBCC0\uD615\uD558\uB294 \uC0C1\uD669\uC744 \uBC29\uC9C0\uD558\uAE30 \uC704\uD55C \uC124\uACC4\uB2E4.\\n\\n| \uAD6C\uBD84 | \uC758\uBBF8 |\\n|------|------|\\n| final \uD074\uB798\uC2A4 | \uD655\uC7A5 \uAD6C\uC870 \uACE0\uC815 \u2014 \uC0C1\uC18D \uBD88\uAC00 |\\n| final \uBA54\uC18C\uB4DC | \uB3D9\uC791 \uACE0\uC815 \u2014 \uC7AC\uC815\uC758 \uBD88\uAC00 |\\n| final \uBCC0\uC218 | \uAC12 \uACE0\uC815 \u2014 \uC7AC\uB300\uC785 \uBD88\uAC00 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `final \uD074\uB798\uC2A4` `String` `\uD0C0\uC785 \uC548\uC815\uC131` `\uC0C1\uC18D \uAE08\uC9C0` `\uBD88\uBCC0\uC131`\\n\\n---\\n\\n## \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. Eclipse \uD504\uB85C\uC81D\uD2B8 \uB9CE\uC544\uC9C0\uBA74 Close Project + Filters\uB85C \uAD00\uB9AC\\n2. \uCF54\uB4DC \uD3EC\uB9F7\uD305 \uB2E8\uCD95\uD0A4: `Ctrl + Shift + F`\\n3. final \uBCC0\uC218 = \uC7AC\uB300\uC785 \uBD88\uAC00, \uBC18\uB4DC\uC2DC \uCD08\uAE30\uD654 \uD544\uC694\\n4. final \uBA54\uC18C\uB4DC = \uC790\uC2DD\uC774 override \uBD88\uAC00, \uC0AC\uC6A9\uB9CC \uAC00\uB2A5\\n5. final \uD074\uB798\uC2A4 = extends \uBD88\uAC00 (\uB300\uD45C \uC0AC\uB840: String)\\n6. \uBC18\uD658\uAC12 \uC788\uB294 \uBA54\uC18C\uB4DC\uB294 \uBCC0\uC218\uC5D0 \uBC1B\uAC70\uB098 \uCD9C\uB825 \uD568\uC218\uB85C \uC804\uB2EC\uD574\uC57C \uD568"},{"id":"/2026/02/26/java-control-flow","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/26/java-control-flow","source":"@site/blog/2026-02-26-java-control-flow.md","title":"[TIL] Java \uAE30\uCD08 \uBB38\uBC95\uACFC \uC81C\uC5B4\uBB38 \u2014 if, switch, for","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.26","date":"2026-02-26T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"\uC81C\uC5B4\uBB38","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uC81C\uC5B4\uBB38"},{"inline":true,"label":"if","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/if"},{"inline":true,"label":"switch","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/switch"},{"inline":true,"label":"for","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/for"},{"inline":true,"label":"Scanner","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/scanner"}],"readingTime":3.38,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java \uAE30\uCD08 \uBB38\uBC95\uACFC \uC81C\uC5B4\uBB38 \u2014 if, switch, for","date":"2026-02-26T00:00:00.000Z","tags":["Java","\uC81C\uC5B4\uBB38","if","switch","for","Scanner"]},"unlisted":false,"prevItem":{"title":"[TIL] Java final\uACFC \uC0C1\uC18D, \uC7AC\uC815\uC758","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/27/java-final-inheritance"},"nextItem":{"title":"[TIL] Java \uAE30\uCD08 \u2014 JAR, \uD0C0\uC785, \uC5F0\uC0B0, \uBCC0\uC218","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/25/java-jar-type-operator"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.26\\n\\n## \u{1F5FA} \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uC720\uB2C8\uCF54\uB4DC/\uD615\uBCC0\uD658 \uBCF5\uC2B5 \u2192 if/else if/else \u2192 Scanner \uC785\uB825 \uCC98\uB9AC\\n\u2192 switch (\uC804\uD1B5 ~ Java 14+) \u2192 for \uBC18\uBCF5\uBB38 \u2192 \uB204\uC801 \uD569 \u2192 \uC9C4\uC57D\uC218 \uD569\\n```\\n\\n---\\n\\n## 1\uFE0F\u20E3 \uBB38\uC790, \uC720\uB2C8\uCF54\uB4DC\uC640 \uD615\uBCC0\uD658, \uBB38\uC790\uC5F4 \uACB0\uD569\\n\\n`char`\uB294 \uB0B4\uBD80\uC801\uC73C\uB85C **\uC720\uB2C8\uCF54\uB4DC \uCF54\uB4DC\uAC12(\uC815\uC218)** \uC73C\uB85C \uC800\uC7A5\uB41C\uB2E4.\\n\\n```java\\nchar n = \'9\';\\nchar m = \'0\';\\nint result = n - m;                // 57 - 48 = 9 (\uCF54\uB4DC\uAC12\uB07C\uB9AC \uC5F0\uC0B0)\\nSystem.out.println(\\"\uACB0\uACFC: \\" + result);\\n\\nSystem.out.println((char)result);  // \uCF54\uB4DC\uAC12 9 \u2192 \uD0ED/\uC81C\uC5B4\uBB38\uC790\uCC98\uB7FC \uBCF4\uC77C \uC218 \uC788\uC74C\\n```\\n\\n:::info\\n`\'9\'` - `\'0\'` = **9** (\uBB38\uC790\uB07C\uB9AC \uBE84\uC148\uCC98\uB7FC \uBCF4\uC774\uC9C0\uB9CC \uC2E4\uC81C\uB85C\uB294 \uC815\uC218 \uCF54\uB4DC\uAC12 \uC5F0\uC0B0)\\n\\n`+` \uC5F0\uC0B0\uC790\uAC00 **\uBB38\uC790\uC5F4\uACFC \uB9CC\uB098\uBA74** \uB2E4\uB978 \uD53C\uC5F0\uC0B0\uC790\uB3C4 \uBB38\uC790\uC5F4\uB85C \uBCC0\uD658\uD574\uC11C \uC774\uC5B4 \uBD99\uC778\uB2E4 \u2192 \uCEE8\uCE90\uD2B8\uB124\uC774\uC158(concatenation)\\n:::\\n\\n:::warning\\n\uC720\uB2C8\uCF54\uB4DC \uD45C\uC758 \uBAA8\uB4E0 \uAC12\uC774 \uB208\uC5D0 \uBCF4\uC774\uB294 \uBB38\uC790\uB294 \uC544\uB2C8\uB2E4.\\n\uCF54\uB4DC\uAC12 13 = \uC5D4\uD130(\uC81C\uC5B4\uBB38\uC790) \u2192 \uCD9C\uB825 \uC2DC \uACF5\uBC31\uCC98\uB7FC \uBCF4\uC77C \uC218 \uC788\uC74C\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC720\uB2C8\uCF54\uB4DC` `char` `\uBA85\uC2DC\uC801\uD615\uBCC0\uD658` `\uCEE8\uCE90\uD2B8\uB124\uC774\uC158` `\uC815\uC218\uC5F0\uC0B0`\\n\\n---\\n\\n## 2\uFE0F\u20E3 if \uC870\uAC74\uBB38\uACFC Scanner \uC785\uB825 \uCC98\uB9AC\\n\\n### if / else if / else\\n\\n| \uD615\uD0DC | \uBAA9\uC801 | \uD2B9\uC9D5 |\\n|------|------|------|\\n| `if` | \uB2E8\uC77C \uC870\uAC74\uC774 \uCC38\uC77C \uB54C\uB9CC \uC2E4\uD589 | \uAC70\uC9D3\uC774\uBA74 \uC544\uBB34\uAC83\uB3C4 \uC548 \uD568 |\\n| `if-else` | \uCC38/\uAC70\uC9D3 \uC591\uBD84 | \uBC18\uB4DC\uC2DC \uD558\uB098\uB294 \uC2E4\uD589 |\\n| `if-else if-else` | \uB2E4\uC911 \uC870\uAC74 \uC21C\uCC28 \uC120\uD0DD | \uC704 \uC870\uAC74 \uB9E4\uCE6D\uB418\uBA74 \uC544\uB798\uB294 \uD3C9\uAC00 \uC548 \uD568 |\\n\\n### Scanner \u2014 \uCF58\uC194 \uC785\uB825 \uCC98\uB9AC\\n\\n```java\\nimport java.util.Scanner;\\n\\nScanner scan = new Scanner(System.in);\\nSystem.out.print(\\"\uC815\uC218 \uAC12\uC744 \uC785\uB825\uD574 \uC8FC\uC138\uC694: \\");\\nint input = scan.nextInt();\\nSystem.out.println(\\"\uC785\uB825\uBC1B\uC740 \uC815\uC218\uAC12: \\" + input);\\n```\\n\\n:::info\\n`import`\uB294 \uB2E4\uB978 \uD328\uD0A4\uC9C0\uC5D0 \uC788\uB294 \uD074\uB798\uC2A4\uB97C \uD604\uC7AC \uD30C\uC77C\uC5D0\uC11C \uC0AC\uC6A9\uD558\uACA0\uB2E4\uB294 \uBA85\uC2DC\uB2E4.\\n\uAC19\uC740 \uC774\uB984\uC758 \uD074\uB798\uC2A4\uAC00 \uB2E4\uB978 \uD328\uD0A4\uC9C0\uC5D0 \uC874\uC7AC\uD560 \uC218 \uC788\uC5B4\uC11C \uD328\uD0A4\uC9C0 \uACBD\uB85C\uB85C \uAD6C\uBD84\uD55C\uB2E4.\\n:::\\n\\n:::warning\\n\uCF58\uC194\uC774 \uBE68\uAC04\uC0C9\uC73C\uB85C \uC2E4\uD589 \uC911 \u2192 **\uC785\uB825 \uB300\uAE30 \uC0C1\uD0DC**\uC77C \uC218 \uC788\uC74C\\n\\n`nextInt()`\uC5D0 \uBB38\uC790(\uD55C\uAE00 \uB4F1)\uB97C \uC785\uB825\uD558\uBA74 \u2192 `InputMismatchException` \uBC1C\uC0DD\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `if\uBB38` `else if` `Scanner` `import` `InputMismatchException`\\n\\n---\\n\\n## 3\uFE0F\u20E3 switch \uBB38 \u2014 \uC804\uD1B5 ~ Java 14+\\n\\nswitch\uB294 \uBC94\uC704 \uBE44\uAD50(`<`, `>`)\uAC00 \uC544\uB2CC **\uAC12\uC758 \uB3D9\uC77C\uC131** \uAE30\uBC18 \uC120\uD0DD\uBB38\uC774\uB2E4.\\n\\n> \uBC94\uC704 \uC870\uAC74 \u2192 `if` / \uAC1C\uBCC4 \uAC12 \uB9E4\uD551 \u2192 `switch`\\n\\n### \uC804\uD1B5 switch (~ Java 13)\\n\\n```java\\nswitch (n) {\\n    case 0:\\n        System.out.println(\\"0\uC774\uB2E4.\\");\\n        break;\\n    case 1:\\n        System.out.println(\\"1\uC774\uB2E4.\\");\\n        break;\\n    default:\\n        System.out.println(\\"\uB2E4\uB978 \uAC12\uC774\uB2E4.\\");\\n}\\n```\\n\\n:::danger\\n`break` \uBE60\uB728\uB9AC\uBA74 **fall-through** \uBC1C\uC0DD \u2192 \uC544\uB798 case\uAE4C\uC9C0 \uC5F0\uC1C4 \uC2E4\uD589\uB428\\n:::\\n\\n### Java 14+ switch expression\\n\\n```java\\n// arrow label (break \uBD88\uD544\uC694, \uC5EC\uB7EC case \uCF64\uB9C8\uB85C \uBB36\uAE30 \uAC00\uB2A5)\\nString result = switch (key) {\\n    case 1 -> \\"\uD558\uB098\\";\\n    case 2, 3 -> \\"\uB458 \uB610\uB294 \uC14B\\";\\n    default -> \\"\uB2E4\uB978 \uC22B\uC790\\";\\n};\\n\\n// yield \u2014 \uBE14\uB85D \uB0B4 \uCD94\uAC00 \uB85C\uC9C1 \uD6C4 \uAC12 \uBC18\uD658\\nString result2 = switch (key) {\\n    case 1 -> \\"\uD558\uB098\\";\\n    default -> {\\n        String msg = \\"\uC54C \uC218 \uC5C6\uC74C: \\" + key;\\n        yield msg;  // \uBE14\uB85D\uC758 \uCD5C\uC885 \uBC18\uD658\uAC12\\n    }\\n};\\n```\\n\\n| \uBC84\uC804/\uBB38\uBC95 | \uD575\uC2EC \uBCC0\uD654 | \uC8FC\uC758\uC810 |\\n|----------|----------|--------|\\n| \uC804\uD1B5 switch | `break`\uB85C \uC885\uB8CC | \uB204\uB77D \uC2DC fall-through |\\n| Java 7+ | `String` \uBE44\uAD50 \uAC00\uB2A5 | \uBE44\uAD50\uAC12\uC740 \uC785\uB825 \uD0C0\uC785\uACFC \uAC19\uC544\uC57C \uD568 |\\n| Java 14+ expression | \uACB0\uACFC\uB97C \uBCC0\uC218\uC5D0 \uB300\uC785 \uAC00\uB2A5 | \uAD6C\uC870 \uADDC\uCE59 \uC900\uC218 \uD544\uC694 |\\n| arrow label | `break` \uC5C6\uC774 \uB2E8\uC77C \uB3D9\uC791 | \uC5EC\uB7EC case \uCF64\uB9C8\uB85C \uBB36\uAE30 \uAC00\uB2A5 |\\n| `yield` | \uBE14\uB85D \uB0B4 \uB85C\uC9C1 \uD6C4 \uAC12 \uBC18\uD658 | \uC911\uAD04\uD638\uB85C \uAC10\uC2F8\uC57C \uD568 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `switch` `fall-through` `switch expression` `arrow label` `yield`\\n\\n---\\n\\n## 4\uFE0F\u20E3 for \uBC18\uBCF5\uBB38\uACFC \uC2A4\uCF54\uD504\\n\\n### \uC2E4\uD589 \uC21C\uC11C\\n\\n```\\n\uCD08\uAE30\uD654 \u2192 \uC870\uAC74\uAC80\uC0AC \u2192 \uBCF8\uBB38 \u2192 \uC99D\uAC10 \u2192 \uC870\uAC74\uAC80\uC0AC \u2192 \uBCF8\uBB38 \u2192 ...\\n```\\n\\n:::info\\n`i < 5` \uCC98\uB7FC **\uBBF8\uB9CC** \uC870\uAC74\uC774\uBA74 \uB9C8\uC9C0\uB9C9 \uAC12(5)\uC740 \uBCF8\uBB38\uC774 \uC2E4\uD589\uB418\uC9C0 \uC54A\uB294\uB2E4.\\n\\n\uCC98\uC74C \uC811\uD560 \uB54C\uB294 **\uB514\uBC84\uADF8 \uD45C**\uB85C \uBCC0\uC218\uAC12 / \uC870\uAC74 \uACB0\uACFC / \uCD9C\uB825 / \uC99D\uAC10\uC744 \uB2E8\uACC4\uBCC4\uB85C \uC801\uC5B4\uBCF4\uBA74 \uC774\uD574\uAC00 \uBE68\uB77C\uC9C4\uB2E4.\\n:::\\n\\n### \uC2A4\uCF54\uD504 \uC8FC\uC758\\n\\n```java\\n// i\uB97C \uBC18\uBCF5\uBB38 \uBC16\uC5D0\uC11C \uC4F0\uACE0 \uC2F6\uB2E4\uBA74 \uBC16\uC5D0 \uC120\uC5B8\uD574\uC57C \uD568\\nint i = 0;\\nfor (; i < 5; i++) {\\n    System.out.println(i);\\n}\\nSystem.out.println(\\"\uB9C8\uC9C0\uB9C9 i: \\" + i);  // 5\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `for\uBB38` `\uC2A4\uCF54\uD504` `\uB204\uC801\uBCC0\uC218` `\uBAA8\uB4C8\uB7EC\uC2A4` `\uC9C4\uC57D\uC218`\\n\\n---\\n\\n## 5\uFE0F\u20E3 \uB204\uC801 \uD569\uACFC \uC9C4\uC57D\uC218 \uD569\\n\\n### \uB204\uC801 \uD569 \uD328\uD134\\n\\n```java\\nint sum = 0;\\nfor (int i = 0; i < 5; i++) {\\n    sum += i;  // 0+1+2+3+4\\n}\\nSystem.out.println(\\"\uD569: \\" + sum);  // 10\\n```\\n\\n### \uC9C4\uC57D\uC218 \uD569 (\uC790\uAE30 \uC790\uC2E0 \uC81C\uC678\uD55C \uC57D\uC218\uC758 \uD569)\\n\\n```java\\nint n = 10;\\nint sumResult = 0;\\n\\nfor (int i = 1; i < n; i++) {   // \uC790\uAE30 \uC790\uC2E0 \uC81C\uC678\\n    if (n % i == 0) {           // \uB098\uB204\uC5B4 \uB5A8\uC5B4\uC9C0\uBA74 \uC57D\uC218\\n        sumResult += i;         // \uB204\uC801\\n    }\\n}\\nSystem.out.println(n + \\"\uC758 \uC9C4\uC57D\uC218\uC758 \uD569: \\" + sumResult);  // 8 (1+2+5)\\n```\\n\\n:::info\\n**\uC57D\uC218 \uD310\uBCC4** = \uBAA8\uB4C8\uB7EC\uC2A4(`%`)\uB85C \uB098\uBA38\uC9C0\uAC00 0\uC778\uC9C0 \uD655\uC778\\n\\n\uC774 \uD328\uD134\uC740 \uC644\uC804\uC218, \uCE5C\uD654\uC218 \uAC19\uC740 \uBB38\uC81C\uB85C \uD655\uC7A5\uB418\uB294 \uC804\uD615\uC801\uC778 \uB204\uC801 \uBCC0\uC218 \uD328\uD134\uC774\uB2E4.\\n:::\\n\\n---\\n\\n## \u{1F51C} \uB2E4\uC74C\uC5D0 \uC774\uC5B4\uC9C8 \uB0B4\uC6A9\\n\\n- \uBC30\uC5F4 (\uBCC0\uC218 \uC5EC\uB7EC \uAC1C \u2192 \uD55C \uD1B5\uC5D0 \uB2F4\uAE30)\\n- \uD5A5\uC0C1\uB41C for\uBB38 (`for-each`)\\n- \uC778\uB371\uC2A4\uB294 0\uBD80\uD130 \uC2DC\uC791, `length`\uB85C \uD06C\uAE30 \uD655\uC778\\n\\n---\\n\\n## \u2705 \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. `char` \uC5F0\uC0B0 = \uB0B4\uBD80\uC801\uC73C\uB85C **\uC815\uC218 \uCF54\uB4DC\uAC12** \uC5F0\uC0B0\\n2. `+`\uAC00 \uBB38\uC790\uC5F4\uACFC \uB9CC\uB098\uBA74 \u2192 \uB098\uBA38\uC9C0\uB3C4 \uBB38\uC790\uC5F4\uB85C **\uCEE8\uCE90\uD2B8\uB124\uC774\uC158**\\n3. `if` = \uBC94\uC704/\uBCF5\uC7A1\uD55C \uC870\uAC74, `switch` = \uAC12\uC758 \uB3D9\uC77C\uC131 \uBE44\uAD50\\n4. `break` \uBE60\uB728\uB9AC\uBA74 **fall-through** \u2192 Java 14+ arrow label\uB85C \uBC29\uC9C0 \uAC00\uB2A5\\n5. `for` \uC2E4\uD589 \uC21C\uC11C: \uCD08\uAE30\uD654 \u2192 \uC870\uAC74 \u2192 \uBCF8\uBB38 \u2192 \uC99D\uAC10 \uBC18\uBCF5\\n6. \uB204\uC801 \uD569 \uD328\uD134: \uC678\uBD80 \uBCC0\uC218 `sum = 0` \u2192 `sum += i`\\n7. \uC57D\uC218 \uD310\uBCC4: `n % i == 0`"},{"id":"/2026/02/25/java-jar-type-operator","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/25/java-jar-type-operator","source":"@site/blog/2026-02-25-java-jar-type-operator.md","title":"[TIL] Java \uAE30\uCD08 \u2014 JAR, \uD0C0\uC785, \uC5F0\uC0B0, \uBCC0\uC218","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.25","date":"2026-02-25T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"JAR","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/jar"},{"inline":true,"label":"\uD0C0\uC785","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uD0C0\uC785"},{"inline":true,"label":"\uC5F0\uC0B0","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uC5F0\uC0B0"},{"inline":true,"label":"\uBCC0\uC218","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uBCC0\uC218"}],"readingTime":4.6,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java \uAE30\uCD08 \u2014 JAR, \uD0C0\uC785, \uC5F0\uC0B0, \uBCC0\uC218","date":"2026-02-25T00:00:00.000Z","tags":["Java","JAR","\uD0C0\uC785","\uC5F0\uC0B0","\uBCC0\uC218"]},"unlisted":false,"prevItem":{"title":"[TIL] Java \uAE30\uCD08 \uBB38\uBC95\uACFC \uC81C\uC5B4\uBB38 \u2014 if, switch, for","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/26/java-control-flow"},"nextItem":{"title":"[TIL] Java OT \u2014 \uAC1C\uBC1C\uD658\uACBD \uAD6C\uCD95\uBD80\uD130 \uAE30\uBCF8 \uBB38\uBC95\uAE4C\uC9C0","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/24/java-ot-setup"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.25\\n\\n## \u{1F5FA} \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uC804\uC77C \uBCF5\uC2B5 \u2192 JAR \uD328\uD0A4\uC9D5 \u2192 \uAE30\uBCF8 \uD0C0\uC785/\uB9AC\uD130\uB7F4 \u2192 \uC2E4\uC218/\uCE90\uC2A4\uD305\\n\u2192 char/boolean \u2192 var \u2192 \uBCC0\uC218 \uC885\uB958/\uC2A4\uCF54\uD504 \u2192 DTO \u2192 \uC5F0\uC0B0\uC790 \u2192 char \uBCC0\uD658\\n```\\n\\n---\\n\\n## 1\uFE0F\u20E3 \uC804\uC77C \uBCF5\uC2B5 \u2014 \uD074\uB798\uC2A4\uC640 \uAC1D\uCCB4\\n\\n- \uC124\uACC4\uB3C4 = \uD074\uB798\uC2A4, \uC0AC\uC6A9 = \uAC1D\uCCB4(\uC778\uC2A4\uD134\uC2A4)\\n- `main()`\uC774 \uC788\uB294 \uD074\uB798\uC2A4\uC5D0\uC11C\uB9CC \uC2E4\uD589 \uAC00\uB2A5\\n- \uC694\uAD6C\uC0AC\uD56D\uC5D0 \uB9DE\uCDB0 **\uCD5C\uC18C \uB2E8\uC704**\uB85C \uAD6C\uD604\uD558\uB294 \uC2B5\uAD00\uC774 \uC911\uC694\\n\\n```java\\nStudent s = new Student();\\nSystem.out.println(s.name);\\nSystem.out.println(s.age);\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD074\uB798\uC2A4` `\uC778\uC2A4\uD134\uC2A4\uD654` `\uD544\uB4DC` `main` `System.out.println`\\n\\n---\\n\\n## 2\uFE0F\u20E3 JAR \uD328\uD0A4\uC9D5\uACFC Runnable JAR \uC2E4\uD589\\n\\nJAR(Java Archive)\uB294 \uC18C\uC2A4\uAC00 \uC544\uB2CC **\uC2E4\uD589/\uBC30\uD3EC\uB97C \uC704\uD574 \uACB0\uACFC\uBB3C\uC744 \uBB36\uB294 \uD328\uD0A4\uC9D5 \uC0B0\uCD9C\uBB3C**\uC774\uB2E4.\\n\\n| \uD615\uC2DD | \uC6A9\uB3C4 |\\n|------|------|\\n| JAR | \uC77C\uBC18 \uC790\uBC14 \uC571 \uBC30\uD3EC |\\n| WAR | \uC6F9 \uC571 \uBC30\uD3EC (\uC11C\uBE14\uB9BF \uCEE8\uD14C\uC774\uB108 \uD544\uC694) |\\n| Spring Boot JAR | \uB0B4\uC7A5 \uC11C\uBC84 \uD3EC\uD568, \uB2E8\uB3C5 \uC2E4\uD589 \uAC00\uB2A5 |\\n\\n### Runnable JAR \uC0DD\uC131 \uC21C\uC11C\\n\\n1. Java Project \uC0DD\uC131 \uD6C4 \uD328\uD0A4\uC9C0(3\uB2E8\uC704 \uC774\uC0C1) + \uBA54\uC778 \uD074\uB798\uC2A4 \uC0DD\uC131\\n2. `Run As > Java Application` \uC73C\uB85C \uD55C \uBC88 \uC2E4\uD589 (Launch configuration \uB4F1\uB85D)\\n3. \uD504\uB85C\uC81D\uD2B8 \uC6B0\uD074\uB9AD \u2192 `Export > Runnable JAR file` \uC120\uD0DD\\n4. Destination \uACBD\uB85C/\uD30C\uC77C\uBA85 \uC9C0\uC815 \uD6C4 Finish\\n5. \uD130\uBBF8\uB110\uC5D0\uC11C \uC2E4\uD589\\n\\n```bash\\njava -jar \uD30C\uC77C\uBA85.jar\\n```\\n\\n:::info\\n\uD130\uBBF8\uB110 \uBA85\uB839\uC5B4 \uCC28\uC774:\\n- Windows CMD: `DIR`\\n- Linux/Mac \uD130\uBBF8\uB110: `ls`\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `JAR` `Runnable JAR` `Manifest` `Export` `java -jar`\\n\\n---\\n\\n## 3\uFE0F\u20E3 \uAE30\uBCF8 \uD0C0\uC785(Primitive)\uACFC \uB9AC\uD130\uB7F4\\n\\n\uC790\uBC14 \uAE30\uBCF8 \uD0C0\uC785\uC740 **8\uAC00\uC9C0**\uB2E4.\\n\\n| \uBD84\uB958 | \uD0C0\uC785 | \uD575\uC2EC \uD3EC\uC778\uD2B8 |\\n|------|------|------------|\\n| \uC815\uC218\uD615 | `byte`, `short`, `int`, `long` | \uD06C\uAE30\uC5D0 \uB530\uB77C \uBC94\uC704 \uB2E4\uB984 |\\n| \uC2E4\uC218\uD615 | `float`, `double` | \uBD80\uB3D9\uC18C\uC218\uC810, \uAE30\uBCF8 \uB9AC\uD130\uB7F4\uC740 `double` |\\n| \uBB38\uC790\uD615 | `char` | \uC720\uB2C8\uCF54\uB4DC \uAE30\uBC18, \uC22B\uC790\uCC98\uB7FC \uC5F0\uC0B0 \uAC00\uB2A5 |\\n| \uB17C\uB9AC\uD615 | `boolean` | `true`/`false`, 0/1 \uCE58\uD658 \uBD88\uAC00 |\\n\\n### \uC815\uC218 \uB9AC\uD130\uB7F4 \uD45C\uAE30\uBC95\\n\\n| \uD45C\uAE30 | \uC608\uC2DC | \uC758\uBBF8 |\\n|------|------|------|\\n| 10\uC9C4\uC218 | `10` | \uC77C\uBC18 \uC22B\uC790 |\\n| 16\uC9C4\uC218 | `0xF` | HEX |\\n| 8\uC9C4\uC218 | `07` | OCT |\\n| 2\uC9C4\uC218 | `0b10` | Binary |\\n\\n:::warning\\n\uC815\uC218 \uB9AC\uD130\uB7F4 \uAE30\uBCF8 = `int`, \uC2E4\uC218 \uB9AC\uD130\uB7F4 \uAE30\uBCF8 = `double`\\n\\n\uC791\uC740 \uADF8\uB987(`float`)\uC5D0 \uD070 \uB9AC\uD130\uB7F4(`double`)\uC744 \uB2F4\uC73C\uBA74 **\uD0C0\uC785 \uBBF8\uC2A4\uB9E4\uCE58 \uC624\uB958** \uBC1C\uC0DD!\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Primitive` `\uB9AC\uD130\uB7F4` `int \uAE30\uBCF8` `double \uAE30\uBCF8` `\uC720\uB2C8\uCF54\uB4DC`\\n\\n---\\n\\n## 4\uFE0F\u20E3 \uC2E4\uC218(\uBD80\uB3D9\uC18C\uC218\uC810)\uC640 \uCE90\uC2A4\uD305\\n\\n`float`\uC5D0 \uC2E4\uC218 \uB9AC\uD130\uB7F4 \uB300\uC785 \uC2DC \uAE30\uBCF8\uC774 `double`\uC774\uB77C \uC624\uB958 \uBC1C\uC0DD \u2192 **F \uC811\uBBF8\uC0AC** \uB610\uB294 **\uBA85\uC2DC\uC801 \uCE90\uC2A4\uD305** \uD544\uC694\\n\\n```java\\nfloat f1 = 3.14F;          // F \uC811\uBBF8\uC0AC\\nfloat f2 = (float) 3.14;   // \uBA85\uC2DC\uC801 \uCE90\uC2A4\uD305\\ndouble d1 = 3.14;\\ndouble d2 = 3e2;           // \uC9C0\uC218 \uD45C\uAE30\uBC95: 3 \xd7 10\xb2 = 300.0\\n```\\n\\n:::info\\n\uC5F0\uC0B0 \uACB0\uACFC\uB294 **\uCC38\uC5EC\uD558\uB294 \uD0C0\uC785 \uC911 \uB354 \uD070 \uD0C0\uC785**\uC73C\uB85C \uC2B9\uACA9\uB41C\uB2E4.\\n\uAE08\uC735 \uB3C4\uBA54\uC778 \uB4F1 \uC815\uBC00\uB3C4\uAC00 \uC911\uC694\uD55C \uACF3\uC5D0\uC11C\uB294 \uD0C0\uC785 \uC120\uD0DD\uACFC \uC624\uCC28 \uAD00\uB9AC\uAC00 \uD575\uC2EC\uC774\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uBD80\uB3D9\uC18C\uC218\uC810` `float` `double` `\uCE90\uC2A4\uD305` `\uC9C0\uC218\uD45C\uAE30\uBC95`\\n\\n---\\n\\n## 5\uFE0F\u20E3 char, boolean\uC758 \uD2B9\uC9D5\\n\\n### char \u2014 \uC720\uB2C8\uCF54\uB4DC \uAE30\uBC18\\n\\n```java\\nchar c1 = \'A\';\\nchar c2 = \'\\\\u0041\';  // \'A\' \uC640 \uB3D9\uC77C\\n```\\n\\n- \uC5F0\uC0B0\uC5D0 \uCC38\uC5EC\uD558\uBA74 **\uC815\uC218\uB85C \uC2B9\uACA9** \u2192 \uB2E4\uC2DC \uBB38\uC790\uB85C \uBC14\uAFB8\uB824\uBA74 \uCE90\uC2A4\uD305 \uD544\uC694\\n\\n### boolean\\n\\n```java\\nboolean b = true;\\n// boolean b = 1;  \u2190 \uC790\uBC14\uC5D0\uC11C\uB294 \uBD88\uAC00! (\uB2E4\uB978 \uC5B8\uC5B4\uC640 \uB2E4\uB984)\\n```\\n\\n:::warning\\n\uC790\uBC14\uC758 `boolean`\uC740 `true`/`false` \uD0A4\uC6CC\uB4DC\uB9CC \uC0AC\uC6A9 \uAC00\uB2A5.\\n\uB2E4\uB978 \uC5B8\uC5B4\uCC98\uB7FC `0`/`1`\uB85C \uC790\uB3D9 \uBCC0\uD658\uB418\uC9C0 \uC54A\uB294\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `char` `\uC720\uB2C8\uCF54\uB4DC` `\\\\u` `boolean` `true/false`\\n\\n---\\n\\n## 6\uFE0F\u20E3 var (\uC790\uBC14 10+) \u2014 \uD0C0\uC785 \uCD94\uB860\\n\\n```java\\nvar n = 10;                              // int\uB85C \uCD94\uB860\\nvar list = new java.util.ArrayList<String>();  // \uD0C0\uC785 \uBC18\uBCF5 \uC0DD\uB7B5\\n```\\n\\n:::info\\n`var`\uB294 \uB3D9\uC801 \uD0C0\uC785\uC774 \uC544\uB2C8\uB2E4!\\n\uCD08\uAE30 \uD560\uB2F9\uC73C\uB85C \uD0C0\uC785\uC774 \uACB0\uC815\uB41C \uD6C4 **\uACE0\uC815** \u2192 \uC774\uD6C4 \uB2E4\uB978 \uD0C0\uC785 \uB300\uC785 \uBD88\uAC00\\n:::\\n\\n- \uB85C\uCEEC \uBCC0\uC218 \uC120\uC5B8\uC5D0\uC11C\uB9CC \uC0AC\uC6A9 \uAC00\uB2A5\\n- \uC81C\uB124\uB9AD \uCEEC\uB809\uC158 \uC0DD\uC131 \uC2DC \uBC18\uBCF5\uB418\uB294 \uD0C0\uC785 \uC120\uC5B8\uC744 \uC904\uC5EC **\uAC00\uB3C5\uC131 \uD5A5\uC0C1**\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `var` `\uD0C0\uC785\uCD94\uB860` `\uB85C\uCEEC\uBCC0\uC218` `\uC81C\uB124\uB9AD` `\uAC00\uB3C5\uC131`\\n\\n---\\n\\n## 7\uFE0F\u20E3 \uBCC0\uC218 \uC885\uB958\uC640 \uC2A4\uCF54\uD504\\n\\n| \uAD6C\uBD84 | \uC120\uC5B8 \uC704\uCE58 | \uC790\uB3D9 \uCD08\uAE30\uD654 | \uC811\uADFC \uBC29\uC2DD |\\n|------|----------|------------|----------|\\n| \uB85C\uCEEC \uBCC0\uC218 | \uBA54\uC18C\uB4DC \uB0B4\uBD80 | \u274C (\uBBF8\uCD08\uAE30\uD654 \uC2DC \uCEF4\uD30C\uC77C \uC624\uB958) | \uBA54\uC18C\uB4DC \uB0B4\uBD80\uC5D0\uC11C\uB9CC \uC0AC\uC6A9 |\\n| \uC778\uC2A4\uD134\uC2A4 \uBCC0\uC218 | \uBA64\uBC84\uD544\uB4DC | \u2705 (\uD0C0\uC785 \uAE30\uBCF8\uAC12) | `obj.field` |\\n| static \uBCC0\uC218 | \uBA64\uBC84\uD544\uB4DC + static | \u2705 (\uC571 \uC2DC\uC791 \uC2DC \uB85C\uB529) | `ClassName.field` \uAD8C\uACE0 |\\n\\n```java\\nthis.field   // \uBA64\uBC84\uD544\uB4DC \uBA85\uC2DC\uC801 \uC811\uADFC (\uB85C\uCEEC \uBCC0\uC218\uC640 \uC774\uB984 \uCDA9\uB3CC \uC2DC)\\nClassName.staticField  // static\uC740 \uD074\uB798\uC2A4\uBA85\uC73C\uB85C \uC811\uADFC \uAD8C\uACE0\\n```\\n\\n:::warning\\n\uB85C\uCEEC \uBCC0\uC218\uAC00 \uBA64\uBC84\uD544\uB4DC\uC640 **\uAC19\uC740 \uC774\uB984**\uC774\uBA74 \uB85C\uCEEC\uC774 \uC6B0\uC120 (\uBA64\uBC84\uD544\uB4DC\uB97C \uAC00\uB9BC)\\n\\n\uBA64\uBC84\uD544\uB4DC\uB97C \uBA85\uC2DC\uD558\uB824\uBA74 `this.` \uC0AC\uC6A9!\\n:::\\n\\n:::danger\\n`static`\uC744 \uB0A8\uBC1C\uD558\uBA74 \uACF5\uC720 \uC0C1\uD0DC\uB85C \uCD94\uC801\uC774 \uC5B4\uB835\uACE0, \uC571 \uC885\uB8CC\uAE4C\uC9C0 \uBA54\uBAA8\uB9AC\uC5D0 \uC720\uC9C0\uB41C\uB2E4.\\n\uD544\uC694\uD55C \uACF5\uC6A9 \uAE30\uB2A5/\uC0C1\uC218 \uC218\uC900\uC5D0\uC11C\uB9CC \uC81C\uD55C\uC801\uC73C\uB85C \uC0AC\uC6A9\uD560 \uAC83.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uB85C\uCEEC\uBCC0\uC218` `\uC778\uC2A4\uD134\uC2A4\uBCC0\uC218` `static` `this` `\uC2A4\uCF54\uD504`\\n\\n---\\n\\n## 8\uFE0F\u20E3 DTO\uC640 \uB2E8\uC77C \uBC18\uD658\\n\\n\uC790\uBC14\uB294 **\uBC18\uD658\uAC12\uC774 1\uAC1C**\uB9CC \uAC00\uB2A5 \u2192 \uC5EC\uB7EC \uAC12\uC744 \uBC18\uD658\uD574\uC57C \uD560 \uB54C **DTO**\uB97C \uC0AC\uC6A9\uD55C\uB2E4.\\n\\n```java\\n// DTO \uD074\uB798\uC2A4\\nclass InfoUserDTO {\\n    String name;\\n    int age;\\n}\\n\\n// \uBA54\uC18C\uB4DC\uC5D0\uC11C DTO \uBC18\uD658\\nInfoUserDTO getUser() {\\n    InfoUserDTO dto = new InfoUserDTO();\\n    dto.name = \\"\uACBD\uC6A9\\";\\n    dto.age = 25;\\n    return dto;\\n}\\n```\\n\\n:::info\\n**\uCF54\uB4DC \uD0D0\uC0C9 \uD301**\\n- `F3` \uB610\uB294 `Ctrl + \uD074\uB9AD` \u2192 \uC120\uC5B8 \uC704\uCE58\uB85C \uC774\uB3D9\\n:::\\n\\n| \uC6A9\uC5B4 | \uC758\uBBF8 |\\n|------|------|\\n| \uD30C\uB77C\uBBF8\uD130 (Parameter) | \uBA54\uC18C\uB4DC\uAC00 \uC804\uB2EC\uBC1B\uB294 \uAC12\uC744 \uB2F4\uB294 \uBCC0\uC218 |\\n| \uC544\uADDC\uBA3C\uD2B8 (Argument) | \uBA54\uC18C\uB4DC \uD638\uCD9C \uC2DC \uC804\uB2EC\uD558\uB294 \uC2E4\uC81C \uAC12 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `DTO` `\uBC18\uD658\uD0C0\uC785` `\uD30C\uB77C\uBBF8\uD130` `\uC544\uADDC\uBA3C\uD2B8` `static \uC811\uADFC`\\n\\n---\\n\\n## 9\uFE0F\u20E3 \uC5F0\uC0B0\uC790 \uCD1D\uC815\uB9AC\\n\\n### \uC0B0\uC220 \uC5F0\uC0B0 \uC8FC\uC758\uC810\\n\\n```java\\nint result = 5 / 2;       // 2 (\uC815\uC218\uB07C\uB9AC \uB098\uB204\uBA74 \uBAAB\uB9CC)\\nfloat f = 5 / 2;          // 2.0 (\uC5F0\uC0B0\uC740 \uC815\uC218, \uC800\uC7A5\uB9CC float)\\nfloat f2 = 5 / 2.0F;      // 2.5 (\uC2E4\uC218\uAC00 \uCC38\uC5EC\uD574\uC57C \uC2E4\uC218 \uACB0\uACFC)\\nlong l = 10L;             // L \uC811\uBBF8\uC0AC = long \uB9AC\uD130\uB7F4\\n```\\n\\n### \uB300\uC785 \uC5F0\uC0B0 \uC8FC\uC758\\n\\n```java\\ni += 5;   // \uC62C\uBC14\uB978 \uB2E8\uCD95 \uB300\uC785\\ni =+ 5;   // \uC8FC\uC758! \uC591\uC218 \uD45C\uC2DC\uB85C \uD574\uC11D\uB428 (+=\uC640 \uB2E4\uB984)\\n```\\n\\n### \uBE44\uD2B8 \uC5F0\uC0B0\\n\\n```java\\n5 & 4   // 0101 & 0100 = 0100 = 4\\n5 | 4   // 0101 | 0100 = 0101 = 5\\n```\\n\\n### \uC20F\uC11C\uD0B7 (Short-circuit)\\n\\n| \uC5F0\uC0B0\uC790 | \uB3D9\uC791 |\\n|--------|------|\\n| `&&` | \uC55E\uC774 `false`\uBA74 \uB4A4 \uD3C9\uAC00 \uC0DD\uB7B5 |\\n| `\\\\|\\\\|` | \uC55E\uC774 `true`\uBA74 \uB4A4 \uD3C9\uAC00 \uC0DD\uB7B5 |\\n| `&`, `\\\\|` | \uC55E \uACB0\uACFC \uBB34\uAD00\uD558\uAC8C \uB4A4\uAE4C\uC9C0 \uBAA8\uB450 \uD3C9\uAC00 |\\n\\n:::info\\n**\uC5F0\uC0B0\uC790 \uC6B0\uC120\uC21C\uC704** \u2014 \uC804\uCCB4 \uC554\uAE30\uBCF4\uB2E4 **\uAD04\uD638\uAC00 \uCD5C\uC6B0\uC120**\uC774\uB77C\uB294 \uC6D0\uCE59\uB9CC \uAE30\uC5B5\uD558\uC790.\\n\\nIDE\uC758 \uB178\uB780 \uC5B8\uB354\uB77C\uC778\uC740 \uCEF4\uD30C\uC77C \uC624\uB958\uAC00 \uC544\uB2CC **\uD488\uC9C8 \uACBD\uACE0** (\uC0AC\uC6A9 \uC548 \uB41C \uBCC0\uC218, \uBB34\uC758\uBBF8\uD55C \uD45C\uD604 \uB4F1)\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uBAA8\uB4C8\uB7EC\uC2A4` `\uCE90\uC2A4\uD305` `\uC99D\uAC10\uC5F0\uC0B0\uC790` `\uBE44\uD2B8\uC5F0\uC0B0` `\uC20F\uC11C\uD0B7`\\n\\n---\\n\\n## \u{1F51F} char \u2192 \uC22B\uC790 \uBCC0\uD658\\n\\n```java\\nchar c = \'9\';\\n\\nint wrong = (int) c;              // 57 (\uC720\uB2C8\uCF54\uB4DC \uCF54\uB4DC\uD3EC\uC778\uD2B8)\\nint correct1 = c - \'0\';           // 9 (\'0\' \uCF54\uB4DC\uD3EC\uC778\uD2B8\uB97C \uBE7C\uBA74 \uC2E4\uC81C \uC22B\uC790)\\nint correct2 = Character.getNumericValue(c);  // 9 (API \uD65C\uC6A9)\\n```\\n\\n:::info\\n`\'9\'`\uB97C `int`\uB85C \uCE90\uC2A4\uD305\uD558\uBA74 **57** (\uC720\uB2C8\uCF54\uB4DC \uCF54\uB4DC\uD3EC\uC778\uD2B8)\uC774 \uB098\uC628\uB2E4.\\n\\n\uC2E4\uC81C \uC22B\uC790 \uAC12\uC744 \uC5BB\uC73C\uB824\uBA74 `- \'0\'` \uB610\uB294 `Character.getNumericValue()` \uC0AC\uC6A9!\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `char \uCE90\uC2A4\uD305` `\uC720\uB2C8\uCF54\uB4DC` `Character.getNumericValue` `\uB9AC\uD130\uB7F4` `\uD0C0\uC785\uC5F0\uC0B0`\\n\\n---\\n\\n## \u2705 \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. JAR = \uC2E4\uD589 \uAC00\uB2A5\uD55C \uBC30\uD3EC \uC0B0\uCD9C\uBB3C, `java -jar`\uB85C \uC2E4\uD589\\n2. \uC815\uC218 \uB9AC\uD130\uB7F4 \uAE30\uBCF8 = `int`, \uC2E4\uC218 \uB9AC\uD130\uB7F4 \uAE30\uBCF8 = `double`\\n3. `float`\uC5D0 \uC2E4\uC218 \uB123\uC73C\uB824\uBA74 `F` \uC811\uBBF8\uC0AC \uB610\uB294 `(float)` \uCE90\uC2A4\uD305\\n4. `boolean`\uC740 `true`/`false`\uB9CC, **0/1 \uCE58\uD658 \uBD88\uAC00**\\n5. `var`\uB294 \uD0C0\uC785 \uCD94\uB860\uC774\uC9C0 \uB3D9\uC801 \uD0C0\uC785\uC774 \uC544\uB2D8 \u2014 \uD55C \uBC88 \uACB0\uC815\uB418\uBA74 \uACE0\uC815\\n6. \uB85C\uCEEC \uBCC0\uC218\uB294 \uC790\uB3D9 \uCD08\uAE30\uD654 \u274C, \uBA64\uBC84\uD544\uB4DC\uB294 \uC790\uB3D9 \uCD08\uAE30\uD654 \u2705\\n7. `&&`/`||` = \uC20F\uC11C\uD0B7, `&`/`|` = \uC804\uCCB4 \uD3C9\uAC00\\n8. `\'9\'` \u2192 `int` \uCE90\uC2A4\uD305\uD558\uBA74 57, \uC2E4\uC81C \uC22B\uC790 9\uB97C \uC6D0\uD558\uBA74 `- \'0\'`"},{"id":"/2026/02/24/java-ot-setup","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/24/java-ot-setup","source":"@site/blog/2026-02-24-java-ot-setup.md","title":"[TIL] Java OT \u2014 \uAC1C\uBC1C\uD658\uACBD \uAD6C\uCD95\uBD80\uD130 \uAE30\uBCF8 \uBB38\uBC95\uAE4C\uC9C0","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.24","date":"2026-02-24T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"Eclipse","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/eclipse"},{"inline":true,"label":"JDK","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/jdk"},{"inline":true,"label":"\uD658\uACBD\uBCC0\uC218","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uD658\uACBD\uBCC0\uC218"},{"inline":true,"label":"OOP","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/oop"}],"readingTime":5.03,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java OT \u2014 \uAC1C\uBC1C\uD658\uACBD \uAD6C\uCD95\uBD80\uD130 \uAE30\uBCF8 \uBB38\uBC95\uAE4C\uC9C0","date":"2026-02-24T00:00:00.000Z","tags":["Java","Eclipse","JDK","\uD658\uACBD\uBCC0\uC218","OOP"]},"unlisted":false,"prevItem":{"title":"[TIL] Java \uAE30\uCD08 \u2014 JAR, \uD0C0\uC785, \uC5F0\uC0B0, \uBCC0\uC218","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/25/java-jar-type-operator"},"nextItem":{"title":"[TIL] \uBD80\uD2B8\uCEA0\uD504 1\uC77C\uCC28 \u2014 OT, \uCD9C\uACB0, \uCDE8\uC5C5\uC9C0\uC6D0 \uCD1D\uC815\uB9AC","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/23/bootcamp-day01-OT"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.24\\n\\n## \u{1F5FA} \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uC6B4\uC601 \uADDC\uCE59 \uC548\uB0B4 \u2192 \uAE30\uC220 \uC2A4\uD0DD \uC18C\uAC1C \u2192 JDK \uC124\uCE58 \u2192 \uD658\uACBD\uBCC0\uC218 \uC124\uC815\\n\u2192 Eclipse \uC124\uCE58 \u2192 \uC790\uBC14 \uAE30\uBCF8 \uAD6C\uC870 \u2192 \uBCC0\uC218/\uD0C0\uC785 \u2192 \uAC1D\uCCB4/\uBA54\uC18C\uB4DC \u2192 \uC811\uADFC \uC81C\uC5B4\uC790\\n```\\n\\n---\\n\\n## 1\uFE0F\u20E3 \uC628\uB77C\uC778 \uC218\uC5C5 \uC6B4\uC601 \uADDC\uCE59\\n\\n- \uC18C\uD1B5\uC740 \uB77C\uC774\uBE0C\uB8F8 \uCC44\uD305\uC774 \uC544\uB2CC **\uD074\uB798\uC2A4\uCC57(\uC2A4\uB808\uB4DC)** \uC911\uC2EC\\n- \uCD9C\uC11D/QR \uCCB4\uD06C\uB294 \uC218\uB2F9 \uD589\uC815\uACFC \uC5F0\uB3D9\uB418\uBBC0\uB85C \uBC18\uB4DC\uC2DC \uC218\uD589\\n- 4\uC2DC~6\uC2DC\uB294 \uACFC\uC81C \uBC0F \uC790\uC728\uD559\uC2B5 \uC2DC\uAC04\\n\\n:::info\\n\uC218\uC5C5 \uC911 \uC774\uD574\uAC00 \uC548 \uB418\uBA74 \uB77C\uC774\uBE0C\uB8F8 \uCC44\uD305 \uB9D0\uACE0 **\uC2A4\uB808\uB4DC\uC5D0 \uC989\uC2DC \uC694\uCCAD**\uC744 \uB0A8\uAE30\uB294 \uAC8C \uC6D0\uCE59\uC774\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD074\uB798\uC2A4\uCC57` `\uB77C\uC774\uBE0C\uB8F8` `\uCD9C\uC11D\uCCB4\uD06C` `QR` `\uC790\uC728\uD559\uC2B5`\\n\\n---\\n\\n## 2\uFE0F\u20E3 \uACFC\uC815 \uAE30\uC220 \uC2A4\uD0DD & IDE \uC120\uD0DD\\n\\n| \uAD6C\uBD84 | \uB3C4\uAD6C/\uAE30\uC220 | \uC120\uD0DD \uC774\uC720 |\\n|------|----------|----------|\\n| IDE | Eclipse | \uBB34\uB8CC, \uC2E4\uBB34 \uD45C\uC900 \uC124\uCE58 \uBC29\uC2DD \uAD50\uC721\uC5D0 \uC801\uD569 |\\n| \uBCF4\uC870 \uB3C4\uAD6C | VS Code | \uBC94\uC6A9 \uD3B8\uC9D1/\uBCF4\uC870 \uC791\uC5C5 |\\n| DB \uB3C4\uAD6C | DBeaver | DB \uC2E4\uC2B5 \uC2DC \uD65C\uC6A9 |\\n| \uC11C\uBC84 | Tomcat | JSP \uB4F1 \uB808\uAC70\uC2DC/\uACF5\uACF5\uAE30\uAD00 \uC2E4\uBB34 \uD750\uB984 \uB300\uC751 |\\n| \uBE4C\uB4DC/\uBC30\uD3EC | Maven, Jenkins | \uD328\uD0A4\uC9D5/\uBC30\uD3EC \uD750\uB984 \uACBD\uD5D8 |\\n\\n:::info\\nIntelliJ\uB294 \uAC15\uB825\uD558\uC9C0\uB9CC \uC720\uB8CC \uD50C\uB79C \uC774\uC288\uB85C \uACFC\uC815 \uD45C\uC900 \uB3C4\uAD6C\uC5D0\uC11C \uC81C\uC678\uB410\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC774\uD074\uB9BD\uC2A4` `\uD1B0\uCEA3` `\uD0C0\uC784\uB9AC\uD504` `\uC820\uD0A8\uC2A4` `DBeaver`\\n\\n---\\n\\n## 3\uFE0F\u20E3 AI \uB3C4\uAD6C \uD65C\uC6A9 \uD301\\n\\nAI\uB294 \uC4F0\uB294 \uBC29\uC2DD\uC5D0 \uB530\uB77C \uD488\uC9C8\uC774 \uD06C\uAC8C \uB2EC\uB77C\uC9C4\uB2E4.\\n\\n| \uD56D\uBAA9 | \uAD8C\uC7A5 \uBC29\uC2DD | \uC8FC\uC758\uC810 |\\n|------|----------|--------|\\n| \uC8FC\uC81C \uAD00\uB9AC | \uC8FC\uC81C\uBCC4 \uCC44\uD305 \uD0ED \uBD84\uB9AC | \uC8FC\uC81C\uAC00 \uC11E\uC774\uBA74 \uC5C9\uB6B1\uD55C \uB2F5\uBCC0\uC774 \uB098\uC634 |\\n| \uC5ED\uD560 \uBD80\uC5EC | \uC2DC\uC2A4\uD15C \uBA54\uC2DC\uC9C0\uB85C \uC804\uBB38\uAC00 \uC5ED\uD560 \uC9C0\uC815 | \uC5ED\uD560 \uC5C6\uC73C\uBA74 \uB9E5\uB77D\uC774 \uD750\uB824\uC9D0 |\\n| \uC801\uC6A9 \uC804\uB7B5 | \uC18C\uC2A4 \uC804\uCCB4\uBCF4\uB2E4 \uBD80\uBD84 \uB2E8\uC704\uB85C \uC694\uCCAD | \uC804\uCCB4 \uD22C\uCC99\uD558\uBA74 \uCF54\uB4DC\uAC00 \uAF2C\uC77C \uC218 \uC788\uC74C |\\n\\n```\\n[\uC2DC\uC2A4\uD15C] \uB2F9\uC2E0\uC740 \uC790\uBC14 \uAC1C\uBC1C\uC790\uC785\uB2C8\uB2E4.\\n[\uC720\uC800] macOS\uC5D0\uC11C JDK 21 \uC124\uCE58 \uBC29\uBC95\uC744 \uB2E8\uACC4\uBCC4\uB85C \uC124\uBA85\uD574 \uC8FC\uC138\uC694.\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC2DC\uC2A4\uD15C\uBA54\uC2DC\uC9C0` `\uC720\uC800\uBA54\uC2DC\uC9C0` `\uD504\uB86C\uD504\uD2B8` `LLM` `Claude`\\n\\n---\\n\\n## 4\uFE0F\u20E3 JDK \uBC84\uC804 \uC120\uD0DD \uAE30\uC900\\n\\n| \uD56D\uBAA9 | \uB0B4\uC6A9 |\\n|------|------|\\n| \uACFC\uC815 \uD45C\uC900 | JDK 21 (LTS) |\\n| \uC2E4\uBB34 \uBD84\uD3EC | JDK 17\uACFC 21\uC774 \uC8FC\uB958 |\\n| \uC120\uD0DD \uADFC\uAC70 | \uC624\uB77C\uD074 Support Roadmap\uC758 LTS \uC9C0\uC6D0 \uAE30\uAC04 |\\n| \uC8FC\uC758 | \uD504\uB808\uC784\uC6CC\uD06C/\uB3C4\uAD6C\uB9C8\uB2E4 \uD638\uD658 \uBC84\uC804 \uB2E4\uB97C \uC218 \uC788\uC74C |\\n\\n:::info\\n\uCD5C\uC2E0 \uBC84\uC804\uC774 \uD56D\uC0C1 \uCD5C\uC120\uC740 \uC544\uB2C8\uB2E4. \uC2E4\uBB34\uB294 **\uC548\uC815\uC131 + \uC9C0\uC6D0 \uAE30\uAC04** \uAE30\uC900\uC73C\uB85C LTS\uB97C \uC120\uD0DD\uD55C\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `JDK21` `LTS` `Support Roadmap` `\uD638\uD658\uC131` `\uBC84\uC804\uC804\uB7B5`\\n\\n---\\n\\n## 5\uFE0F\u20E3 JDK \uB2E4\uC6B4\uB85C\uB4DC\uC640 \uB9E4\uB274\uC5BC \uC124\uCE58\\n\\n\uACFC\uC815 \uD45C\uC900\uC740 **Amazon Corretto 21** (\uC624\uD508\uC18C\uC2A4 \uBC30\uD3EC\uD310).\\n\\n:::warning\\nWindows\uC5D0\uC11C\uB294 `C:\\\\Java` \uCC98\uB7FC **\uACF5\uBC31 \uC5C6\uB294 \uB8E8\uD2B8 \uACBD\uB85C**\uC5D0 \uC124\uCE58\uD560 \uAC83.\\n`Program Files`\uB294 \uACF5\uBC31\uC774 \uD3EC\uD568\uB418\uC5B4 \uC788\uC5B4 \uC2A4\uD06C\uB9BD\uD2B8/\uC678\uBD80 \uC2DC\uC2A4\uD15C\uC5D0\uC11C \uC624\uB3D9\uC791\uD560 \uC218 \uC788\uB2E4.\\n:::\\n\\n**JDK \uD3F4\uB354 \uAD6C\uC870**\\n\\n| \uB514\uB809\uD130\uB9AC | \uC5ED\uD560 |\\n|---------|------|\\n| `bin` | java, javac \uB4F1 \uC2E4\uD589 \uBA85\uB839 \uBC14\uC774\uB108\uB9AC |\\n| `lib` | \uC2E4\uD589\uC5D0 \uD544\uC694\uD55C \uB77C\uC774\uBE0C\uB7EC\uB9AC \uB9AC\uC18C\uC2A4 |\\n| `conf` | \uB7F0\uD0C0\uC784 \uB3D9\uC791 \uC124\uC815 \uD30C\uC77C |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Amazon Corretto` `\uB9E4\uB274\uC5BC\uC124\uCE58` `bin` `lib` `conf`\\n\\n---\\n\\n## 6\uFE0F\u20E3 JAVA_HOME \uD658\uACBD\uBCC0\uC218 \uC124\uC815\\n\\n`JAVA_HOME`\uC740 \uC790\uBC14 \uAE30\uBC18 \uC18C\uD504\uD2B8\uC6E8\uC5B4\uAC00 JDK \uC704\uCE58\uB97C \uACF5\uD1B5 \uCC38\uC870\uD558\uB294 \uD45C\uC900 \uD658\uACBD\uBCC0\uC218\uB2E4.\\n\\n```cmd\\necho %JAVA_HOME%\\n```\\n\\n:::warning\\n- \uAC12\uC740 JDK \uB8E8\uD2B8 \uD3F4\uB354\uAE4C\uC9C0\uB9CC (bin \uD3EC\uD568 \u274C)\\n- **\uC2DC\uC2A4\uD15C \uBCC0\uC218**\uB85C \uC124\uC815\uD574\uC57C \uC804\uCCB4 \uACC4\uC815/\uD504\uB85C\uC138\uC2A4\uC5D0 \uC801\uC6A9\uB428\\n- \uC124\uC815 \uD6C4 CMD\uB97C \uC0C8\uB85C \uC5F4\uC5B4\uC57C \uBC18\uC601\uB428\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `JAVA_HOME` `\uC2DC\uC2A4\uD15C\uBCC0\uC218` `echo` `CMD` `\uD45C\uC900\uD658\uACBD`\\n\\n---\\n\\n## 7\uFE0F\u20E3 PATH \uD658\uACBD\uBCC0\uC218 \uC124\uC815\uACFC \uAC80\uC99D\\n\\n`Path` \uC2DC\uC2A4\uD15C \uBCC0\uC218\uC5D0 `%JAVA_HOME%\\\\bin` \uCD94\uAC00 \u2192 \uC5B4\uB514\uC11C\uB4E0 `java` \uBA85\uB839 \uC2E4\uD589 \uAC00\uB2A5\\n\\n```cmd\\njava -version\\n```\\n\\n**\uC790\uC8FC \uACAA\uB294 \uBB38\uC81C**\\n\\n| \uC99D\uC0C1 | \uC6D0\uC778 | \uC870\uCE58 |\\n|------|------|------|\\n| `java -version`\uC774 1.8\uB85C \uCD9C\uB825 | Path \uC0C1\uB2E8\uC5D0 \uAE30\uC874 JDK \uACBD\uB85C \uC6B0\uC120 \uC801\uC6A9 | \uAE30\uC874 Oracle JDK \uACBD\uB85C \uC0AD\uC81C \uB610\uB294 \uC21C\uC11C \uC870\uC815 |\\n| `echo %JAVA_HOME%`\uC774 \uBB38\uC790\uC5F4 \uADF8\uB300\uB85C \uCD9C\uB825 | \uD658\uACBD\uBCC0\uC218 \uBBF8\uC801\uC6A9 | \uC2DC\uC2A4\uD15C \uBCC0\uC218 \uC7AC\uB4F1\uB85D \uD6C4 \uCC3D \uBAA8\uB450 \uB2EB\uACE0 CMD \uC7AC\uC2E4\uD589 |\\n| Mac\uC5D0\uC11C \uD655\uC778 \uBC29\uBC95 \uB2E4\uB984 | Unix \uACC4\uC5F4\uC740 `$VAR` \uD45C\uAE30 | `echo $JAVA_HOME` \uC73C\uB85C \uD655\uC778 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `PATH` `\uC6B0\uC120\uC21C\uC704` `java -version` `\uC911\uBCF5JDK` `CLI`\\n\\n---\\n\\n## 8\uFE0F\u20E3 Eclipse \uD328\uD0A4\uC9C0 \uC124\uCE58\uC640 \uC2E4\uD589 \uC124\uC815\\n\\n- **Installer \uB9D0\uACE0 Package(\uC555\uCD95)\uB85C \uC124\uCE58** \u2192 \uC5EC\uB7EC \uBC84\uC804 \uBD84\uB9AC \uC6B4\uC601 \uAC00\uB2A5\\n- \uBC84\uC804: 2025-12 \uB9B4\uB9AC\uC2A4 \uC0AC\uC6A9\\n- \uC124\uCE58 \uACBD\uB85C: `C:\\\\Program_Eclipse` \uCC98\uB7FC \uACF5\uBC31 \uC5C6\uB294 \uACBD\uB85C \uAD8C\uC7A5\\n\\n### eclipse.ini \uC124\uC815\\n\\n\uC774\uD074\uB9BD\uC2A4\uAC00 \uC2DC\uC2A4\uD15C JRE \uB300\uC2E0 \uC124\uCE58\uD55C JDK\uB97C \uBC14\uB77C\uBCF4\uAC8C \uC124\uC815\\n\\n```ini\\n-vm\\nC:\\\\Java\\\\amazon-corretto-21\\\\bin\\\\javaw.exe\\n```\\n\\n:::info\\n\uC6CC\uD06C\uC2A4\uD398\uC774\uC2A4\uB294 \uD504\uB85C\uC81D\uD2B8 \uC791\uC5C5 \uACF5\uAC04\uC774\uBBC0\uB85C `java` \uCC98\uB7FC \uBAA9\uC801\uC774 \uB4DC\uB7EC\uB098\uB294 \uC774\uB984 \uAD8C\uC7A5\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Eclipse Package` `eclipse.ini` `-vm` `\uC6CC\uD06C\uC2A4\uD398\uC774\uC2A4` `JRE`\\n\\n---\\n\\n## 9\uFE0F\u20E3 \uC790\uBC14 \uAE30\uBCF8 \uAD6C\uC870\uC640 \uC2E4\uD589 \uD750\uB984\\n\\n| \uC694\uC18C | \uC758\uBBF8 | \uD575\uC2EC \uADDC\uCE59 |\\n|------|------|----------|\\n| \uD074\uB798\uC2A4 | \uAC12/\uAE30\uB2A5\uC758 \uBB36\uC74C, \uD0C0\uC785\uC774 \uB428 | `public` \uD074\uB798\uC2A4\uBA85 = \uD30C\uC77C\uBA85 \uC77C\uCE58 |\\n| \uBA54\uC18C\uB4DC | \uAE30\uB2A5\uC758 \uB2E8\uC704, \uD638\uCD9C\uB85C \uC2E4\uD589 | \uBC18\uD658 \uD0C0\uC785 \uC788\uC73C\uBA74 `return` \uD544\uC694 |\\n| `main` | \uD504\uB85C\uADF8\uB7A8 \uC2DC\uC791\uC810 | `public static void main(String[] args)` |\\n| \uD638\uCD9C | \uC810(`.`)\uC73C\uB85C \uD558\uC704 \uBA64\uBC84 \uC811\uADFC | \uAC1D\uCCB4 \uC778\uC2A4\uD134\uC2A4\uAC00 \uC788\uC5B4\uC57C \uD638\uCD9C \uAC00\uB2A5 |\\n\\n:::info\\n\uC790\uBC14\uB294 **\uCEF4\uD30C\uC77C \uC5B8\uC5B4** \u2014 \uBA54\uC18C\uB4DC \uC815\uC758 \uC21C\uC11C\uB294 \uC2E4\uD589\uACFC \uBB34\uAD00\uD558\uB2E4.\\nHTML\uCC98\uB7FC \uC704\uC5D0\uC11C \uC544\uB798\uB85C \uC989\uC2DC \uD574\uC11D\uB418\uB294 \uC778\uD130\uD504\uB9AC\uD130 \uBC29\uC2DD\uACFC \uB2E4\uB974\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `main\uBA54\uC18C\uB4DC` `\uD074\uB798\uC2A4\uBA85\uADDC\uCE59` `\uCEF4\uD30C\uC77C` `System.out.println` `API`\\n\\n---\\n\\n## \u{1F51F} \uBCC0\uC218, \uD0C0\uC785, \uB300\uC785, \uC778\uC2A4\uD134\uC2A4\uD654\\n\\n```java\\nint n = 10;           // \uB300\uC785: \uC624\uB978\uCABD \uAC12\uC744 \uC67C\uCABD \uBCC0\uC218\uC5D0 \uC800\uC7A5\\nString s = \\"hello\\";   // \uCC38\uC870 \uD0C0\uC785\\nCoffee c = new Coffee(); // \uC778\uC2A4\uD134\uC2A4\uD654: \uD074\uB798\uC2A4\uB97C \uBA54\uBAA8\uB9AC\uC5D0 \uC62C\uB824 \uAC1D\uCCB4 \uC0DD\uC131\\n```\\n\\n- \uAE30\uBCF8 \uD0C0\uC785: \uC5B8\uC5B4\uAC00 \uBBF8\uB9AC \uC815\uC758\uD55C \uD0C0\uC785 (`int`, `char`, `boolean` \uB4F1)\\n- \uCC38\uC870 \uD0C0\uC785: `new` \uB4F1\uC73C\uB85C \uC0DD\uC131\uB418\uB294 \uBCF5\uD569 \uAD6C\uC870\\n- \uC624\uB958(\uBE68\uAC04 \uC904) = \uBB38\uBC95/\uD0C0\uC785/\uC138\uBBF8\uCF5C\uB860/\uBC18\uD658 \uB4F1 \uADDC\uCE59 \uC704\uBC18 \u2192 **\uBC18\uB4DC\uC2DC \uD574\uACB0 \uD6C4 \uC9C4\uD589**\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uBCC0\uC218` `\uB370\uC774\uD130\uD0C0\uC785` `\uB300\uC785\uC5F0\uC0B0\uC790` `new` `\uC778\uC2A4\uD134\uC2A4\uD654`\\n\\n---\\n\\n## 1\uFE0F\u20E31\uFE0F\u20E3 \uCEE4\uD53C \uC608\uC81C\uB85C \uBCF4\uB294 \uD074\uB798\uC2A4/\uBA54\uC18C\uB4DC/\uAC1D\uCCB4\\n\\n```java\\nMachine m = new Machine();\\nCoffee c = m.order();\\nSystem.out.println(c.name);\\nSystem.out.println(c.sugar);\\n```\\n\\n| \uD074\uB798\uC2A4 | \uC5ED\uD560 | \uD3EC\uD568 \uC694\uC18C |\\n|--------|------|----------|\\n| `Coffee` | \uAC12\uC744 \uB2F4\uB294 \uD074\uB798\uC2A4 (POJO) | `String name`, `String sugar` \uB4F1 \uD544\uB4DC |\\n| `Machine` | \uAE30\uB2A5 \uC911\uC2EC \uD074\uB798\uC2A4 | `public Coffee order()`, `private Coffee make()` |\\n| `CoffeeMain` | \uC2E4\uD589 \uC2DC\uC791\uC810 | `main`\uC5D0\uC11C \uAC1D\uCCB4 \uC0DD\uC131 \uBC0F \uCD9C\uB825 |\\n\\n:::warning\\n\uC790\uC8FC \uB098\uC624\uB294 \uC624\uB958\uB4E4:\\n- \uC138\uBBF8\uCF5C\uB860 \uB204\uB77D\\n- \uD30C\uC77C\uBA85/\uD074\uB798\uC2A4\uBA85 \uBD88\uC77C\uCE58\\n- `println` \uC624\uD0C0 (`IN` / `LN` \uAD6C\uBD84)\\n- `System.err` \uC798\uBABB \uC0AC\uC6A9\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `POJO` `\uBC18\uD658\uD0C0\uC785` `\uBA54\uC18C\uB4DC\uD638\uCD9C` `\uAC1D\uCCB4\uC0DD\uC131` `\uC2E4\uD589\uD750\uB984`\\n\\n---\\n\\n## 1\uFE0F\u20E32\uFE0F\u20E3 \uC811\uADFC \uC81C\uC5B4\uC790\\n\\n| \uC81C\uC5B4\uC790 | \uC811\uADFC \uBC94\uC704 | \uD55C \uC904 \uC815\uB9AC |\\n|--------|----------|----------|\\n| `public` | \uC804\uCCB4 \uACF5\uAC1C | \uBAA8\uB4E0 \uD328\uD0A4\uC9C0/\uD074\uB798\uC2A4\uC5D0\uC11C \uC811\uADFC \uAC00\uB2A5 |\\n| `private` | \uB0B4\uBD80 \uC804\uC6A9 | \uC120\uC5B8\uD55C \uD074\uB798\uC2A4 \uB0B4\uBD80\uC5D0\uC11C\uB9CC \uC811\uADFC \uAC00\uB2A5 |\\n| `protected` | \uC0C1\uC18D \uBC94\uC704 | \uC790\uC2DD \uD074\uB798\uC2A4\uC5D0\uC11C \uC811\uADFC \uAC00\uB2A5 |\\n| `default` | \uD328\uD0A4\uC9C0 \uBC94\uC704 | \uAC19\uC740 \uD328\uD0A4\uC9C0 \uC18C\uC18D\uC5D0\uC11C\uB9CC \uC811\uADFC \uAC00\uB2A5 |\\n\\n:::info\\n\uBAA8\uB4E0 \uC790\uBC14 \uD074\uB798\uC2A4\uB294 \uAE30\uBCF8\uC801\uC73C\uB85C `extends Object`\uB97C \uD3EC\uD568\uD55C\uB2E4.\\n\uC790\uB3D9\uC644\uC131\uC5D0\uC11C \uBCF4\uC774\uB294 `notify`, `hashCode` \uB4F1\uC740 **Object\uB85C\uBD80\uD130 \uC0C1\uC18D\uB41C \uAE30\uB2A5**\uC774\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `public` `private` `protected` `default` `\uD328\uD0A4\uC9C0`\\n\\n---\\n\\n## 1\uFE0F\u20E33\uFE0F\u20E3 \uD30C\uB77C\uBBF8\uD130 vs \uC544\uADDC\uBA3C\uD2B8\\n\\n```java\\nvoid order(int money) {  // money\uB294 \uD30C\uB77C\uBBF8\uD130\\n    System.out.println(money);\\n}\\norder(100);  // 100\uC740 \uC544\uADDC\uBA3C\uD2B8\\n```\\n\\n- **\uD30C\uB77C\uBBF8\uD130**: \uBA54\uC18C\uB4DC \uC120\uC5B8\uBD80\uC758 \uC785\uB825 \uBCC0\uC218\\n- **\uC544\uADDC\uBA3C\uD2B8**: \uD638\uCD9C \uC2DC \uC2E4\uC81C\uB85C \uC804\uB2EC\uD558\uB294 \uAC12\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD30C\uB77C\uBBF8\uD130` `\uC544\uADDC\uBA3C\uD2B8` `\uBA54\uC18C\uB4DC` `\uC785\uB825\uAC12` `\uC6A9\uC5B4\uAD6C\uBD84`\\n\\n---\\n\\n## 1\uFE0F\u20E34\uFE0F\u20E3 \uC8FC\uC11D, \uC608\uC57D\uC5B4, \uC778\uCF54\uB529\\n\\n```java\\n// \uB2E8\uC904 \uC8FC\uC11D\\n/* \uB2E4\uC911 \uC8FC\uC11D\\n   \uC5EC\uB7EC \uC904 \uAC00\uB2A5 */\\n```\\n\\n- **\uC608\uC57D\uC5B4**: IDE\uC5D0\uC11C \uC0C9\uC774 \uCE60\uD574\uC9C4 \uD1A0\uD070 \u2192 \uBCC0\uC218\uBA85/\uD074\uB798\uC2A4\uBA85\uC73C\uB85C \uC0AC\uC6A9 \uBD88\uAC00\\n- **\uC778\uCF54\uB529**: UTF-8\uC744 \uD45C\uC900\uC73C\uB85C \uC124\uC815 \u2192 \uD55C\uAE00 \uAE68\uC9D0 \uC608\uBC29\\n\\n:::warning\\n\uD55C\uAD6D \uD658\uACBD\uC5D0\uC11C EUC-KR\uC774 \uC5B8\uAE09\uB420 \uC218 \uC788\uC9C0\uB9CC, \uD611\uC5C5/\uBC30\uD3EC/\uB2E4\uAD6D\uC5B4 \uD658\uACBD\uC5D0\uC11C\uB294 **UTF-8\uC774 \uD45C\uC900**\uC774\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC8FC\uC11D` `\uC608\uC57D\uC5B4` `UTF-8` `EUC-KR` `\uC778\uCF54\uB529`\\n\\n---\\n\\n## \u2705 \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. JDK\uB294 **Amazon Corretto 21 LTS**, \uACF5\uBC31 \uC5C6\uB294 \uACBD\uB85C\uC5D0 \uC218\uB3D9 \uC124\uCE58\\n2. `JAVA_HOME` \u2192 JDK \uB8E8\uD2B8 \uACBD\uB85C (bin \uBBF8\uD3EC\uD568), \uC2DC\uC2A4\uD15C \uBCC0\uC218\uB85C \uC124\uC815\\n3. `PATH` \u2192 `%JAVA_HOME%\\\\bin` \uCD94\uAC00, \uAE30\uC874 JDK \uACBD\uB85C \uC911\uBCF5 \uC8FC\uC758\\n4. Eclipse\uB294 **Package(\uC555\uCD95)** \uBC29\uC2DD, `eclipse.ini`\uC5D0\uC11C JDK \uBA85\uC2DC \uC5F0\uACB0\\n5. \uC790\uBC14\uB294 **\uD30C\uC77C\uBA85 = \uD074\uB798\uC2A4\uBA85**, `main`\uC774 \uC5C6\uC73C\uBA74 \uC2E4\uD589 \uBD88\uAC00\\n6. `new` = \uC778\uC2A4\uD134\uC2A4\uD654, `.` = \uBA64\uBC84 \uC811\uADFC, `=` = \uC624\uB978\uCABD \uAC12\uC744 \uC67C\uCABD\uC5D0 \uC800\uC7A5\\n7. AI \uC4F8 \uB54C\uB294 **\uC8FC\uC81C \uBD84\uB9AC + \uC5ED\uD560 \uBD80\uC5EC** \uBA3C\uC800"},{"id":"/2026/02/23/bootcamp-day01-OT","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/23/bootcamp-day01-OT","source":"@site/blog/2026-02-23-bootcamp-day01-OT.md","title":"[TIL] \uBD80\uD2B8\uCEA0\uD504 1\uC77C\uCC28 \u2014 OT, \uCD9C\uACB0, \uCDE8\uC5C5\uC9C0\uC6D0 \uCD1D\uC815\uB9AC","description":"\u{1F5FA} \uC624\uB298 \uB2E4\uB8EC \uB0B4\uC6A9 \uD55C\uB208\uC5D0 \uBCF4\uAE30","date":"2026-02-23T00:00:00.000Z","tags":[{"inline":true,"label":"\uBD80\uD2B8\uCEA0\uD504","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uBD80\uD2B8\uCEA0\uD504"},{"inline":true,"label":"KDT","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/kdt"},{"inline":true,"label":"OT","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/ot"},{"inline":true,"label":"\uCD9C\uACB0","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uCD9C\uACB0"},{"inline":true,"label":"\uCDE8\uC5C5\uC9C0\uC6D0","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uCDE8\uC5C5\uC9C0\uC6D0"}],"readingTime":4.57,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] \uBD80\uD2B8\uCEA0\uD504 1\uC77C\uCC28 \u2014 OT, \uCD9C\uACB0, \uCDE8\uC5C5\uC9C0\uC6D0 \uCD1D\uC815\uB9AC","date":"2026-02-23T00:00:00.000Z","tags":["\uBD80\uD2B8\uCEA0\uD504","KDT","OT","\uCD9C\uACB0","\uCDE8\uC5C5\uC9C0\uC6D0"]},"unlisted":false,"prevItem":{"title":"[TIL] Java OT \u2014 \uAC1C\uBC1C\uD658\uACBD \uAD6C\uCD95\uBD80\uD130 \uAE30\uBCF8 \uBB38\uBC95\uAE4C\uC9C0","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/24/java-ot-setup"}},"content":"## \u{1F5FA} \uC624\uB298 \uB2E4\uB8EC \uB0B4\uC6A9 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uD074\uB798\uC2A4\uB8F8/\uD074\uB798\uC2A4\uCC57 \u2192 QR \uCD9C\uACB0 \uCCB4\uACC4 \u2192 \uC9C0\uAC01/\uC870\uD1F4/\uC678\uCD9C \uADDC\uCE59\\n\u2192 \uACF5\uACB0/\uC815\uC815 \uC808\uCC28 \u2192 \uC81C\uC801\xb7\uC218\uB8CC \uAE30\uC900 \u2192 \uCEE4\uB9AC\uC5B4 OT \u2192 \uCDE8\uC5C5\uC9C0\uC6D0 \uD504\uB85C\uADF8\uB7A8\\n```\\n\\n---\\n\\n## 1\uFE0F\u20E3 \uD074\uB798\uC2A4\uB8F8 & \uD074\uB798\uC2A4\uCC57 \uC6B4\uC601 \uAD6C\uC870\\n\\n\uC218\uC5C5 \uAD00\uB828 \uCC44\uB110\uC740 \uD074\uB798\uC2A4\uCC57 \uAE30\uBC18\uC73C\uB85C \uC6B4\uC601\uB41C\uB2E4. \uCC98\uC74C \uC811\uC18D\uD558\uBA74 `general`\uB9CC \uBCF4\uC774\uB294\uB370, \uC88C\uCE21 \uD558\uB2E8 **\uB514\uB809\uD1A0\uB9AC**\uC5D0\uC11C \uCC44\uB110\uC744 \uCC3E\uC544 `\uCC38\uC5EC` \uBC84\uD2BC\uC73C\uB85C \uCD94\uAC00\uD574\uC57C \uD55C\uB2E4.\\n\\n| \uAD6C\uBD84 | \uCC44\uB110 | \uBAA9\uC801 |\\n|------|------|------|\\n| \uACF5\uC9C0 | \uACF5\uC9C0\uC0AC\uD56D | \uC77C\uC815, \uD544\uB3C5 \uC548\uB0B4 (\uD074\uB798\uC2A4\uB8F8/\uCC57 \uB3D9\uC77C) |\\n| \uC218\uC5C5 Q&A | \uAC15\uC758 \uC911 \uCC44\uB110 (\uC2A4\uB808\uB4DC) | \uC218\uC5C5 \uD750\uB984 \uC720\uC9C0\uD558\uBA70 \uC9C8\uBB38 |\\n| \uC6B4\uC601 Q&A | \uBB34\uC5C7\uC774\uB4E0 \uBB3C\uC5B4\uBCF4\uC138\uC694 | \uD589\uC815/\uC6B4\uC601 \uC804\uBC18 \uBB38\uC758 |\\n| \uCD9C\uACB0 \uBCF4\uC870 | QR \uC694\uCCAD\uBC29 | QR \uBBF8\uB178\uCD9C \uC2DC\uAC04 \uC694\uCCAD |\\n\\n:::info\\n**AI \uB178\uD2B8** \uAE30\uB2A5: \uC218\uC5C5 \uB2E4\uC74C\uB0A0 \uC694\uC57D\uBCF8\uC774 \uC790\uB3D9 \uC0DD\uC131\uB418\uC5B4 \uBCF5\uC2B5\uC5D0 \uD65C\uC6A9 \uAC00\uB2A5\uD558\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD074\uB798\uC2A4\uCC57` `\uB514\uB809\uD1A0\uB9AC` `\uC2A4\uB808\uB4DC` `\uACF5\uC9C0\uC0AC\uD56D` `AI\uB178\uD2B8`\\n\\n---\\n\\n## 2\uFE0F\u20E3 \uAD50\uC721 \uC6B4\uC601 \uADDC\uC815\\n\\n- \uC218\uC5C5 \uC2DC\uAC04: 09:00 ~ 18:00 (50\uBD84 \uC218\uC5C5 + 10\uBD84 \uD734\uC2DD)\\n- \uC810\uC2EC: 11:50 ~ 13:00 (\uAC15\uC0AC \uC7AC\uB7C9\uC73C\uB85C \uC720\uB3D9)\\n- \uAC1C\uAC15\uC77C/\uC885\uAC15\uC77C: 14:00 ~ 18:00 \uBCC4\uB3C4 \uC6B4\uC601\\n- \uACF5\uD734\uC77C \uD734\uAC15\\n\\n### \uCE74\uBA54\uB77C \uCD9C\uC11D \uADDC\uC815\\n\\n**\uCE74\uBA54\uB77C ON\uC774 \uCD9C\uC11D\uC758 \uD575\uC2EC \uC804\uC81C\uB2E4.** \uC5BC\uAD74(\uB208, \uCF54, \uC785)\uC774 \uC2DD\uBCC4 \uAC00\uB2A5\uD574\uC57C \uCD9C\uC11D\uC73C\uB85C \uC778\uC815\uB41C\uB2E4.\\n\\n:::warning\\n\uC778\uD130\uB137 \uC7AC\uC5F0\uACB0 \uC2DC \uCE74\uBA54\uB77C\uAC00 \uAEBC\uC9C8 \uC218 \uC788\uC5B4 \uC218\uC2DC\uB85C \uD655\uC778\uD574\uC57C \uD55C\uB2E4.\\n:::\\n\\n| \uC6B4\uC601 \uD56D\uBAA9 | \uAE30\uC900 | \uC8FC\uC758\uC810 |\\n|----------|------|--------|\\n| \uCE74\uBA54\uB77C \uCD9C\uC11D | \uC5BC\uAD74 \uC2DD\uBCC4 \uAC00\uB2A5 \uD544\uC218 | \uC7AC\uC5F0\uACB0 \uD6C4 \uCE74\uBA54\uB77C \uAEBC\uC9D0 \uC8FC\uC758 |\\n| \uBB34\uB2E8\uC774\uD0C8 | 15\uBD84 \uC774\uC0C1 \uC774\uD0C8 \uB610\uB294 \uCE74\uBA54\uB77C OFF | \uC7A0\uAE50 \uC774\uB3D9\uB3C4 \uC678\uCD9C \uC808\uCC28 \uD544\uC694 |\\n| \uD68C\uACE0 (16~18\uC2DC) | \uC218\uC5C5 \uC2DC\uAC04\uC73C\uB85C \uAC04\uC8FC | \uD68C\uACE0 \uC911\uC5D0\uB3C4 \uCE74\uBA54\uB77C ON |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uCE74\uBA54\uB77C\uC628` `\uD68C\uACE0` `\uC8FC\uAC04\uC124\uBB38` `\uBB34\uB2E8\uC774\uD0C8` `\uD559\uC2B5\uAE30\uB85D`\\n\\n---\\n\\n## 3\uFE0F\u20E3 QR \uCD9C\uACB0 \uCCB4\uACC4\\n\\n\uCD9C\uACB0\uC740 **\uBA38\uC0ACA** \uC571\uC5D0\uC11C QR \uCCB4\uD06C + \uAC15\uC758\uC2E4 \uC785\uC7A5 \uB450 \uAC00\uC9C0\uB97C \uBAA8\uB450 \uC644\uB8CC\uD574\uC57C \uD55C\uB2E4.\\n\\n:::danger \uC911\uC694\\n\\"\uCCB4\uD06C \uC644\uB8CC\\" \uBB38\uAD6C\uAC00 \uB5A0\uB3C4 \uC2E4\uC81C \uC2DC\uAC04\uC774 \uAE30\uB85D\uB410\uB294\uC9C0 \uBC18\uB4DC\uC2DC \uD655\uC778! \uC804\uC0B0 \uC624\uB958\uB85C \uB204\uB77D\uB418\uB294 \uC0AC\uB840\uAC00 \uC788\uACE0, \uBBF8\uD655\uC778\uC740 \uBCF8\uC778 \uBD80\uC8FC\uC758\uB85C \uCC98\uB9AC\uB41C\uB2E4.\\n:::\\n\\n| \uD56D\uBAA9 | \uC2DC\uAC04 \uCC3D | \uBE44\uACE0 |\\n|------|---------|------|\\n| \uC785\uC2E4 QR | 08:50 ~ 09:10 | \uCC3D \uC678\uC5D0\uB294 \uBA58\uD1A0\uC5D0\uAC8C \uC694\uCCAD |\\n| \uD1F4\uC2E4 QR | 17:50 ~ 18:30 | \uC218\uC5C5 \uC9C0\uC5F0 \uACE0\uB824\uD574 \uAE38\uAC8C \uC5F4\uB9BC |\\n| \uC0C1\uC2DC QR | \uACE0\uC815 \uCC3D \uC678 | \uC694\uCCAD\uBC29 \uC591\uC2DD\uC73C\uB85C \uC2E0\uCCAD |\\n\\n:::danger\\n**\uD574\uC678\uC5D0\uC11C QR \uCD9C\uC11D = \uBD80\uC815 \uCD9C\uACB0 = \uC989\uC2DC \uC81C\uC801** (\uCCAD\uAC15\uC740 \uAC00\uB2A5\uD558\uC9C0\uB9CC QR \uCCB4\uD06C\uB294 \uC808\uB300 \uC548 \uB428)\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `QR\uCCB4\uD06C` `\uAC15\uC758\uC2E4\uC785\uC7A5` `\uC785\uD1F4\uC2E4\uC2DC\uAC04\uD655\uC778` `\uC0C1\uC2DCQR` `\uD574\uC678\uCD9C\uC11D\uAE08\uC9C0`\\n\\n---\\n\\n## 4\uFE0F\u20E3 \uC9C0\uAC01 / \uC870\uD1F4 / \uC678\uCD9C / \uACB0\uC11D \uADDC\uCE59\\n\\n### \uD575\uC2EC: 50% \uADDC\uCE59\\n\\n\uD558\uB8E8 \uC218\uC5C5\uC758 **50% \uBBF8\uB9CC \uC218\uAC15 = \uACB0\uC11D** \uCC98\uB9AC\uB41C\uB2E4.\\n\\n| \uAD6C\uBD84 | \uC778\uC815 \uC870\uAC74 | \uC8FC\uC758\uC810 |\\n|------|----------|--------|\\n| \uACB0\uC11D | QR \uBBF8\uCCB4\uD06C or 50% \uBBF8\uB9CC \uC218\uAC15 | \uC77C\uBD80 \uCC38\uC5EC\uD574\uB3C4 \uACB0\uC11D \uB420 \uC218 \uC788\uC74C |\\n| \uC9C0\uAC01 | \uC2DC\uC791 \uD6C4 50% \uC774\uB0B4 \uC785\uC2E4 | QR\uB9CC \uCC0D\uACE0 \uC785\uC2E4 \uB2A6\uC73C\uBA74 \uC9C0\uAC01 |\\n| \uC870\uD1F4 | 50% \uC774\uC0C1 \uC218\uAC15 \uD6C4 \uC911\uAC04 \uD1F4\uC2E4 | 50% \uBBF8\uB9CC\uC774\uBA74 \uACB0\uC11D \uCC98\uB9AC |\\n| \uC678\uCD9C | \uC678\uCD9C QR \u2192 \uBCF5\uADC0 QR \uC808\uCC28 \uC644\uB8CC | \uB450 QR \uBAA8\uB450 \uCC0D\uC5B4\uC57C \uD568 |\\n\\n### \uB204\uC801 \uADDC\uCE59\\n\\n:::warning\\n\uC9C0\uAC01 + \uC870\uD1F4 + \uC678\uCD9C **\uAC01\uAC01 3\uD68C \uB204\uC801 = \uACB0\uC11D 1\uD68C**\\n\\n\uD558\uB8E8\uC5D0 \uC9C0\uAC01 + \uC678\uCD9C + \uC870\uD1F4 \uBAA8\uB450 \uD558\uBA74 \u2192 \uD558\uB8E8\uC5D0 3\uD68C \uB204\uC801 \uAC00\uB2A5\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `50%\uADDC\uCE59` `\uC9C0\uAC01` `\uC870\uD1F4` `\uC678\uCD9C` `\uB204\uC8013\uD68C\uACB0\uC11D`\\n\\n---\\n\\n## 5\uFE0F\u20E3 \uACF5\uACB0(\uCD9C\uC11D \uC778\uC815) & \uCD9C\uACB0 \uC815\uC815\\n\\n### \uACF5\uACB0 \uAC00\uB2A5 \uC0AC\uC720\\n\\n\uAD6D\uAC00\uC2DC\uD5D8, \uC608\uBE44\uAD70/\uBBFC\uBC29\uC704, \uC9C8\uBCD1/\uC785\uC6D0, \uACBD\uC870\uC0AC, \uBA74\uC811 \uB4F1\\n\\n:::warning\\n**\uC9C8\uBCD1 \uACF5\uACB0\uC740 \uD6C8\uB828\uC77C\uC218\uC758 10%\uAE4C\uC9C0\uB9CC \uAC00\uB2A5** (121\uC77C \uACFC\uC815 \uAE30\uC900 \uC57D 12\uD68C)\\n\\n\uCD08\uBC18\uC5D0 \uACBD\uBBF8\uD55C \uC0AC\uC720\uB85C \uC18C\uC9C4\uD558\uBA74 \uB098\uC911\uC5D0 \uBABB \uC500 \u2014 \uC804\uB7B5\uC801\uC73C\uB85C \uC0AC\uC6A9\uD560 \uAC83\\n:::\\n\\n### \uC99D\uBE59 \uC11C\uB958 \uC694\uAC74\\n\\n| \uACF5\uACB0 \uC720\uD615 | \uD544\uC218 \uC11C\uB958 | \uD575\uC2EC \uC694\uAC74 |\\n|----------|----------|----------|\\n| \uC9C8\uBCD1/\uC785\uC6D0 | \uC9C4\uB8CC\uD655\uC778\uC11C + \uCC98\uBC29\uC804 + \uACB0\uC81C\uC601\uC218\uC99D | **\uC9C8\uBCD1\uCF54\uB4DC \uAE30\uC7AC \uD544\uC218** |\\n| \uBA74\uC811 | \uB0A0\uC778\uB41C \uBA74\uC811\uD655\uC778\uC11C + \uC5F0\uB77D\uB0B4\uC5ED + \uAD6C\uC778\uACF5\uACE0 | \uAE30\uC5C5 \uD655\uC778 \uC804\uD654 \uC62C \uC218 \uC788\uC74C |\\n\\n:::danger\\n\uBBF8\uC6A9, \uAC74\uAC15\uAC80\uC9C4, \uC2A4\uCF00\uC77C\uB9C1 \u2192 \uC9C8\uBCD1 \uACF5\uACB0 \uBD88\uC778\uC815\\n:::\\n\\n- \uC81C\uCD9C \uAE30\uD55C: \uC0AC\uC720 \uBC1C\uC0DD \uD6C4 **3\uC77C \uC774\uB0B4**\\n- \uC2E0\uCCAD \uC704\uCE58: **\uAD50\uC721\uD589\uC815 \uB514\uC2A4\uCF54\uB4DC** (\uD504\uB85C\uD544 \uC2E4\uBA85 \uC124\uC815 \uD544\uC218)\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uACF5\uACB0\uC2E0\uCCAD` `\uC9C8\uBCD1\uCF54\uB4DC` `\uC99D\uBE59\uC11C\uB958` `\uC81C\uCD9C\uAE30\uD55C` `\uAD50\uC721\uD589\uC815\uB514\uC2A4\uCF54\uB4DC`\\n\\n---\\n\\n## 6\uFE0F\u20E3 \uC218\uAC15 \uC7A5\uC18C \uADDC\uC815\\n\\n\uC624\uC804/\uC624\uD6C4 QR\uC740 \uB3D9\uC77C\uD55C \uC7A5\uC18C\uC5D0\uC11C \uCC0D\uB294 \uAC8C \uC6D0\uCE59. \uBD88\uAC00\uD53C\uD558\uAC8C \uC774\uB3D9\uD560 \uACBD\uC6B0 **\uC7A5\uC18C \uC774\uB3D9 \uD655\uC778\uC11C** \uC0AC\uC804 \uC81C\uCD9C \uD544\uC218.\\n\\n| \uACF5\uAC04 \uC720\uD615 | \uAC00\uB2A5 \uC5EC\uBD80 | \uC774\uC720 |\\n|----------|----------|------|\\n| 1\uC778 \uB8F8\uCE74\uD398 / 1\uC778 \uC2A4\uD130\uB514\uB8F8 | \u2705 \uC870\uAC74\uBD80 \uAC00\uB2A5 | \uC18C\uC74C \uD1B5\uC81C, \uB2E8\uB3C5 \uACF5\uAC04 |\\n| \uB3C5\uC11C\uC2E4 | \u2705 \uBE44\uAD50\uC801 \uAC00\uB2A5 | \uACE0\uC815 \uC88C\uC11D, \uC800\uC18C\uC74C |\\n| \uB3C4\uC11C\uAD00 | \u26A0\uFE0F \uC9C0\uC591 | \uC624\uD508 \uACF5\uAC04, \uC774\uB3D9 \uC778\uC6D0 \uB178\uCD9C |\\n| \uC77C\uBC18 \uCE74\uD398/\uC74C\uC2DD\uC810 | \u274C \uBD88\uAC00\uC5D0 \uAC00\uAE4C\uC6C0 | \uBD80\uC815 \uCD9C\uACB0 \uD310\uB2E8 \uAC00\uB2A5\uC131 \uD07C |\\n\\n:::warning\\n\uC7A5\uC18C \uC774\uB3D9\uC740 **\uC26C\uB294 \uC2DC\uAC04 / \uC810\uC2EC\uC2DC\uAC04\uC5D0\uB9CC** \uAC00\uB2A5. \uC218\uC5C5 \uC911 \uC774\uB3D9 = \uBB34\uB2E8\uC774\uD0C8\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC7A5\uC18C\uC774\uB3D9\uD655\uC778\uC11C` `\uC26C\uB294\uC2DC\uAC04\uC774\uB3D9` `\uC624\uD508\uACF5\uAC04\uC81C\uD55C` `\uBD80\uC815\uCD9C\uACB0` `\uC218\uAC15\uD658\uACBD`\\n\\n---\\n\\n## 7\uFE0F\u20E3 \uC81C\uC801 & \uC218\uB8CC \uAE30\uC900\\n\\n### \uC218\uB8CC \uC870\uAC74\\n\\n- **\uCD9C\uC11D\uB960 80% \uC774\uC0C1** + **\uD504\uB85C\uC81D\uD2B8 \uACB0\uACFC\uBB3C** \uD544\uC218\\n- \uACB0\uC11D\uC774 \uC804\uCCB4\uC758 20% \uCD08\uACFC \uC2DC \uC81C\uC801 \uB300\uC0C1\\n\\n### \uACBD\uACE0 \uB2E8\uACC4\\n\\n1\uCC28 \uC11C\uBA74 \uACBD\uACE0 \u2192 2\uCC28 \uC0C1\uB2F4 + \uD655\uC778\uC11C/\uC11C\uC57D\uC11C \u2192 3\uCC28 \uAC1C\uC120 \uBBF8\uD761 \uC2DC **\uC81C\uC801**\\n\\n:::danger\\n**\uBD80\uC815 \uCD9C\uACB0\uC740 \uD69F\uC218 \uBB34\uAD00 \uC989\uC2DC \uC81C\uC801**\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC218\uB8CC80%` `\uC81C\uC801\uAE30\uC900` `\uBD80\uC815\uCD9C\uACB0` `\uACBD\uACE0\uC81C\uB3C4` `\uD504\uB85C\uC81D\uD2B8\uACB0\uACFC\uBB3C`\\n\\n---\\n\\n## 8\uFE0F\u20E3 \uD6C8\uB828\uC7A5\uB824\uAE08 & \uD589\uC815 \uCC98\uB9AC\\n\\n- \uC9C0\uAE09 \uC870\uAC74: \uB2E8\uC704\uAE30\uAC04 **\uCD9C\uC11D 80% \uC774\uC0C1** + **HRD \uC218\uAC15\uD3C9 \uC791\uC131** (\uC885\uAC15 \uD6C4 1\uAC1C\uC6D4 \uC774\uB0B4)\\n- \uC9C0\uAE09\uC561: 1\uC77C 1\uB9CC5\uCC9C\uC6D0 \uAE30\uC900, **\uC6D4 \uCD5C\uB300 30\uB9CC\uC6D0** \uC0C1\uD55C\\n- \uACC4\uC88C \uD655\uC778: **\uACE0\uC6A924**\uC5D0\uC11C \uBCF8\uC778 \uB4F1\uB85D \uACC4\uC88C \uD655\uC778 \uD544\uC218\\n\\n:::warning\\n\uC218\uC5C5 \uC2DC\uAC04\uACFC \uACB9\uCE58\uB294 \uADFC\uB85C\uB294 \uBD88\uAC00. \uADFC\uB85C \uC911 QR \uCD9C\uC11D = \uBD80\uC815 \uCD9C\uACB0\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD6C8\uB828\uC7A5\uB824\uAE08` `\uACE0\uC6A9\uD615\uD0DC\uBCC0\uACBD` `\uACE0\uC6A924` `HRD\uC218\uAC15\uD3C9` `\uC11C\uB958\uC694\uCCAD`\\n\\n---\\n\\n## 9\uFE0F\u20E3 \uCEE4\uB9AC\uC5B4 OT \u2014 \uBAA9\uD45C \uC218\uCE58\uD654\\n\\n\uCDE8\uC5C5 \uC900\uBE44\uB294 \uC624\uB298\uBD80\uD130 \uC2DC\uC791\uC774\uB77C\uB294 \uAD00\uC810\uC73C\uB85C \uC9C4\uD589\uB410\uB2E4. \uD575\uC2EC\uC740 **\uBAA9\uD45C\uB97C \uC218\uCE58\uD654**\uD558\uB294 \uAC83.\\n\\n| \uB098\uC05C \uC608 | \uC88B\uC740 \uC608 |\\n|---------|---------|\\n| \uBE14\uB85C\uADF8 \uC4F0\uAE30 | \uC8FC 3\uD68C \uAE30\uC220 \uAE00 1\uD3B8 \uBC1C\uD589 |\\n| \uC774\uB825\uC11C \uC4F0\uAE30 | \uC218\uB8CC 2\uB2EC \uC804 \uCD08\uC548 \uC644\uC131 + \uCCA8\uC0AD 3\uD68C \uC774\uC0C1 |\\n| \uCF54\uD14C \uC900\uBE44\uD558\uAE30 | \uC8FC 3\uD68C \uBB38\uC81C \uD480\uACE0 \uC624\uB2F5 \uC815\uB9AC |\\n| \uD504\uB85C\uC81D\uD2B8 \uD574\uBCF4\uAE30 | \uD504\uB85C\uC81D\uD2B8 2\uAC1C \uAD6C\uC131 + \uBC30\uD3EC\uAE4C\uC9C0 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD22C\uB450\uB9AC\uC2A4\uD2B8` `\uAC1C\uC778\uCC4C\uB9B0\uC9C0` `\uD300\uCC4C\uB9B0\uC9C0` `\uBAA9\uD45C\uC218\uCE58\uD654` `\uC18C\uADF8\uB8F9\uD65C\uB3D9`\\n\\n---\\n\\n## \u{1F51F} \uCDE8\uC5C5\uC9C0\uC6D0 \uD504\uB85C\uADF8\uB7A8\\n\\n| \uD504\uB85C\uADF8\uB7A8 | \uB0B4\uC6A9 |\\n|---------|------|\\n| \uC138\uB81D\uAC8C\uD2F0 \uCEE4\uBBA4\uB2C8\uD2F0 | \uB514\uC2A4\uCF54\uB4DC \uAE30\uBC18 \uCDE8\uC5C5 \uC815\uBCF4 + \uD611\uC57D \uAE30\uC5C5 \uACF5\uACE0 |\\n| 1:1 \uC0C1\uB2F4/\uCCA8\uC0AD | \uC774\uB825\uC11C, \uC790\uC18C\uC11C, \uBA74\uC811, \uD3EC\uD2B8\uD3F4\uB9AC\uC624 \uCF54\uCE6D |\\n| \uBA38\uC0AC \uB85C\uCF13\uB2E8 | \uC778\uD134\uC2ED\uD615 \uC2E4\uBB34 \uACBD\uD5D8 (\uC8FC5\uC77C, \uC77C3\uC2DC\uAC04, 4\uC8FC) |\\n| \uB2E8\uAE30 \uADFC\uBB34 | \uB3D9\uC77C \uC9C1\uC885 \uACBD\uB825 \uC778\uC815, \uC774\uC9C1/\uC5F0\uBD09 \uD611\uC0C1 \uC720\uB9AC |\\n| \uC0AC\uC5C5\uC790 \uB4F1\uB85D \uC9C0\uC6D0 | \uBE44\uC0C1\uC8FC \uC624\uD53C\uC2A4 \uC784\uB300\uCC28 \uACC4\uC57D\uC11C \uBE44\uC6A9 6\uAC1C\uC6D4 \uC804\uC561 \uC9C0\uC6D0 |\\n\\n:::info\\n\uCDE8\uC5C5\uC9C0\uC6D0 \uAE30\uAC04: **\uC218\uAC15 6\uAC1C\uC6D4 + \uC218\uB8CC \uD6C4 6\uAC1C\uC6D4 = \uCD1D 1\uB144**\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC138\uB81D\uAC8C\uD2F0\uCEE4\uBBA4\uB2C8\uD2F0` `\uCDE8\uC5C5\uC0C1\uB2F4` `\uC11C\uB958\uCCA8\uC0AD` `\uB85C\uCF13\uB2E8` `\uC0AC\uC5C5\uC790\uB4F1\uB85D\uC9C0\uC6D0`\\n\\n---\\n\\n## \u2705 \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. QR \uCC0D\uACE0 **\uC2DC\uAC04 \uAE30\uB85D\uAE4C\uC9C0** \uD655\uC778\uD558\uC790 (\uCCB4\uD06C \uC644\uB8CC \uBBFF\uC9C0 \uB9D0 \uAC83)\\n2. **50% \uADDC\uCE59** \u2014 \uC808\uBC18 \uC774\uC0C1 \uC218\uAC15\uD574\uC57C \uC9C0\uAC01/\uC870\uD1F4\uB85C \uC778\uC815\\n3. \uC9C0\uAC01/\uC870\uD1F4/\uC678\uCD9C **\uB204\uC801 3\uD68C = \uACB0\uC11D 1\uD68C**\\n4. \uC9C8\uBCD1 \uACF5\uACB0\uC740 **\uC9C8\uBCD1\uCF54\uB4DC \uD3EC\uD568 \uC11C\uB958** \uD544\uC218, \uCD1D 12\uD68C \uD55C\uB3C4\\n5. \uBD80\uC815 \uCD9C\uACB0\uC740 **\uC989\uC2DC \uC81C\uC801** \u2014 \uD574\uC678 QR \uC808\uB300 \uAE08\uC9C0\\n6. \uBAA9\uD45C\uB294 **\uC218\uCE58\uD654** \u2014 \\"\uC774\uB825\uC11C \uC4F0\uAE30\\" \uB9D0\uACE0 \\"\uC218\uB8CC 2\uB2EC \uC804 \uCD08\uC548 \uC644\uC131\\""}]}}')}}]);